using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, b;
    cin >> n >> b;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> bal(n);
    for (int i = 0; i < n; ++i) {
        if (i == 0) {
            bal[i] = (a[i] % 2 == 0) ? 1 : -1;
        } else {
            bal[i] = bal[i - 1] + ((a[i] % 2 == 0) ? 1 : -1);
        }
    }

    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 1; i < n - 1; ++i) {
        if (bal[i] == 0) {
            pq.push(abs(a[i + 1] - a[i]));
        }
    }

    int ans = 0;
    while (!pq.empty() && b >= pq.top()) {
        b -= pq.top();
        pq.pop();
        ++ans;
    }

    cout << ans << '\n';
    return 0;
}

