    public static void main(String[] args) throws IOException 
    {
        InputReader in=new InputReader(System.in);
        int n=in.nextInt();
        int b=in.nextInt();
        int [] a=new int[n];
        a=in.nextIntArray(n);
        int[] odd=new int[n+1];
        int[] even=new int[n+1];
        odd[0]=0;
        even[0]=0;
        for(int i=1;i<=n;i++)
        {
            if(a[i-1]%2==1)
            {
                odd[i]=odd[i-1]+1;
                even[i]=even[i-1];
            }
            else
            {
                odd[i]=odd[i-1];
                even[i]=even[i-1]+1;
            }
        }
        int prev=0;
        PriorityQueue<Integer> cost=new PriorityQueue<Integer>();
        for(int i=1;i<=n-1;i++)
        {
            int oc=odd[i]-odd[prev];
            int ec=even[i]-even[prev];
            if(oc==ec)
            {
