public:
    InputReader(FILE* st) : stream(st), curChar(0), snumChars(0) {}

    int read() {
        if (snumChars == -1)
            throw "InputMismatchException";
        if (curChar >= snumChars) {
            curChar = 0;
            snumChars = fread(buf, 1, 8192, stream);
            if (snumChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    int nextInt() {
        int c = read();
        while (isspace(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isspace(c) && c != -1);
        return res * sgn;
    }

    long long nextLong() {
        int c = read();
        while (isspace(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long long res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isspace(c) && c != -1);
        return res * sgn;
    }

    vector<int> nextIntArray(int n) {
        vector<int> a(n);
        for (int i = 0; i < n; ++i)
            a[i] = nextInt();
        return a;
    }

    string readString() {
        int c = read();
        while (isspace(c))
            c = read();
        string res;
        do {
            res.push_back(static_cast<char>(c));
            c = read();
        } while (!isspace(c) && c != -1);
        return res;
    }

    string nextLine() {
