        while (isspace(c))
            c = read();
        string res;
        do {
            res.push_back(static_cast<char>(c));
            c = read();
        } while (c != '\n' && c != '\r' && c != -1);
        return res;
    }

private:
    static bool isspace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
};

