        int[] even = new int[n + 1];

        for (int i = 1; i <= n; i++)
        {
            if ((a[i - 1] & 1) == 1)
            {
                odd[i] = odd[i - 1] + 1;
                even[i] = even[i - 1];
            }
            else
            {
                odd[i] = odd[i - 1];
                even[i] = even[i - 1] + 1;
            }
        }

        List<Integer> costs = new ArrayList<Integer>();
        int prev = 0;

        for (int i = 1; i < n; i++)
        {
            if (odd[i] - odd[prev] == even[i] - even[prev])
            {
                costs.add(Math.abs(a[i] - a[i - 1]));
                prev = i;
            }
        }

        Collections.sort(costs);
        int total = 0;
        int ans = 0;

        for (int c : costs)
        {
            if (total + c > b) break;
            total += c;
            ans++;
        }

        System.out.println(ans);
    }
}

