                pos++;
            }

            int num = 0;
            while (pos < data.length && !isSpace(data[pos]))
            {
                num = num * 10 + (data[pos] - '0');
                pos++;
            }
            return num * sign;
        }
    }

    public static void main(String[] args) throws IOException
    {
