using namespace std;

// Fast input reader similar to Java's InputReader
class FastInput {
public:
    FastInput() {
        buf = new char[1024];
        curChar = 0;
        numChars = 0;
        stream = stdin;
    }
    ~FastInput() {
        delete[] buf;
    }
    int read() {
        if (numChars == -1) return -1;
        if (curChar >= numChars) {
            curChar = 0;
            numChars = fread(buf, 1, 1024, stream);
            if (numChars <= 0) return -1;
        }
        return buf[curChar++];
    }
    int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw runtime_error("InputMismatchException");
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }
private:
    FILE* stream;
    char* buf;
    int curChar;
    int numChars;
    bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    FastInput in;
    int n = in.nextInt();
    int b = in.nextInt();
    vector<int> arr1(n);
    for (int i = 0; i < n; ++i) {
        arr1[i] = in.nextInt();
    }
    vector<int> pf1(n), pf2(n);
    int sum1 = 0, sum2 = 0;
    for (int i = 0; i < n; ++i) {
        if (arr1[i] % 2 == 0)
            ++sum1;
        else
            ++sum2;
        pf1[i] = sum1;
        pf2[i] = sum2;
    }
    int prev = 0;
    vector<int> arr(n); // will be resized later
    int p = 0;
    for (int i = 1; i < n - 2; i += 2) {
        int x, y;
        if (prev == 0) {
            x = pf1[i];
            y = pf2[i];
        } else {
            x = pf1[i] - pf1[prev];
            y = pf2[i] - pf2[prev];
        }
        if (x == y) {
            arr[p] = abs(arr1[i + 1] - arr1[i]);
            ++p;
        }
    }
    vector<int> val(p, 1);
    // 0/1 knapsack DP
    vector<vector<int>> K(p + 1, vector<int>(b + 1, 0));
    for (int i = 0; i <= p; ++i) {
        for (int w = 0; w <= b; ++w) {
            if (i == 0 || w == 0)
                K[i][w] = 0;
            else if (arr[i - 1] <= w)
                K[i][w] = max(val[i - 1] + K[i - 1][w - arr[i - 1]], K[i - 1][w]);
            else
                K[i][w] = K[i - 1][w];
        }
    }
    cout << K[p][b] << '\n';
    return 0;
}

