using namespace std;

int main() {
    // Read all input lines and join with spaces
    string all;
    string line;
    while (getline(cin, line)) {
        all += line + " ";
    }

    // Parse integers from the joined string
    stringstream ss(all);
    vector<int> nums;
    int num;
    while (ss >> num) {
        nums.push_back(num);
    }

    // First two numbers: n and b
    int n = nums[0];
    int b = nums[1];

    // Next n numbers: array a
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        a[i] = nums[2 + i];
    }

    // Prefix counts of even and odd numbers
    vector<int> pe(n), po(n);
    int even = 0, odd = 0;
    for (int i = 0; i < n; ++i) {
        if ((a[i] & 1) == 0) even++;
        else odd++;
        pe[i] = even;
        po[i] = odd;
    }

    // Compute weights: indices i from 1 to n-3 inclusive where i is odd and pe[i]==po[i]
    vector<int> w;
    for (int i = 1; i < n - 2; ++i) {
        if ((i & 1) == 1 && pe[i] == po[i]) {
            w.push_back(abs(a[i + 1] - a[i]));
        }
    }

    // 0/1 knapsack: maximize number of cuts with total cost <= b
    vector<int> dp(b + 1, 0);
    for (int weight : w) {
        for (int cap = b; cap >= weight; --cap) {
            dp[cap] = max(dp[cap], dp[cap - weight] + 1);
        }
    }

    cout << dp[b] << endl;

    return 0;
}

