import java.util.*;
public class Cutting
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int b = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = sc.nextInt();
        int count = 0, sum = 0, odd = 0, even = 0;
        ArrayList<Integer> al = new ArrayList<>();
        for (int i = 0; i < n; i++)
        {
            if ((a[i] & 1) == 1)
                odd++;
            else
                even++;
            if (i != n - 1)
            {
                if (odd == even)
                    al.add(Math.abs(a[i + 1] - a[i]));
            }
        }
        Collections.sort(al);
        for (Integer val : al)
        {
            sum += val;
            if (sum <= b)
                count++;
            else
                break;
        }
        System.out.println(count);
    }
}

