import java.io.*;
import java.util.*;

public class CF998B {
    static class FastScanner {
        private BufferedInputStream in = new BufferedInputStream(System.in);
        private int nextInt() throws IOException {
            int c;
            do {
                c = in.read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = in.read();
            }
            int val = 0;
            while (c > ' ' && c != -1) {
                val = val * 10 + (c - '0');
                c = in.read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int w = fs.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
        }
        ArrayList<Integer> cuts = new ArrayList<Integer>();
        int even = 0;
        int odd = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) even++;
            else odd++;
            if (even == odd) cuts.add(Math.abs(a[i] - a[i + 1]));
        }
        List<Integer> dp = new ArrayList<Integer>(Collections.nCopies(w + 1, 0));
        for (int cost : cuts) {
            for (int j = w; j >= 1; j--) {
                if (cost <= j) {
                    int with = dp.get(j - cost) + 1;
                    if (with > dp.get(j)) {
                        dp.set(j, with);
                    }
                }
            }
        }
        PrintWriter out = new PrintWriter(System.out);
        out.println(dp.get(w));
        out.close();
    }
}

