    for (int i = 100; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int n, B;
    cin >> n >> B;
    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    int buckets[101] = {0};
    int sum = 0;
    int evens = 0;
    int odds = 0;
    int start = 0;
    int count = 0;
    int k = 1;

    int i = 0;
    while (i < n - 1) {
        if (arr[i] % 2 == 0) {
            evens++;
        } else {
            odds++;
        }

        if (evens == odds) {
            int diff = abs(arr[i + 1] - arr[i]);
            int max = bucketMax(buckets);
            if (sum > B && diff < max) {
                sum -= max;
                buckets[max]--;
                buckets[diff]++;
                sum += diff;
            } else if (sum < B) {
                sum += diff;
                buckets[diff]++;
                count++;
                start = i + 1;
            }
            if (i == n - 2 && k < n - 1) {
                i = start;
                i++; // simulate for loop increment after continue
                evens = 0;
                odds = 0;
                continue;
            }
        }
        i++;
    }

    int j = 100;
    while (sum > B) {
        if (buckets[j] > 0) {
            sum -= j;
            count--;
        } else {
            j--;
        }
    }

    cout << count << endl;
    return 0;
}

