        ArrayList<Integer> al = new ArrayList<>();
        for(int i=0;i<n;i++){
            if(i!=0){
                if(even == odd){
                    al.add(Math.abs(arr[i]-arr[i-1]));
                }
            }
            if(arr[i]%2 == 0){
                even++;
            }
            else{
                odd++;
            }
        }
        Collections.sort(al);
        int count = 0;
        for(int i=0;i<al.size();i++){
            int element = al.get(i);
            if(element<=k){
                count++;
                k-=element;
            }
            else{
                break;
            }
        }
        System.out.println(count);
