    int n2 = r - q;
    long long L[n1 + 1], R[n2 + 1];
    int L1[n1 + 1], R1[n2 + 1];

    for (int i = 0; i < n1; i++) {
        L[i] = a[p + i];
        L1[i] = b[p + i];
    }
    for (int i = 0; i < n2; i++) {
        R[i] = a[q + 1 + i];
        R1[i] = b[q + 1 + i];
    }
    L[n1] = R[n2] = INF;
    L1[n1] = R1[n2] = INF;

    for (int k = p, i = 0, j = 0; k <= r; k++) {
        if (L[i] <= R[j]) {
            a[k] = L[i];
            b[k] = L1[i++];
        } else {
            a[k] = R[j];
            b[k] = R1[j++];
        }
    }
}

void mergeSort(int a[], int b[], int c[], int p, int r) {
    if (p < r) {
        int q = (p + r) >> 1;
        mergeSort(a, b, c, p, q);
        mergeSort(a, b, c, q + 1, r);
        merge(a, b, c, p, q, r);
    }
}

void merge(int a[], int b[], int c[], int p, int q, int r) {
    int n1 = q - p + 1;
    int n2 = r - q;
    int L[n1 + 1], R[n2 + 1];
    int L1[n1 + 1], R1[n2 + 1];
    int L2[n1 + 1], R2[n2 + 1];

    for (int i = 0; i < n1; i++) {
        L[i] = a[p + i];
        L1[i] = b[p + i];
        L2[i] = c[p + i];
    }
    for (int i = 0; i < n2; i++) {
        R[i] = a[q + 1 + i];
        R1[i] = b[q + 1 + i];
        R2[i] = c[q + 1 + i];
    }
    L[n1] = R[n2] = INF;
    L1[n1] = R1[n2] = INF;
    L2[n1] = R2[n2] = INF;
    int j = 0, k = 0;
    for (int i = p; i <= r; i++) {
        if (L[j] < R[k]) {
            a[i] = L[j];
            b[i] = L1[j];
            c[i] = L2[j++];
        } else if (L[j] > R[k]) {
            a[i] = R[k];
            b[i] = R1[k];
            c[i] = R2[k++];
        } else {
            if (L1[j] > R1[k]) {
                a[i] = L[j];
                b[i] = L1[j];
                c[i] = L2[j++];
            } else {
                a[i] = R[k];
                b[i] = R1[k];
                c[i] = R2[k++];
            }
        }
    }
}

int* sieve(int n) {
    int* a = new int[n + 1];
    for (int i = 2; i <= n; i++) a[i] = 1;
    for (int i = 2; i <= sqrt(n); i++) {
        if (a[i] == 1) {
            for (int k = 2; i * k <= n; k++) {
                a[i * k] = 0;
            }
        }
    }
    return a;
}

