vector<int> gd(int a, int b) {
    int m = (int)gcd(a, b);
    vector<int> q;
    for (int i = 1; i * i <= m; ++i) {
        if (m % i == 0) {
            q.push_back(i);
            if (i != m / i) q.push_back(m / i);
        }
    }
    return q;
}

