            while (isSpace(c)) {
                if (c == -1) throw new InputMismatchException();
                c = in.read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = in.read();
            }
            int res = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = in.read();
            }
            return res * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int k = fs.nextInt();
