public class Cutting {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        int B = s.nextInt();

        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextInt();
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int balance = 0;

        for (int i = 0; i < n; i++) {
            balance += (arr[i] % 2 == 0) ? 1 : -1;

            if (balance == 0 && i < n - 1) {
                pq.add(Math.abs(arr[i] - arr[i + 1]));
            }
        }

        int cuts = 0;
        while (!pq.isEmpty() && B >= pq.peek()) {
            B -= pq.poll();
            cuts++;
        }

        System.out.println(cuts);
    }
}

