public class Main {
    static class FastScanner {
        private BufferedInputStream in;
        private int c;

        FastScanner() {
            in = new BufferedInputStream(System.in);
        }

        private int read() {
            try {
                return in.read();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int num = 0;
            while (c > ' ') {
                num = num * 10 + (c - '0');
                c = read();
            }
            return neg ? -num : num;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int b = fs.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
        }

        int[] costs = new int[n];
        int size = 0;
        int even = 0;
        int odd = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) {
                even++;
            } else {
                odd++;
            }
            if (even == odd) {
                costs[size++] = Math.abs(a[i + 1] - a[i]);
            }
        }

        Arrays.sort(costs, 0, size);
        int sum = 0;
        int ans = 0;
        for (int i = 0; i < size; i++) {
            sum += costs[i];
            if (sum <= b) {
                ans = i + 1;
            }
        }
        System.out.println(ans);
    }
}

