                .mapToInt(Integer::parseInt)
                .toArray();

        int n = data[0];
        int b = data[1];
        int[] a = Arrays.copyOfRange(data, 2, 2 + n);

        int[] dp = new int[n];
        int idx = 1;
        int balance = 0;
        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 0) {
                balance--;
            } else {
                balance++;
            }
            if (balance == 0) {
                dp[idx++] = Math.abs(a[i + 1] - a[i]);
            }
        }

        Arrays.sort(dp, 0, idx);
        Arrays.parallelPrefix(dp, 0, idx, Integer::sum);

        int ans = 0;
        for (int i = 1; i < idx; i++) {
            if (dp[i] <= b) {
                ans = i;
            }
        }
        System.out.println(ans);
    }
}

