        while (c != EOF && isspace(c)) {
            c = getchar();
        }
        if (c == EOF) {
            return 0; // Should not happen in valid input
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = getchar();
        }
        int res = 0;
