        for (int i = 1; i < a.length; i++) {
            int cost = Math.abs(a[i] - a[i - 1]);
            if (odds == evens && cost <= b) {
                evens = 0;
                odds = 0;
                costs[len++] = cost;
            }
            if (a[i] % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
        }

        for (int i = 1; i < len; i++) {
            int value = costs[i];
            int j = i - 1;
            while (j >= 0 && costs[j] > value) {
                costs[j + 1] = costs[j];
                j--;
            }
            costs[j + 1] = value;
        }

        for (int i = 0; i < len; i++) {
            if (b < costs[i]) {
