            if (current % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
            i++;
        }

        costs.sort(null);

        int remaining = b;
        for (int cost : costs) {
            if (remaining < cost) {
                break;
            }
            cuts++;
            remaining -= cost;
        }
        return cuts;
