import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int b = scanner.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
        }
        System.out.println(answer(arr, b));
    }

    private static int answer(int[] arr, int b) {
        PriorityQueue<Integer> costs = new PriorityQueue<>();
        int numsEven = arr[0] % 2 == 0 ? 1 : 0;
        int numsOdd = arr[0] % 2 == 1 ? 1 : 0;

        for (int i = 1; i < arr.length; i++) {
            int cost = Math.abs(arr[i] - arr[i - 1]);
            if (numsOdd == numsEven && cost <= b) {
                numsOdd = 0;
                numsEven = 0;
                costs.add(cost);
            }
            if (arr[i] % 2 == 0) {
                numsEven++;
            } else {
                numsOdd++;
            }
        }

        int cuts = 0;
        while (!costs.isEmpty() && costs.peek() <= b) {
            b -= costs.poll();
            cuts++;
        }
        return cuts;
    }
}

