vector<int> strToIntArr(const string& s) {
    vector<int> ret;
    stringstream ss(s);
    int num;
    while (ss >> num) {
        ret.push_back(num);
    }
    return ret;
}

bool checkSub(const vector<int>& aArr, int splitInd) {
    int nEven = 0, nOdd = 0;
    for (int i = 0; i <= splitInd; ++i) {
        if ((aArr[i] & 1) == 0) ++nEven;
        else ++nOdd;
    }
    return nEven == nOdd;
}

int getMaxCuts(int n, int b, const vector<int>& aArr) {
    // priority queue of pairs (cost, index), sorted by cost ascending, then index ascending
    auto cmp = [](const pair<int,int>& p, const pair<int,int>& q) {
        if (p.first != q.first) return p.first > q.first;
        return p.second > q.second;
    };
    priority_queue<pair<int,int>, vector<pair<int,int>>, decltype(cmp)> pq(cmp);

    for (int i = 1; i < (int)aArr.size() - 1; ++i) {
        if (checkSub(aArr, i)) {
            int cost = abs(aArr[i] - aArr[i+1]);
            pq.push({cost, i});
        }
    }

    int nCoins = b;
    int nCuts = 0;
    while (nCoins > 0 && !pq.empty()) {
        int cost = pq.top().first;
        if (cost >= nCoins + 1) break;
        pq.pop();
        nCoins -= cost;
        ++nCuts;
    }
    return nCuts;
}

