        for (int j = 0; j < (int)remaining.size(); ++j) {
            int idx = remaining[j];
            int cost = abs(aArr[idx] - aArr[idx + 1]);
            if (cost < bestCost) {
                bestCost = cost;
                bestPos = j;
            }
        }
        if (bestPos == -1) break;
        remaining.erase(remaining.begin() + bestPos);
        nCoins -= bestCost;
        nCuts++;
    }
    return nCuts;
}

