    static int[] memo;

    public static void main(String[] args) {
        InputStream is = System.in;
        OutputStream os = System.out;
        InputReader in = new InputReader(is);
        OutputWriter out = new OutputWriter(os);
        long a = in.readInt();
        long b = in.readInt();
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        long ans;
        if (a == 1) {
            long r = b % 6;
            if (r <= 3) ans = b - r;
            else if (r == 4) ans = b - 2;
            else ans = b - 1;
        } else if (a <= 5 && b <= 30) {
            N = (int) a;
            M = (int) b;
            STATES = 1 << (3 * N);
            memo = new int[(M + 1) * (N + 1) * STATES];
            Arrays.fill(memo, -1);
            ans = go(0, 0, 0);
        } else {
            ans = a * b - a * b % 2;
        }
        out.printLine(ans);
        out.close();
    }

    static int go(int row, int col, int mask) {
        int idx = ((row * (N + 1) + col) * STATES + mask);
        if (memo[idx] != -1) return memo[idx];
        int res;
        if (row == M) {
            res = mask == 0 ? 0 : Integer.MIN_VALUE;
        } else if (col == N) {
            res = go(row + 1, 0, mask);
        } else if ((mask & 1) == 1) {
            res = go(row, col + 1, mask >> 1);
        } else {
            res = go(row, col + 1, mask >> 1);
            res = Math.max(go(row, col + 1, (mask >> 1) + (1 << (3 * N - 1))) + 2, res);
            if (col != 0 && ((mask >> (2 * N - 1)) & 1) == 0) {
                res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (2 * N - 2))) + 2);
            }
            if (col != N - 1 && ((mask >> (2 * N + 1)) & 1) == 0) {
                res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (2 * N))) + 2);
            }
            if (col >= 2 && ((mask >> (N - 2)) & 1) == 0) {
                res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (N - 3))) + 2);
            }
            if (col < N - 1 && ((mask >> (N + 2)) & 1) == 0) {
                res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (N + 1))) + 2);
            }
        }
        memo[idx] = res;
        return res;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
