                if (max == 7L) return 12L;
                return min * max;
            }
            case 3: {
                if (max < 3L) return 0L;
                long product = min * max;
                return (max & 1L) == 1L ? product - 1L : product;
            }
            default:
                return 0L;
        }
    }
}

