        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long[] vals = Arrays.stream(br.readLine().split(" ")).mapToLong(Long::parseLong).toArray();
        if (vals[0] > vals[1]) {
            vals[0] ^= vals[1];
            vals[1] ^= vals[0];
            vals[0] ^= vals[1];
        }
        System.out.println(calculate(vals[0], vals[1]));
