    class Point {
        int x;
        int y;
        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }

        if (n == 1) {
            m--;
            int[] left = {0, 0, 0, 2, 4, 6};
            long res = m / 6 * 6 + left[m % 6];
            outln(res);
            return;
        }
        else if (n == 2) {
            if (m < 20) {
                outln(bruteforce(n, m));
            }
            else {
                outln(1L * n * m);
            }
            return;
        }
        else if (n == 3) {
            if (m < 20) {
                outln(bruteforce(n, m));
            }
            else {
                long res = 1L * n * m;
                if (res % 2 != 0) {
                    res--;
                }
                outln(res);
            }
            return;
        }

        if (1L * n * m < 1000) {
            outln(bruteforce(n, m));
            return;
        }
        long res = 1L * n * m;
        if (res % 2 != 0) {
            res--;
        }
        outln(res);
    }

    int bruteforce(int n, int m) {
        List<Point> even = new ArrayList<>();
        List<Point> odd = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
