public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        System.out.println(compute(n, m));
    }

    private static long compute(long n, long m) {
        if (n >= 4 && m >= 4) {
            if (n % 2 == 0 || m % 2 == 0) {
                return n * m;
            }
            return n * m - 1;
        }

        long min = Math.min(n, m);
        long max = Math.max(n, m);

        if (min == 1) {
            long rem = max % 6;
            long result = max - rem;
            if (rem == 4) result += 2;
            if (rem == 5) result += 4;
            return result;
        }

        if (min == 2) {
            if (max < 3) return 0;
            if (max == 3) return 4;
            if (max == 7) return 12;
            return 2L * max;
        }

        if (min == 3) {
            if (max < 3) return 0;
            long result = 3L * max;
            if (max % 2 == 1) --result;
            return result;
        }

        return 0;
    }
}

