    }

    private static long oneRow(long c) {
        long m = c % 6;
        if (m == 0) return c;
        if (m <= 3) return c - m;
        if (m == 4) return c - 2;
        return c - 1;
    }

    private static long twoRows(long c) {
        if (c == 3 || c == 7) return 2L * (c - 1);
        return 2L * c;
    }

    static class FS {
        BufferedReader br;
        StringTokenizer st;

        public FS() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw null;
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

