}

bool can(int cur, int r, int c) {
    if (cur > R * C / 2) {
        return true;
    }
    if (c >= C) {
        return can(cur, r + 1, 0);
    }
    if (grid[r][c] != 0) {
        return can(cur, r, c + 1);
