static vector<char> readAll(istream& in) {
    vector<char> buffer;
    char chunk[4096];
    while (in.read(chunk, sizeof(chunk)) || in.gcount() > 0) {
        streamsize read = in.gcount();
        buffer.insert(buffer.end(), chunk, chunk + read);
    }
    return buffer;
}

static long long solve(long long n, long long m) {
    if (n > m) {
        swap(n, m);
    }
    if (n == 1) {
        long long subtract[] = {0, 1, 2, 3, 2, 1};
        return m - subtract[m % 6];
    }
    if (n == 2) {
        if (m == 2) return 0;
        if (m == 3) return 4;
        if (m == 7) return 12;
        return m * 2;
    }
    return (n * m) & ~1LL;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<char> data = readAll(cin);
    string input(data.begin(), data.end());

    // Trim trailing whitespace
    while (!input.empty() && (input.back() == ' ' || input.back() == '\n' || input.back() == '\r' || input.back() == '\t')) {
        input.pop_back();
    }

    // Tokenize
    string token;
    vector<long long> tokens;
    for (char c : input) {
        if (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
            if (!token.empty()) {
                tokens.push_back(stoll(token));
                token.clear();
            }
        } else {
            token += c;
        }
    }
    if (!token.empty()) {
        tokens.push_back(stoll(token));
    }

    long long n = tokens[0];
    long long m = tokens[1];
    long long answer = solve(n, m);
    cout << answer << endl;

    return 0;
}

