    void fillBuf() {
        bufi = 0;
        bufc = 0;
        while (bufc == 0) {
            cin.read(buf, BUFSIZE);
            bufc = cin.gcount();
            if (bufc == 0) {
                bufc = 0;
                return;
            }
        }
    }

    bool pumpBuf() {
        if (bufi == bufc) fillBuf();
        return bufc != 0;
    }

    bool isDelimiter(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }

    void eatDelimiters() {
        while (true) {
            if (bufi == bufc) {
                fillBuf();
                if (bufc == 0) throw runtime_error("IO: Out of input.");
            }
            if (!isDelimiter(buf[bufi])) break;
            ++bufi;
        }
    }

public:
    IO() : bufc(0), bufi(0) {}

    string next() {
        sb.str("");
        sb.clear();
        eatDelimiters();
        int start = bufi;
        while (true) {
            if (bufi == bufc) {
                sb.write(buf + start, bufi - start);
                fillBuf();
                start = 0;
                if (bufc == 0) break;
            }
            if (isDelimiter(buf[bufi])) break;
            ++bufi;
        }
        sb.write(buf + start, bufi - start);
