    if (n == 2) {
        if (m < 3) io.println(0);
        else if (m == 3) io.println(4);
        else if (m == 7) io.println(12);
        else io.println(2 * m);
        return;
    }
    // general case solution:
    io.println(2 * (n * m / 2));
}

int main() {
    solve();
    return 0;
}

