import java.io.IOException;
import java.util.Scanner;

public class NekoAndAkiPrank {
    private final static long MOD = 1_000_000_007;
    private long[][] memo;
    private int n;

    public void solve() throws IOException {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        memo = new long[2 * n][n + 1];
        for (int i = 0; i < 2 * n; i++) {
            for (int k = 0; k <= n; k++) {
                memo[i][k] = -1;
            }
        }
        long tWays = 0;
        for (int i = 1; i < 2 * n; i += 2) {
            int limit = Math.min(i, 2 * n - i);
            for (int k = 0; k <= limit; k++) {
                tWays = (tWays + f(i, k)) % MOD;
            }
        }
        System.out.println(tWays);
    }

    private long f(int i, int k) {
        if (i == 0) {
            return (k == 0) ? 1 : 0;
        }
        if (memo[i][k] != -1) {
            return memo[i][k];
        }
        long res;
        if (k == 0) {
            res = f(i - 1, 1);
        } else if (k == n) {
            res = f(i - 1, n - 1);
        } else {
            res = (f(i - 1, k - 1) + f(i - 1, k + 1)) % MOD;
        }
        memo[i][k] = res;
        return res;
    }

    public static void main(String[] args) throws IOException {
        NekoAndAkiPrank solution = new NekoAndAkiPrank();
        solution.solve();
    }
}

