import java.util.*;
import java.io.*;

public class Main {
	public static void main(String args[]) {new Main().run();}

	FastReader in = new FastReader();
	PrintWriter out = new PrintWriter(System.out);
	void run(){
		work();
		out.flush();
	}
	long mod=1000000007;
	long gcd(long a,long b) {
		return a==0?b:b>a?gcd(b%a,a):gcd(b,a);
	}
	void work() {
		int n=in.nextInt();
		long[] dp=new long[2*n+1];
		long ret=0;
		dp[0]=1;
		for(int p=1;p<=2*n;p++) {
			long[] ndp=new long[2*n+1];
			for(int i=0;i<2*n;i++) {
				ndp[i+1]+=dp[i];
				ndp[i+1]%=mod;
				if(i-1>=0) {
					ndp[i-1]+=dp[i];
					ndp[i-1]%=mod;
					if(p%2==0) {
						int r=2*n-p;
						if(r>=i-1) {
							ret+=dp[i];
						}
					}
				}
			}
			ret%=mod;
			dp=ndp;
		}
		out.println(ret);
	}
}	



class FastReader
{
	BufferedReader br;
	StringTokenizer st;

	public FastReader()
	{
		br=new BufferedReader(new InputStreamReader(System.in));
	}


	public String next() 
	{
		if(st==null || !st.hasMoreElements())
		{
			try {
				st = new StringTokenizer(br.readLine());
			} catch (IOException e) {
				e.printStackTrace();
			}
		}
		return st.nextToken();
	}

	public int nextInt() 
	{
		return Integer.parseInt(next());
	}

	public long nextLong()
	{
		return Long.parseLong(next());
	}
}

