using namespace std;

typedef long long ll;
const ll MOD = 1000000007LL;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<ll> dp(2 * n + 1, 0);
    dp[0] = 1;
    ll ret = 0;

    for (int p = 1; p <= 2 * n; ++p) {
        vector<ll> ndp(2 * n + 1, 0);
        for (int i = 0; i < 2 * n; ++i) {
            ndp[i + 1] = (ndp[i + 1] + dp[i]) % MOD;
            if (i - 1 >= 0) {
                ndp[i - 1] = (ndp[i - 1] + dp[i]) % MOD;
                if (p % 2 == 0) {
                    int r = 2 * n - p;
                    if (r >= i - 1) {
                        ret = (ret + dp[i]) % MOD;
                    }
                }
            }
        }
        ret %= MOD;
        dp = move(ndp);
    }

    cout << ret << endl;
    return 0;
