        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        RollingSolver solver = new RollingSolver();
        solver.solve(1, in, out);
        out.close();
    }

    static class RollingSolver {
        static final int MOD = 1_000_000_007;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            out.print(calculate(n));
        }

        private int calculate(int n) {
            int size = 2 * n + 1;
            if (size < 0) {
                throw new NegativeArraySizeException();
            }
            int[] prevEven = new int[size];
            int[] prevOdd = new int[size];
            prevEven[0] = 1;

            for (int depth = 1; depth <= 2 * n; depth++) {
                int[] curEven = new int[size];
                int[] curOdd = new int[size];

                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    int sumEven = 0;
                    int sumOdd = 0;

                    if (opened > 0) {
                        sumEven += prevOdd[opened - 1];
                        sumOdd += prevEven[opened - 1];
                    }
                    if (opened + 1 < size) {
                        sumEven += prevOdd[opened + 1];
                        sumOdd += prevEven[opened + 1];
                    }

                    curEven[opened] = (sumEven + 1) % MOD;
                    curOdd[opened] = sumOdd % MOD;
