        int n = in.nextInt();
        int[][] dp = new int[n * 2][n + 1];
        dp[0][1] = 1;
        for (int i = 1; i < n * 2; i++)
            for (int j = 0; j <= n; j++) {
                if (j + 1 <= n) {
                    dp[i][j + 1] += dp[i - 1][j];
                    dp[i][j + 1] %= mod;
                }

                if (j - 1 >= 0) {
                    dp[i][j - 1] += dp[i - 1][j];
                    dp[i][j - 1] %= mod;
                }
            }

