            for (int j = 0; j <= n; j++)
                if (j <= 2 * n - 1 - i && j % 2 == 1) {
                    ans = (ans + dp[i][j]) % mod;
                    //System.err.println(i +" " + j + " " + ans);
                }

        out.print(ans);
    }


