    ll even = k / 2 + 1;
    ll odd = (k + 1) / 2;

    if ((n * m) % 2 == 1) {
        ll base = k + 1;
        ll exp = n * m;
        ll res = modPow(base, exp, MOD);
        cout << res;
    } else {
        ll a = even + odd;   // this equals k + 1
        ll b = even - odd;   // 0 or 1
        ll exp = n * m;
        ll temp1 = modPow(a, exp, MOD);
        ll temp2 = modPow(b, exp, MOD);
        ll sum = (temp1 + temp2) % MOD;
        ll factor = (MOD + 1) / 2;   // modular inverse of 2 modulo MOD
        ll ans = (sum * factor) % MOD;
        cout << ans << endl;
    }

