    if (ti % 2 == 0) {
        long long y = fastpow(n, ti / 2);
        long long k = (y * y) % MOD;
        return k;
    } else {
        long long y = fastpow(n, ti / 2);
        long long k = ((n % MOD) * y) % MOD;
        k = (k * y) % MOD;
        return k;
    }
