import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        EHeightAllTheSame solver = new EHeightAllTheSame();
        solver.solve(1, in, out);
        out.close();
    }

    static class EHeightAllTheSame {
        public void solve(int testNumber, FastReader s, PrintWriter out) {
            long n = s.nextLong(), m = s.nextLong(), k = n * m;
            long l = s.nextLong(), r = s.nextLong(), len = r - l + 1;
            long mod = 998244353L;

            if (k % 2 == 1) {
                out.println(powRec(len, k, mod));
                return;
            }

            long ans = (powRec(len, k, mod) + powRec(len % 2, k, mod)) * powRec(2, mod - 2, mod) % mod;
            out.println(ans);
        }

        private static long powRec(long x, long y, long p) {
            if (y == 0) return 1 % p;
            x %= p;
            long half = powRec(x, y / 2, p);
            half = (half * half) % p;
            if ((y & 1) == 1) half = (half * x) % p;
            return half;
        }
    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            if (filter != null) return filter.isSpaceChar(c);
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

