    public static long exp(long a, long b) {
        if (b == 0) return 1;
        if (b == 1) return a;
        ArrayDeque<Long> stack = new ArrayDeque<Long>();
        while (b != 0 && b != 1) {
            if (b % 2 != 0) {
                stack.push(a);
            }
            a = (a * a) % M;
            b /= 2;
        }
        long ans = (b == 1) ? a : 1;
        while (!stack.isEmpty()) {
            ans = (ans * stack.pop()) % M;
        }
        return ans;
    }
}

