long long pow_mod(long long base, long long exponent, long long mod) {
    if (base < 0 || exponent < 0) {
        // Not fully replicating Java's sign handling, but base is positive in context
        long long res = 1;
        base %= mod;
        while (exponent > 0) {
            if (exponent & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exponent >>= 1;
        }
