vector<int> sub(const vector<int>& a, const vector<int>& b) {
    return {a[0]-b[0], a[1]-b[1], a[2]-b[2], a[3]-b[3], a[4]-b[4]};
}

bool angle(const vector<int>& u, const vector<int>& v) {
    double dot = u[0]*v[0] + u[1]*v[1] + u[2]*v[2] + u[3]*v[3] + u[4]*v[4];
    double mu = sqrt(u[0]*u[0] + u[1]*u[1] + u[2]*u[2] + u[3]*u[3] + u[4]*u[4]);
    double mv = sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2] + v[3]*v[3] + v[4]*v[4]);
    if (mu == 0.0 || mv == 0.0) return false;
    double ratio = dot / (mu * mv);
    // Clamp to avoid domain errors (though not strictly necessary for exact Java behavior)
    if (ratio > 1.0) ratio = 1.0;
    if (ratio < -1.0) ratio = -1.0;
    double deg = acos(ratio) * 180.0 / PI;
    return deg < 90.0;
}

