                    b[i] = in.nextInt();
                    c[i] = in.nextInt();
                    d[i] = in.nextInt();
                    e[i] = in.nextInt();
                }

                Set<Integer> bad = new HashSet<>();

                for (int i = 1; i <= n; i++) {
