    cin.tie(NULL);

    int n;
    cin >> n;
    if (n >= 100) {
        cout << 0 << endl;
        return 0;
    }

    vector<long long> a(105), b(105), c(105), d(105), e(105);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i] >> b[i] >> c[i] >> d[i] >> e[i];
    }

    set<int> bad;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            for (int k = 1; k <= n; ++k) {
                if (i == j || j == k || k == i) continue;

                long long ax = a[j] - a[i];
                long long bx = b[j] - b[i];
                long long cx = c[j] - c[i];
                long long dx = d[j] - d[i];
                long long ex = e[j] - e[i];

                long long ay = a[k] - a[i];
                long long by = b[k] - b[i];
                long long cy = c[k] - c[i];
                long long dy = d[k] - d[i];
                long long ey = e[k] - e[i];

                double dot = ax*ay + bx*by + cx*cy + dx*dy + ex*ey;
                long long mag1_sq = ax*ax + bx*bx + cx*cx + dx*dx + ex*ex;
                long long mag2_sq = ay*ay + by*by + cy*cy + dy*dy + ey*ey;

                double cos_angle = dot / sqrt((double)mag1_sq) / sqrt((double)mag2_sq);
                // clamp to avoid domain error in acos
                if (cos_angle > 1.0) cos_angle = 1.0;
                if (cos_angle < -1.0) cos_angle = -1.0;
