using namespace std;

const double eps = 1e-9;
const double PI = acos(-1.0);

struct Vector {
    int arr[5];
    Vector(const int a[], const int b[]) {
        for (int i = 0; i < 5; ++i) {
            arr[i] = b[i] - a[i];
        }
    }
    double mag() const {
        double sum = 0;
        for (int i = 0; i < 5; ++i) {
            sum += arr[i] * arr[i];
        }
        return sqrt(sum);
    }
    int prod(const Vector& v) const {
        int sum = 0;
        for (int i = 0; i < 5; ++i) {
            sum += arr[i] * v.arr[i];
        }
        return sum;
    }
};

int main() {
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << endl;
        return 0;
    }
    vector<vector<int>> arr(n, vector<int>(5));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 5; ++j) {
            cin >> arr[i][j];
        }
    }
    vector<int> good_indices;
    for (int i = 0; i < n; ++i) {
        bool good = true;
        for (int j = 0; j < n && good; ++j) {
            if (j == i) continue;
            for (int k = j + 1; k < n && good; ++k) {
                if (k == i) continue;
                Vector v1(arr[i].data(), arr[j].data());
                Vector v2(arr[i].data(), arr[k].data());
                double dot = v1.prod(v2);
                double mag1 = v1.mag();
                double mag2 = v2.mag();
                double cos_angle = dot / (mag1 * mag2);
                // Clamp to avoid numerical issues
                cos_angle = max(-1.0, min(1.0, cos_angle));
                double angle = acos(cos_angle);
                if (angle < PI / 2 - eps) {
                    good = false;
                }
            }
        }
        if (good) {
            good_indices.push_back(i + 1);
        }
    }
    cout << good_indices.size() << endl;
    for (int idx : good_indices) {
        cout << idx << endl;
    }
    return 0;
}

