        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                points[i][j] = scan.nextInt();
            }
        }
        List<Integer> ans = IntStream.range(0, n)
                .filter(i -> isGood(i, points))
                .map(i -> i + 1)
                .boxed()
                .collect(Collectors.toList());
        System.out.println(ans.size());
        ans.forEach(System.out::println);
    }

    private static boolean isGood(int i, int[][] p) {
        int n = p.length;
        for (int j = 0; j < n; j++) {
            if (j == i) {
                continue;
            }
            for (int k = j + 1; k < n; k++) {
                if (k == i) {
                    continue;
                }
                int dot = 0;
                double a = 0;
                double b = 0;
                for (int d = 0; d < 5; d++) {
                    int u = p[j][d] - p[i][d];
                    int v = p[k][d] - p[i][d];
                    dot += u * v;
                    a += u * u;
                    b += v * v;
                }
                double angle = Math.acos(dot / (Math.sqrt(a) * Math.sqrt(b)));
                if (angle < Math.PI / 2 - EPS) {
                    return false;
                }
            }
        }
        return true;
    }
}

