        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int d = 0; d < 5; d++) {
                    vectors[i][j][d] = data[j * 5 + d] - data[i * 5 + d];
                }
            }
        }

        BitSet bad = new BitSet(n);

        for (int i = 0; i < n; i++) {
            if (bad.get(i)) continue;
            loop:
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (!equal(vectors[i][j], vectors[i][k]) && dot(vectors[i][j], vectors[i][k]) > 0) {
                        bad.set(i);
                        break loop;
                    }
                }
            }
        }

        int good = n - bad.cardinality();
        System.out.println(good);
        for (int i = 0; i < n; i++) {
            if (!bad.get(i)) {
                System.out.println(i + 1);
            }
        }
