import java.util.Scanner;
import java.util.StringTokenizer;

public class Test {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        while (s.hasNextLine()) {
            s.nextLine();
            System.out.println(TextDocumentAnalysis.input(s.nextLine()));
        }
        s.close();
    }
}

class TextDocumentAnalysis {
    public static String input(String str) {
        int max = 0;
        int words = 0;
        int cur = 0;
        boolean open = false;
        StringTokenizer st = new StringTokenizer(str, "_()", true);
        while (st.hasMoreTokens()) {
            String token = st.nextToken();
            if (isDelimiterToken(token)) {
                char d = token.charAt(0);
                if (cur > 0) {
                    if (d == '(') {
                        if (cur > max) max = cur;
                        open = true;
                    } else if (d == ')') {
                        words++;
                        open = false;
                    } else {
                        if (open) words++;
                        else if (cur > max) max = cur;
                    }
                    cur = 0;
                } else {
                    if (d == '(') open = true;
                    else if (d == ')') open = false;
                }
            } else {
                cur += token.length();
            }
        }
        if (cur > 0) {
            if (open) words++;
            else if (cur > max) max = cur;
        }
        return max + " " + words;
    }

    private static boolean isDelimiterToken(String token) {
        return token.length() == 1
                && (token.charAt(0) == '(' || token.charAt(0) == ')' || token.charAt(0) == '_');
    }
}

