    return token.length() == 1 &&
           (token[0] == '(' || token[0] == ')' || token[0] == '_');
}

string input(const string& str) {
    int max_len = 0;
    int words = 0;
    int cur = 0;
    bool open = false;

    string temp;
    vector<string> tokens;
    for (size_t i = 0; i < str.length(); ++i) {
        char c = str[i];
        if (c == '_' || c == '(' || c == ')') {
            if (!temp.empty()) {
                tokens.push_back(temp);
                temp.clear();
            }
            tokens.push_back(string(1, c));
        } else {
            temp += c;
        }
    }
    if (!temp.empty()) {
        tokens.push_back(temp);
    }

    for (const auto& token : tokens) {
        if (isDelimiterToken(token)) {
            char d = token[0];
            if (cur > 0) {
                if (d == '(') {
                    if (cur > max_len) max_len = cur;
                    open = true;
                } else if (d == ')') {
                    words++;
                    open = false;
                } else {
                    if (open) words++;
                    else if (cur > max_len) max_len = cur;
                }
                cur = 0;
            } else {
                if (d == '(') open = true;
                else if (d == ')') open = false;
            }
        } else {
            cur += token.length();
        }
    }

    if (cur > 0) {
        if (open) words++;
        else if (cur > max_len) max_len = cur;
    }

    return to_string(max_len) + " " + to_string(words);
}

int main() {
    string line;
    while (getline(cin, line)) {
        if (!getline(cin, line)) break;
        cout << input(line) << endl;
    }
    return 0;
}

