#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>

std::vector<std::string> split(const std::string& s, char delim) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream tokenStream(s);
    while (std::getline(tokenStream, token, delim)) {
        tokens.push_back(token);
    }
    // If the string ends with delimiter, getline returns empty token, but if it starts with delimiter,
    // getline will produce an empty token at the beginning. However, if the string is empty,
    // getline will not produce any token. We need to handle empty string case.
    // Also, if the string is exactly the delimiter, getline will produce two empty tokens? Actually:
    // For s = "_", getline reads first empty token before delimiter, then after delimiter it reads empty token? 
    // Let's test: istringstream iss("_"); string t; getline(iss,t,'_'); t is ""; then getline again? 
    // Actually getline extracts characters until delimiter, so first call returns "" (since first char is delimiter),
    // then the delimiter is consumed, next call returns "" (since end of stream). So we get two empty tokens.
    // But if s is empty, getline returns false immediately, so tokens remains empty. That matches Java split("_") on "" gives [""]? 
    // Java: "".split("_") returns array of length 1 containing empty string. So we need to handle empty string specially.
    // We'll add a check: if s.empty(), return {""}.
    if (s.empty()) {
        tokens.push_back("");
    }
    return tokens;
}

int main() {
    int n;
    std::string s;
    std::cin >> n >> s;

    bool open = false;
    std::string sb;
    int maxOutSide = 0;
    int nbrInside = 0;

    for (int i = 0; i < n; ++i) {
        char c = s[i];
        if (c == '(') {
            if (!open) {
                std::vector<std::string> outsideWords = split(sb, '_');
                for (const std::string& word : outsideWords) {
                    maxOutSide = std::max(maxOutSide, (int)word.length());
                }
            }
            open = true;
            sb.clear();
        } else if (c == ')') {
            open = false;
            std::vector<std::string> inside = split(sb, '_');
            nbrInside += std::count_if(inside.begin(), inside.end(),
                                       [](const std::string& x) { return !x.empty(); });
            sb.clear();
        } else {
            sb.push_back(c);
        }
    }

    // Process remaining outside words
    std::vector<std::string> outsideWords = split(sb, '_');
    for (const std::string& word : outsideWords) {
        maxOutSide = std::max(maxOutSide, (int)word.length());
    }

    std::cout << maxOutSide << " " << nbrInside << std::endl;

    return 0;
}

