#include <iostream>
#include <string>
#include <regex>
#include <sstream>

using namespace std;

int main() {
    int n;
    string s;
    cin >> n;
    cin >> s;
    int winpars = 0, longest = 0;
    int i = 0, j = 0;

    // Replace all "__" with "_" repeatedly
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        while (pos != string::npos) {
            s.replace(pos, 2, "_");
            pos = s.find("__", pos);
        }
    }
    n = s.length();

    // First block: if opening parenthesis at start
    if (s.at(i) == '(') {
        while (true) {
            if (j >= n) break;
            char c = s.at(j);
            j++;
            if (c == ')') break;
            if (j < n && s.at(j) == ')') {
                string temp = s.substr(i + 1, j - i - 1);
                if (temp.find('_') == string::npos && temp.length() > 0) {
                    winpars++;
                } else {
                    stringstream ss(temp);
                    string token;
                    while (getline(ss, token, '_')) {
                        if (!token.empty()) winpars++;
                    }
                }
                i = j;
            }
        }
        i = j;
    }

    // Second block: scan for other parentheses
    while (i < n && s.at(i) != '(') {
        ++i;
        if (i < n && s.at(i) == '(') {
            j = i;
            while (true) {
                if (j >= n) break;
                char c = s.at(j);
                j++;
                if (c == ')') break;
                if (j < n && s.at(j) == ')') {
                    string temp = s.substr(i + 1, j - i - 1);
                    if (temp.find('_') == string::npos && temp.length() > 0) {
                        winpars++;
                    } else {
                        stringstream ss(temp);
                        string token;
                        while (getline(ss, token, '_')) {
                            if (!token.empty()) winpars++;
                        }
                    }
                    i = j;
                }
            }
            i = j;
        }
    }

    // Replace all parentheses (and their content) with '_'
    regex re("\\([^\\(]*\\)");
    while (s.find('(') != string::npos || s.find(')') != string::npos) {
        s = regex_replace(s, re, "_");
    }

    // Tokenize by '_' and find longest length
    stringstream ss(s);
    string token;
    while (getline(ss, token, '_')) {
        int len = token.length();
        if (len > longest) longest = len;
    }

    cout << longest << " " << winpars << endl;
    return 0;
}

