using namespace std;

int countTokens(const string& s) {
    int count = 0;
    stringstream ss(s);
    string token;
    while (getline(ss, token, '_')) {
        if (!token.empty()) count++;
    }
    return count;
}

int main() {
    int n;
    string s;
    cin >> n >> s;

    // Replace multiple underscores with single underscore
    string s2;
    for (char c : s) {
        if (c == '_') {
            if (s2.empty() || s2.back() != '_') s2 += '_';
        } else {
            s2 += c;
        }
    }
    s = s2;
    n = s.length();

    int winpars = 0;
    int longest = 0;
    int i = 0;
    while (i < n) {
        if (s[i] == '(') {
            int j = i;
            while (j < n && s[j] != ')') {
                j++;
                if (j < n && s[j] == ')') {
                    winpars += countTokens(s.substr(i + 1, j - i - 1));
                    i = j;
                }
            }
            // If no closing parenthesis, the loop would be infinite; assume valid input.
        } else {
            i++;
        }
    }

    // Replace all parenthesized groups with underscore
    regex paren_regex(R"(\([^\(]*\))");
    while (s.find('(') != string::npos || s.find(')') != string::npos) {
        s = regex_replace(s, paren_regex, "_");
    }

    // Find longest word outside parentheses
    stringstream ss(s);
    string token;
    while (getline(ss, token, '_')) {
        if (!token.empty()) {
            longest = max(longest, (int)token.length());
        }
    }

    cout << longest << " " << winpars << endl;
    return 0;
}

