#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

std::vector<std::string> split(const std::string& s, char delim) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream tokenStream(s);
    while (std::getline(tokenStream, token, delim)) {
        tokens.push_back(token);
    }
    // If the string ends with delimiter, getline will not add an empty token at the end.
    // But Java's split adds an empty string if the string ends with delimiter? Actually Java's split removes trailing empty strings by default.
    // However, in the code they use split("_") and then check !f.equals("") so they ignore empty strings.
    // So we don't need to add trailing empty strings. The getline behavior matches: it does not add trailing empty.
    // But for consecutive delimiters, getline returns empty strings, which is correct.
    return tokens;
}

int main() {
    std::vector<int> parentStart;
    std::vector<int> parentEnd;

    int n;
    std::string target;
    std::cin >> n >> target;

    for (int i = 0; i < n; ++i) {
        if (target[i] == '(')
            parentStart.push_back(i);
        if (target[i] == ')')
            parentEnd.push_back(i);
    }

    int count = 0;
    for (size_t i = 0; i < parentEnd.size(); ++i) {
        std::string s = target.substr(parentStart[i] + 1, parentEnd[i] - parentStart[i] - 1);
        std::vector<std::string> ss = split(s, '_');
        for (const std::string& f : ss) {
            if (!f.empty()) count++;
        }
    }

    int Max = 0;
    parentEnd.insert(parentEnd.begin(), 0);
    parentStart.push_back(target.length());

    int i;
    if (target[0] == '(')
        i = 1;
    else
        i = 0;

    for (; i < (int)parentEnd.size(); ++i) {
        std::string s;
        if (target[parentEnd[i]] == ')')
            s = target.substr(parentEnd[i] + 1, parentStart[i] - parentEnd[i] - 1);
        else
            s = target.substr(parentEnd[i], parentStart[i] - parentEnd[i]);
        std::vector<std::string> ss = split(s, '_');
        for (const std::string& sss : ss) {
            if ((int)sss.length() > Max && sss.find('(') == std::string::npos && sss.find(')') == std::string::npos) {
                Max = sss.length();
            }
        }
    }

    std::cout << Max << " " << count << std::endl;

    return 0;
}

