using namespace std;

// Count non-empty parts when splitting by '_'
int splitCount(const string& s) {
    if (s.empty()) return 0;
    stringstream ss(s);
    string part;
    int cnt = 0;
    while (getline(ss, part, '_')) {
        if (!part.empty()) cnt++;
    }
    return cnt;
}

// Find maximum length of parts that do not contain '(' or ')'
int splitMaxLength(const string& s) {
    if (s.empty()) return 0;
    stringstream ss(s);
    string part;
    int maxLen = 0;
    while (getline(ss, part, '_')) {
        if (part.find('(') == string::npos && part.find(')') == string::npos) {
            maxLen = max(maxLen, (int)part.length());
        }
    }
    return maxLen;
}

int main() {
    int n;
    string target;
    cin >> n >> target;

    vector<int> starts, ends;
    for (int i = 0; i < n; i++) {
        char c = target[i];
        if (c == '(') starts.push_back(i);
        if (c == ')') ends.push_back(i);
    }

    // Count parts inside parentheses
    int count = 0;
    for (size_t i = 0; i < ends.size(); i++) {
        string inner = target.substr(starts[i] + 1, ends[i] - starts[i] - 1);
        count += splitCount(inner);
    }

    // Prepare for outside intervals
    ends.insert(ends.begin(), 0);
    starts.push_back(target.length());

    int begin = (target[0] == '(') ? 1 : 0;
    int Max = 0;
    for (size_t i = begin; i < ends.size(); i++) {
        int from = (target[ends[i]] == ')') ? ends[i] + 1 : ends[i];
        string outer = target.substr(from, starts[i] - from);
        Max = max(Max, splitMaxLength(outer));
    }

    cout << Max << " " << count << endl;
    return 0;
}

