        while (c > ' ') {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        }
        return res * sgn;
    }

    public String next() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c = read();
        while (c <= ' ') c = read();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }
}

