    bool previousNormal = false;
    for (int i = 0; i < n; ++i) {
        if (inside[i]) {
            char c = s[i];
            if (c == '(' || c == ')' || c == '_') {
                previousNormal = false;
            } else {
                if (!previousNormal) insideWords++;
                previousNormal = true;
            }
        }
    }

    // Build the string with parentheses replaced by spaces and underscores replaced by spaces
    string replaced;
    int i = 0;
    while (i < n) {
        if (s[i] == '(') {
            // Find the matching ')'
            int j = i + 1;
            while (j < n && s[j] != ')') ++j;
            // Skip optional space after ')'
            int k = j + 1;
            if (k < n && s[k] == ' ') ++k;
            // Replace the whole expression with a single space
            replaced += ' ';
            i = k;
        } else if (s[i] == '_') {
            replaced += ' ';
            ++i;
        } else {
            replaced += s[i];
            ++i;
        }
    }

    // Split by spaces and find maximum token length
    int maxLen = 0;
    stringstream ss(replaced);
    string token;
    while (ss >> token) {
        int len = token.length();
        if (len > maxLen) maxLen = len;
    }

    // Output
    cout << maxLen << " " << insideWords << endl;

    return 0;
}

