using namespace std;

int main() {
    int n;
    cin >> n;
    cin.ignore();
    string s;
    getline(cin, s);

    // Split by regex "\\(.*?\\)" to get parts outside parentheses
    regex re("\\(.*?\\)");
    vector<string> outside_parts;
    sregex_token_iterator iter(s.begin(), s.end(), re, -1);
    sregex_token_iterator end;
    for (; iter != end; ++iter) {
        outside_parts.push_back(*iter);
    }
    // Remove trailing empty parts (Java's split omits trailing empty)
    while (!outside_parts.empty() && outside_parts.back().empty()) {
        outside_parts.pop_back();
    }

    // Find max length of underscore-separated tokens in outside parts
    int max_len = 0;
    for (const string& part : outside_parts) {
        istringstream iss(part);
        string token;
        while (getline(iss, token, '_')) {
            if (!token.empty() && (int)token.length() > max_len) {
                max_len = token.length();
            }
        }
    }

    // Extract substrings inside parentheses (using simple loop)
    vector<string> inside_parts;
    int last = -1;
    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (c == '(') {
            last = i;
        }
        if (c == ')' && last != -1) {
            inside_parts.push_back(s.substr(last + 1, i - last - 1));
        }
    }

    // Count non-empty underscore-separated words inside parentheses
    int count = 0;
    for (const string& part : inside_parts) {
        istringstream iss(part);
        string word;
        while (getline(iss, word, '_')) {
            if (!word.empty()) {
                count++;
            }
        }
    }

    cout << max_len << " " << count << endl;

    return 0;
}

