int main() {
    int n;
    cin >> n;
    cin.ignore();
    string s;
    getline(cin, s);

    vector<string> parts;
    size_t pos = 0;
    while (pos < s.length()) {
        size_t open = s.find('(', pos);
        if (open == string::npos) {
            parts.push_back(s.substr(pos));
            break;
        }
        if (open > pos) {
            parts.push_back(s.substr(pos, open - pos));
        }
        size_t close = s.find(')', open);
        if (close != string::npos) {
            pos = close + 1;
        } else {
            break;
        }
    }

    int max_len = 0;
    for (const string& part : parts) {
        istringstream tokenStream(part);
        string token;
        while (getline(tokenStream, token, '_')) {
            if (!token.empty()) {
                max_len = max(max_len, (int)token.length());
            }
        }
    }

    vector<string> inside;
    int last = -1;
    for (size_t i = 0; i < s.length(); i++) {
        char c = s[i];
        if (c == '(') {
            last = i;
        }
        if (c == ')' && last != -1) {
            inside.push_back(s.substr(last + 1, i - last - 1));
            last = -1;
        }
    }

    int count = 0;
    for (const string& content : inside) {
        istringstream tokenStream(content);
        string token;
        while (getline(tokenStream, token, '_')) {
            if (!token.empty()) {
                count++;
            }
        }
    }

    cout << max_len << " " << count << endl;
    return 0;
}

