    static class Reader {
        BufferedReader br;
        StringTokenizer st;
        Reader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }
        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

