public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int l = sc.nextInt();
        String s = sc.next();

        int max = 0;
        int num = 0;
        boolean inside = false;
        int pos = 0;

        while (pos < l) {
            int d = nextDelimiter(s, pos, l);

            if (d < 0) {
                max = Math.max(max, l - pos);
                pos = l;
            } else {
                int wordLen = d - pos;
                char ch = s.charAt(d);

                if (ch == '(') {
                    max = Math.max(max, wordLen);
                    inside = true;
                } else if (ch == ')') {
                    if (wordLen != 0) num++;
                    inside = false;
                } else {
                    if (inside) {
                        if (wordLen != 0) num++;
                    } else {
                        max = Math.max(max, wordLen);
                    }
                }

                pos = d + 1;
            }
        }

        System.out.println(max + " " + num);
    }

    private static int nextDelimiter(String s, int from, int end) {
        int min = end;

        int p = s.indexOf('(', from);
        if (p >= from && p < end && p < min) min = p;

        p = s.indexOf(')', from);
        if (p >= from && p < end && p < min) min = p;

        p = s.indexOf('_', from);
        if (p >= from && p < end && p < min) min = p;

        return min == end ? -1 : min;
    }
}

