    std::regex pattern(R"(\([^)]*\))");
    std::sregex_iterator it(line.begin(), line.end(), pattern);
    std::sregex_iterator end;

    std::vector<std::pair<int, int>> matches;
    std::vector<bool> covered(line.length(), false);
    int insideWords = 0;

    for (; it != end; ++it) {
        std::smatch match = *it;
        int start = match.position();
        int endPos = start + match.length();
        matches.push_back({start, endPos});
        for (int i = start; i < endPos; ++i) covered[i] = true;
        std::string block = match.str();
        insideWords += countWords(block.substr(1, block.length() - 2));
