#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>

using namespace std;

// Check if character is a letter or underscore
bool isLetterOrUnderscore(char c) {
    return isalpha(c) || c == '_';
}

// Replace all substrings matching pattern "([a-zA-Z_]*)"
// with a single underscore.
string replaceParentheses(const string& s) {
    string result;
    int i = 0;
    int n = s.size();
    while (i < n) {
        if (s[i] == '(') {
            // Find the matching ')'
            int j = i + 1;
            while (j < n && s[j] != ')') {
                ++j;
            }
            if (j == n) {
                // No closing parenthesis, keep the '(' and continue
                result.push_back(s[i]);
                ++i;
                continue;
            }
            // Check if substring between parentheses consists only of letters/underscores
            bool valid = true;
            for (int k = i + 1; k < j; ++k) {
                if (!isLetterOrUnderscore(s[k])) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                // Replace the whole group with '_'
                result.push_back('_');
                i = j + 1;
            } else {
                // Not a valid pattern, keep the '(' and continue
                result.push_back(s[i]);
                ++i;
            }
        } else {
            result.push_back(s[i]);
            ++i;
        }
    }
    return result;
}

// Find the maximum length of words separated by underscores (ignoring empty words)
int maxWordLength(const string& s) {
    int maxLen = 0;
    int curLen = 0;
    for (char c : s) {
        if (c == '_') {
            maxLen = max(maxLen, curLen);
            curLen = 0;
        } else {
            ++curLen;
        }
    }
    maxLen = max(maxLen, curLen);
    return maxLen;
}

// Count words in a string separated by underscores (non-empty parts)
int countWords(const string& text) {
    if (text.empty()) return 0;
    int count = 0;
    int i = 0;
    int n = text.size();
    while (i < n) {
        // Skip underscores
        while (i < n && text[i] == '_') ++i;
        if (i < n) {
            // Found a word
            ++count;
            // Skip the word
            while (i < n && text[i] != '_') ++i;
        }
    }
    return count;
}

// Count words inside parentheses in the original string
int countWordsInParentheses(const string& s) {
    int total = 0;
    int i = 0;
    int n = s.size();
    while (i < n) {
        if (s[i] == '(') {
            int j = i + 1;
            while (j < n && s[j] != ')') {
                ++j;
            }
            if (j < n) {
                // Extract substring between parentheses
                string inside = s.substr(i + 1, j - i - 1);
                total += countWords(inside);
                i = j + 1;
            } else {
                ++i;
            }
        } else {
            ++i;
        }
    }
    return total;
}

int main() {
    int n;
    string s;
    cin >> n >> s;

    // Part 1: replace parentheses groups with underscore and find max word length
    string replaced = replaceParentheses(s);
    int maxLen = maxWordLength(replaced);
    cout << maxLen << endl;

    // Part 2: count words inside parentheses
    int wordsInside = countWordsInParentheses(s);
    cout << wordsInside << endl;

    return 0;
}

