                    inParen = false;
                } else if (c == '_') {
                    if (curLen > 0) { wordCount++; curLen = 0; }
                } else if (c != '(' && c != ')') {
                    curLen++;
                }
            } else {
                if (c == '(') {
                    if (curLen > maxLen) maxLen = curLen;
                    curLen = 0;
                    inParen = true;
                } else if (c == '_') {
                    if (curLen > maxLen) maxLen = curLen;
                    curLen = 0;
                } else if (c == ')') {
                    // do nothing
                } else {
                    curLen++;
                }
            }
            idx++;
        }
        if (!inParen && curLen > maxLen) maxLen = curLen;
        cout << maxLen << " " << wordCount << endl;
    }
    return 0;
}

