using namespace std;

int scan(const string& text, const regex& token, int acc, bool count) {
    auto words_begin = sregex_iterator(text.begin(), text.end(), token);
    auto words_end = sregex_iterator();
    for (auto it = words_begin; it != words_end; ++it) {
        if (count) {
            acc++;
        } else {
            int len = it->str().length();
            if (len > acc) acc = len;
        }
    }
    return acc;
}

