    while (i < lastClose) {
        int open = st.find('(', i);
        // scan outside from j to open
        maxl = scan(st.substr(j, open - j), token, maxl, false);
        // update j to after next ')'
        j = st.find(')', j + 1) + 1;
        int close = st.find(')', i + 1);
        cnt += scan(st.substr(open + 1, close - open - 1), token, 0, true);
        i = close;
    }
    // scan remaining from j to end
    maxl = scan(st.substr(j), token, maxl, false);
    cout << maxl << " " << cnt << endl;
    return 0;
}

