public class Words {
    private enum State {
        OUTSIDE, INSIDE
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String str = sc.next();
        char[] ch = str.toCharArray();
        int[] temp = new int[n];
        int count = 0;
        int k = 0;
        State state = ch[0] == '(' ? State.INSIDE : State.OUTSIDE;

        for (int i = 0; i < n; i++) {
            char c = ch[i];
            switch (state) {
                case OUTSIDE:
                    if (c == '_') {
                        k++;
                    } else if (c == '(') {
                        state = State.INSIDE;
                    } else {
                        temp[k]++;
                    }
                    break;

                case INSIDE:
                    if (c == ')') {
                        state = State.OUTSIDE;
                        k++;
                    } else if (i > 0) {
                        char prev = ch[i - 1];
                        if ((prev == '(' || prev == '_') && c != '_' && c != '(') {
                            count++;
                        }
                    }
                    break;
            }
        }

        int swap;
        for (int i = 0; i < n; i++) {
            for (int j = i; j > 0; j--) {
                if (temp[j] > temp[j - 1]) {
                    swap = temp[j];
                    temp[j] = temp[j - 1];
                    temp[j - 1] = swap;
                }
            }
        }

        System.out.println(temp[0]);
        System.out.println(count);
    }
}

