        int maxSize = 0;
        int currentSize = 0;
        boolean inside = false;

        for (int i = 0; i < n; i++) {
            char c = arr[i];

            if (c == '(') {
                inside = true;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
                }
            } else if (c == ')') {
                inside = false;
                if (currentSize != 0) {
                    maxSize = Math.max(maxSize, currentSize);
                    currentSize = 0;
