            } else if (!inside) {
                if (c != '_') {
                    currentSize++;
                    if (i == n - 1) {
                        maxSize = Math.max(maxSize, currentSize);
                    }
                } else {
                    if (currentSize != 0) {
                        maxSize = Math.max(maxSize, currentSize);
                        currentSize = 0;
                    }
                }
            }
        }

