    getline(cin, line); // read first line (ignore)
    string temp;
    getline(cin, temp); // read the actual content

    // Find parts outside parentheses
    int one = 0;
    size_t pos = 0;
    while (pos < temp.length()) {
        size_t open = temp.find('(', pos);
        if (open == string::npos) {
            // Process remaining string from pos to end (outside)
            string seg = temp.substr(pos);
            stringstream ss(seg);
            string word;
            while (getline(ss, word, '_')) {
                if (!word.empty()) {
                    // getline may give empty strings for consecutive underscores, but '_+' splits ignore empties
                    // Actually with '_+' we need to handle multiple underscores as one delimiter
                }
            }
            // Simple approach: split by underscores manually
            size_t start = pos;
            for (size_t i = pos; i < temp.length(); ++i) {
                if (temp[i] == '_') {
                    if (i > start) {
                        one = max(one, (int)(i - start));
                    }
                    start = i + 1;
                }
            }
            if (start < temp.length()) {
                one = max(one, (int)(temp.length() - start));
            }
            break;
        }
        // Process text before '('
        string seg = temp.substr(pos, open - pos);
        size_t start = 0;
        for (size_t i = 0; i < seg.length(); ++i) {
            if (seg[i] == '_') {
                if (i > start) {
                    one = max(one, (int)(i - start));
                }
                start = i + 1;
            }
        }
        if (start < seg.length()) {
            one = max(one, (int)(seg.length() - start));
        }

        size_t close = temp.find(')', open);
        if (close == string::npos) {
            // No closing parenthesis; treat rest as inside? Original pattern has ? so may match partial
            // But for safety, break
            break;
        }
        pos = close + 1;
    }

    // Now process inside parentheses
    int two = 0;
    size_t search_start = 0;
    while (search_start < temp.length()) {
        size_t open = temp.find('(', search_start);
        if (open == string::npos) break;
        size_t close = temp.find(')', open);
        string inside;
        if (close == string::npos) {
            inside = temp.substr(open + 1);
            search_start = temp.length();
        } else {
            inside = temp.substr(open + 1, close - open - 1);
            search_start = close + 1;
        }
        // Split inside by '_+'
        size_t start = 0;
        for (size_t i = 0; i <= inside.length(); ++i) {
            if (i == inside.length() || inside[i] == '_') {
                if (i > start) {
                    string part = inside.substr(start, i - start);
                    if (containsLetter(part))
                        two++;
                }
                while (i < inside.length() && inside[i] == '_') i++;
                start = i;
                if (i == inside.length()) break;
            }
        }
    }

    cout << one << " " << two << endl;
    return 0;
}

