		Pattern outside = Pattern.compile("\\([a-zA-Z_]*\\)");
		int one = outside.splitAsStream(temp)
				.flatMap(seg -> Arrays.stream(seg.split("_+")))
				.mapToInt(String::length)
				.max()
				.orElse(0);

		Pattern paren = Pattern.compile("\\([^)]*\\)?");
		Matcher m = paren.matcher(temp);
		int two = 0;
		while (m.find()) {
			String inside = m.group().substring(1);
			for (String part : inside.split("_+")) {
				if (part.chars().anyMatch(Text_Document_Analysis::isAsciiLetter))
					two++;
			}
		}
		System.out.println(one + " " + two);
	}

	private static boolean isAsciiLetter(int ch) {
		return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
	}
}

