    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        int longestOutside = longestOutsideWord(s, n);
        int insideWords = countInsideWords(s, n);

        System.out.println(longestOutside + " " + insideWords);
    }

    private static int longestOutsideWord(String s, int n) {
        int max = -1;
        int current = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '_') {
                max = Math.max(max, current);
                current = 0;
            } else if (c != '(' && c != ')') {
                current++;
            } else {
                max = Math.max(max, current);
                current = 0;
                i++;
                while (s.charAt(i) != ')') {
                    i++;
                }
            }
        }
        return Math.max(max, current);
    }

    private static int countInsideWords(String s, int n) {
        int words = 0;
        int current = 0;

        for (int i = 0; i < n; i++) {
            while (i < n && s.charAt(i) != '(') {
                i++;
            }
            if (i == n) {
                break;
            }
            i++;
            while (s.charAt(i) != ')') {
                char c = s.charAt(i);
                if (c == '_') {
                    if (current > 0) {
                        words++;
                    }
                    current = 0;
                } else {
                    current++;
                }
                i++;
            }
            if (current > 0) {
                words++;
            }
            current = 0;
        }
        return words;
    }
}

