                    if (token.equals("(")) {
                        inPar = true;
                    } else if (token.equals(")")) {
                        inPar = false;
                    }
                } else {
                    pending += token.length();
                }
            }

            out.printf("%d %d", maxOutside, wordsInside);
        }
