vector<int> documentAnalyser(const string& doc) {
    // Words outside parentheses: remove all parenthesized parts
    regex parenRemove("\\([^)]*\\)");
    string outside = regex_replace(doc, parenRemove, "");
    regex wordPattern("[[:alpha:]]+");
    smatch m;
    string::const_iterator searchStart(outside.cbegin());
    int longest = 0;
    while (regex_search(searchStart, outside.cend(), m, wordPattern)) {
        int len = m[0].length();
        if (len > longest) longest = len;
        searchStart = m.suffix().first;
    }

    // Words inside parentheses: extract each parenthesized part
    int wordsInside = 0;
    regex parenPattern("\\(([^)]*)\\)");
    searchStart = doc.cbegin();
    while (regex_search(searchStart, doc.cend(), m, parenPattern)) {
        string inside = m[1].str();
        string::const_iterator innerStart(inside.cbegin());
        while (regex_search(innerStart, inside.cend(), m, wordPattern)) {
            wordsInside++;
            innerStart = m.suffix().first;
        }
        searchStart = m.suffix().first;
    }
    return {longest, wordsInside};
}

