            } else if (ch == ')') {
                inside = false;
                t += '_';
            } else if (!inside) {
                t += ch;
            }
        }
        return t;
    }

    static int count(const std::string& s) {
        std::regex token("[^_]+");
        auto words_begin = std::sregex_iterator(s.begin(), s.end(), token);
        auto words_end = std::sregex_iterator();
        return std::distance(words_begin, words_end);
    }

public:
    static int maxLength(const std::string& s) {
        std::string underscoreForm = toUnderscoreForm(s);
        std::regex token("[^_]+");
        auto words_begin = std::sregex_iterator(underscoreForm.begin(), underscoreForm.end(), token);
        auto words_end = std::sregex_iterator();
        int max = 0;
        for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
            std::smatch match = *i;
            max = std::max(max, (int)match.str().length());
        }
        return max;
    }

    static int words(const std::string& s) {
        int c = 0;
        std::string t;
