        if (c == '(' || c == ')') braces.push_back(i);
    }
    stringstream outside;
    int previousBoundary = -1;
    for (size_t i = 1; i + 1 < braces.size(); i += 2) {
        int open = braces[i];
        int close = braces[i + 1];
        outside << '_' << s.substr(previousBoundary + 1, open - (previousBoundary + 1));
        insideWords += countWords(s.substr(open + 1, close - open - 1));
        previousBoundary = close;
    }
    outside << '_' << s.substr(braces.back() + 1);
    string outsideText = outside.str();
    // Replace underscores with spaces, trim, collapse spaces
    for (char& c : outsideText) if (c == '_') c = ' ';
    size_t start = outsideText.find_first_not_of(' ');
    if (start != string::npos) {
        size_t end = outsideText.find_last_not_of(' ');
        outsideText = outsideText.substr(start, end - start + 1);
    } else {
        outsideText = "";
    }
    // Collapse multiple spaces
    string collapsed;
    bool space = false;
    for (char c : outsideText) {
        if (c == ' ') {
            if (!space) {
                collapsed += ' ';
                space = true;
            }
        } else {
            collapsed += c;
            space = false;
        }
    }
    outsideText = collapsed;
    int maxLen = 0;
    if (!outsideText.empty()) {
        stringstream ss(outsideText);
        string word;
        while (ss >> word) {
            maxLen = max(maxLen, (int)word.length());
        }
    }
    cout << maxLen << " " << insideWords << endl;
    return 0;
}

