long long comb[100][100];

struct Item {
    int mask;
    int d;
    Item(int m, int d) : mask(m), d(d) {}
    bool operator>(const Item& other) const {
        return d > other.d;
    }
};

long long modMul(long long a, long long b) {
    return (a * b) % MOD;
}

long long modAdd(long long a, long long b) {
    return (a + b) % MOD;
}

void precomputeCombinations() {
    for (int i = 0; i < 100; i++) {
        comb[i][0] = 1;
    }
    for (int i = 1; i < 100; i++) {
        for (int j = 1; j <= i; j++) {
            comb[i][j] = modAdd(comb[i - 1][j - 1], comb[i - 1][j]);
        }
    }
}

void relax(int fromMask, int toMask, long long edge, unordered_map<int, int>& dist, 
           unordered_map<int, long long>& ways, priority_queue<Item, vector<Item>, greater<Item>>& pq) {
    int nd = dist[fromMask] + 1;
    auto it = dist.find(toMask);
    if (it == dist.end() || nd < it->second) {
        dist[toMask] = nd;
        ways[toMask] = modMul(ways[fromMask], edge);
        pq.push(Item(toMask, nd));
    } else if (nd == it->second) {
        ways[toMask] = modAdd(ways[toMask], modMul(ways[fromMask], edge));
    }
}

