    int ans = 1000000000;
    for (int i = 0; i <= f; ++i) {
        if (i * 50 > K) break;
        int j = min((K - i * 50) / 100, h);
        int totalW = i * 50 + j * 100;
        if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred))
            ans = min(ans, solve(1, f - i, h - j));
    }
    return memo[t][f][h] = ans + 1;
}

int solve2(int t, int f, int h, int r) {
    if (r == 0 && f == 0 && h == 0) return 1;
    if (r == 0) return 0;
    if (memo2[t][f][h][r] != -1) return memo2[t][f][h][r];
    int ans = 0;
    if (t == 1) {
        for (int i = 0; i <= fifty - f; ++i) {
            if (i * 50 > K) break;
            for (int j = 0; j <= hundred - h; ++j) {
                if (i == 0 && j == 0) continue;
                int totalW = i * 50 + j * 100;
                if (totalW > K) break;
                ans = (ans + (long long)(nCk(fifty - f, i) * nCk(hundred - h, j) % MOD) * solve2(0, f + i, h + j, r - 1) % MOD) % MOD;
            }
        }
    } else {
        for (int i = 0; i <= f; ++i) {
            if (i * 50 > K) break;
            for (int j = 0; j <= h; ++j) {
                if (i == 0 && j == 0) continue;
