#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
int N, K, fifty = 0, hundred = 0;
int memo[2][101][101];
long long comb[101][101];

int solve(int t, int f, int h) {
    if (f == 0 && h == 0)
        return 0;
    if (memo[t][f][h] != -1)
        return memo[t][f][h];
    if (t == 1)
        return 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));

    int ans = 1000000;
    for (int i = 0; i <= f; i++) {
        if (i * 50 > K) break;
        int j = min((K - i * 50) / 100, h);
        int totalW = i * 50 + j * 100;
        if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred))
            ans = min(ans, solve(1, f - i, h - j));
    }
    return memo[t][f][h] = ans + 1;
}

long long nCk(int n, int k) {
    if (n < k) return 0;
    if (k == 0 || k == n) return 1;
    if (comb[n][k] != -1) return comb[n][k];
    if (n - k < k) return comb[n][k] = nCk(n, n - k);
    return comb[n][k] = (1LL * n * nCk(n - 1, k - 1) % MOD * pow(k, MOD - 2)) % MOD;
}

int pow(int x, long long p) {
    if (p == 0) return 1;
    int ans = 1;
    if (p % 2 == 1) ans = (1LL * ans * x) % MOD;
    int c = pow(x, p / 2);
    ans = (1LL * ((1LL * ans * c) % MOD) * c) % MOD;
    return ans;
}

int countWays(int min) {
    int dp[2][101][101][150];
    memset(dp, 0, sizeof(dp));
    dp[0][0][0][0] = dp[1][0][0][0] = 1;
    for (int r = 1; r <= min; r++) {
        for (int t = 0; t <= 1; t++) {
            for (int f = 0; f <= fifty; f++) {
                for (int h = 0; h <= hundred; h++) {
                    long long ans = 0;
                    if (t == 1) {
                        for (int i = 0; i <= fifty - f; i++) {
                            if (i * 50 > K) break;
                            for (int j = 0; j <= hundred - h; j++) {
                                if (i == 0 && j == 0) continue;
                                int totalW = i * 50 + j * 100;
                                if (totalW > K) break;
                                long long ways = (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD;
                                ans = (ans + ways * dp[0][f + i][h + j][r - 1]) % MOD;
                            }
                        }
                    } else {
                        for (int i = 0; i <= f; i++) {
                            if (i * 50 > K) break;
