                    int rx = cnt1 - x;
                    int ry = cnt2 - y;
                    for (int i = 0; i <= rx; i++) {
                        for (int j = 0; j <= ry; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            long ways = f(dp[x][y][z], rx, i, ry, j);
                            int nx = x + i;
                            int ny = y + j;
                            int nz = 0;
                            if (dist[nx][ny][nz] >= d + 1) {
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    queue.add(new Tuple(dist[nx][ny][nz], nx, ny, nz));
                                    dp[nx][ny][nz] += ways;
                                    dp[nx][ny][nz] %= mod;
                                } else {
                                    dp[nx][ny][nz] += ways;
                                    dp[nx][ny][nz] %= mod;
                                }
                            }
                        }
                    }
                }
            }

            if (dist[0][0][1] == INF)
                pn(-1);
            else
                pn(dist[0][0][1]);
            pn(dp[0][0][1]);
        }

        int ni() {
            return in.nextInt();
        }

        void pn(long zx) {
            out.println(zx);
        }

        class Tuple {
            long d;
            int x, y, z;

            Tuple(long d, int x, int y, int z) {
                this.d = d;
                this.x = x;
                this.y = y;
                this.z = z;
            }
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

