    if (b == 1) return a;
    long long val = pow(a, b / 2);
    if (b % 2 == 0)
        return val * val % MOD;
    else
        return val * (val * a % MOD) % MOD;
}

class Scanner {
private:
    string line;
    istringstream iss;
public:
    Scanner() {}

    string next() {
        while (iss.fail() || iss.eof()) {
            if (!getline(cin, line)) {
                throw runtime_error("No more input");
            }
            iss.clear();
            iss.str(line);
        }
        string token;
        iss >> token;
        return token;
    }

    long long nextLong() {
        return stoll(next());
    }

    int nextInt() {
        return stoi(next());
    }

    double nextDouble() {
        return stod(next());
    }

    string nextLine() {
        iss.clear();
        if (!getline(cin, line)) {
            throw runtime_error("No more input");
        }
        iss.str(line);
        return line;
    }

    bool endLine() {
        string nextLine;
        while (getline(cin, nextLine)) {
            if (nextLine.empty()) continue;
            iss.clear();
            iss.str(nextLine);
            string token;
            if (iss >> token) {
                // put back the token? Actually we consumed it.
                // Java's endLine() reads the line and then checks if there are tokens.
                // After this call, the next next() should use this line.
                // We'll store the line and iss.
                line = nextLine;
                // Note: next() will read from this line.
                return true;
            }
        }
        return false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Scanner in;
    string line = in.next();
    int result = 0;
    int last = 1;
    for (int i = 1; i < (int)line.size(); ++i) {
        if (line[i] == line[i - 1]) {
            ++last;
        } else {
            if (last % 2 == 0) ++result;
            last = 1;
        }
    }
    if (last % 2 == 0) ++result;
    cout << result << endl;
    return 0;
}

