public class GeneticEngineering {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String str = sc.next();

        int res = 0;
        Deque<Character> currentRun = new ArrayDeque<Character>();

        for (char ch : str.toCharArray()) {
            if (currentRun.isEmpty() || currentRun.peek() == ch) {
                currentRun.push(ch);
            } else {
                if (currentRun.size() % 2 == 0) {
                    res++;
                }
                currentRun.clear();
                currentRun.push(ch);
            }
        }

        if (currentRun.size() % 2 == 0) {
            res++;
        }

        System.out.println(res);
        sc.close();
    }

}

