            AtomicInteger run = new AtomicInteger(1);
            AtomicInteger result = new AtomicInteger(0);
            AtomicReference<Character> previous = new AtomicReference<>(s.charAt(0));

            s.chars().skip(1).forEach(ch -> {
                if (ch == previous.get()) {
                    run.incrementAndGet();
                } else {
                    if ((run.get() & 1) == 0) {
                        result.incrementAndGet();
