                    previous.set((char) ch);
                    run.set(1);
                }
            });

            if ((run.get() & 1) == 0) {
                result.incrementAndGet();
            }

            System.out.println(result.get());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

