// KMP ALGORITHM : TIME COMPL:O(N+M)
// FINDS THE OCCURENCES OF PATTERN AS A  SUBSTRING IN STRING
//RETURN THE ARRAYLIST OF INDEXES
// IF SIZE OF LIST IS ZERO MEANS PATTERN IS NOT PRESENT IN STRING

vector<int> kmpAlgorithm(string str, string pat) {
    vector<int> list;
    int n = str.length();
    int m = pat.length();
    string q = pat + "#" + str;
    int lps[n + m + 1];
    longestPefixSuffix(lps, q, (n + m + 1));
    for (int i = m + 1; i < (n + m + 1); i++) {
        if (lps[i] == m) {
            list.push_back(i - 2 * m);
        }
    }
    return list;
}

void longestPefixSuffix(int lps[], string str, int n) {
    lps[0] = 0;
    for (int i = 1; i <= n - 1; i++) {
        int l = lps[i - 1];
        while (l > 0 && str[i] != str[l]) {
            l = lps[l - 1];
        }
        if (str[i] == str[l]) {
            l++;
        }
        lps[i] = l;
    }
}

