long long knapsack(int weight[], long long value[], int maxWeight, int n) {
    long long dp[maxWeight + 1];
    fill(dp, dp + maxWeight + 1, 0);
    for (int i = 0; i < n; i++) {
        for (int j = maxWeight; j >= weight[i]; j--) {
            dp[j] = max(dp[j], value[i] + dp[j - weight[i]]);
        }
    }
    return dp[maxWeight];
}

