// to return max sum of any subarray in given array
long long kadanesAlgorithm(long long arr[], int n) {
    long long dp[n];
    dp[0] = arr[0];
    long long max_val = dp[0];
    for (int i = 1; i < n; i++) {
        if (dp[i - 1] > 0) {
            dp[i] = dp[i - 1] + arr[i];
        } else {
            dp[i] = arr[i];
        }
        if (dp[i] > max_val) max_val = dp[i];
    }
    return max_val;
}

