long long power(long long x, long long n) {
    //time comp : o(logn)
    if (n == 0) return 1L;
    if (n == 1) return x;
    long long ans = 1L;
    while (n > 0) {
        if (n % 2 == 1) {
            ans = ans * x;
        }
        n /= 2;
        x = x * x;
    }
    return ans;
}

////////////////////////////////////////////////////////////////////////////////////////////////////
long long powerMod(long long x, long long n, long long mod) {
    //time comp : o(logn)
    if (n == 0) return 1L;
    if (n == 1) return x;
    long long ans = 1;
    while (n > 0) {
        if (n % 2 == 1) ans = (ans * x) % mod;
        x = (x * x) % mod;
        n /= 2;
    }
    return ans;
}

