/*
lowerBound - finds largest element equal or less than value passed
upperBound - finds smallest element equal or more than value passed
if not present return -1;
*/
long long lowerBound(long long arr[], int n, long long k) {
    long long ans = -1;
    int start = 0;
    int end = n - 1;
    while (start <= end) {
        int mid = (start + end) / 2;
        if (arr[mid] <= k) {
            ans = arr[mid];
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }
    return ans;
}

