#include <bits/stdc++.h>
using namespace std;

class First {
private:
    istringstream tok;

public:
    int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    void ntok() {
        string line;
        if (!getline(cin, line)) return;
        size_t start = line.find_first_not_of(" \t");
        if (start == string::npos) return;
        tok.clear();
        tok.str(line);
    }

    int ipar() {
        string token;
        if (!(tok >> token)) return 0;
        return stoi(token);
    }

    vector<int> iapar(int n) {
        vector<int> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = ipar();
        }
        return arr;
    }

    long lpar() {
        string token;
        if (!(tok >> token)) return 0;
        return stol(token);
    }

    vector<long> lapar(int n) {
        vector<long> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = lpar();
        }
        return arr;
    }

    double dpar() {
        string token;
        if (!(tok >> token)) return 0.0;
        return stod(token);
    }

    string spar() {
        string token;
        if (!(tok >> token)) return "";
        return token;
    }

