    class StringTokenizer {
    public:
        StringTokenizer(const string& str) : input(str), pos(0) {}
        bool hasMoreTokens() {
            return pos < input.size();
        }
        string nextToken() {
            while (pos < input.size() && input[pos] == ' ') pos++;
            if (pos >= input.size()) return "";
            size_t start = pos;
            while (pos < input.size() && input[pos] != ' ') pos++;
            return input.substr(start, pos - start);
