    if (c == '-') { negative = true; c = getchar(); }
    while (c >= '0' && c <= '9') {
        result = result * 10 + (c - '0');
        c = getchar();
    }
    return negative ? -result : result;
}

int dfs(vector<pair<int,int>>& pairs, int idx, vector<int>& a, vector<int>& b, int& minVal) {
    vector<int> ca = a;
    vector<int> cb = b;
    for (auto& p : pairs) {
        int m = min(ca[p.first], cb[p.second]);
        cb[p.second] -= m;
        ca[p.first] -= m;
    }
    int sum = 0;
    for (int i = 0; i < 3; i++) sum += ca[i];
    minVal = min(minVal, sum);
    for (int i = idx; i < (int)pairs.size(); i++) {
        swap(pairs[i], pairs[idx]);
        minVal = dfs(pairs, idx + 1, a, b, minVal);
        swap(pairs[i], pairs[idx]);
    }
    return minVal;
}

