import java.util.*;
import java.util.stream.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        List<String> tokens = reader.lines()
                .flatMap(line -> Arrays.stream(line.trim().split("\\s+")))
                .filter(token -> !token.isEmpty())
                .collect(Collectors.toList());
        reader.close();

        int[] nums = tokens.stream().mapToInt(Integer::parseInt).toArray();
        int n = nums[0];
        int[] a = Arrays.copyOfRange(nums, 1, 4);
        int[] b = Arrays.copyOfRange(nums, 4, 7);

        int min = IntStream.of(
                Math.max(0, a[0] - b[0] - b[2]),
                Math.max(0, a[1] - b[0] - b[1]),
                Math.max(0, a[2] - b[1] - b[2])
        ).sum();

        int max = IntStream.of(
                Math.min(a[0], b[1]),
                Math.min(a[1], b[2]),
                Math.min(a[2], b[0])
        ).sum();

        PrintWriter pw = new PrintWriter(System.out);
        pw.println(min + " " + max);
        pw.flush();
    }
}

