import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br;
    static StringTokenizer st = new StringTokenizer("");

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        int n = nextInt();
        int[] a = {nextInt(), nextInt(), nextInt()};
        int[] b = {nextInt(), nextInt(), nextInt()};

        int max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);

        int[] order = {0, 1, 2};
        int minAns = Integer.MAX_VALUE;
        do {
            int[] ac = a.clone();
            int[] bc = b.clone();
            for (int idx : order) {
                consume(ac, bc, idx);
            }
            minAns = Math.min(minAns, ac[0] + ac[1] + ac[2]);
        } while (nextPermutation(order));

        System.out.println(minAns + " " + max);
    }

    static void consume(int[] a, int[] b, int i) {
        int first = (i + 1) % 3;
        int second = i;
        if (b[i] > a[first]) {
            b[i] -= a[first];
            a[first] = 0;
            if (b[i] > a[second]) {
                b[i] -= a[second];
                a[second] = 0;
            } else {
                a[second] -= b[i];
                b[i] = 0;
            }
        } else {
            a[first] -= b[i];
            b[i] = 0;
        }
    }

    static boolean nextPermutation(int[] arr) {
        int i = arr.length - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }
        int j = arr.length - 1;
        while (arr[j] <= arr[i]) {
            j--;
        }
        swap(arr, i, j);
        reverse(arr, i + 1, arr.length - 1);
        return true;
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }

    static void reverse(int[] arr, int l, int r) {
        while (l < r) {
            swap(arr, l++, r--);
        }
    }

    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

