public class Test {
    static class Frame {
        long x, y;
        int v1, v2;
        int state;
        long sum;
        long result;
        boolean noCache;

        Frame(long x, long y, int v1, int v2) {
            this.x = x;
            this.y = y;
            this.v1 = v1;
            this.v2 = v2;
            state = 0;
            sum = 0;
            result = 0;
            noCache = false;
        }
    }

    int r, c;
    Scanner sca = new Scanner(System.in);
    long[][] C = new long[64][64];
    long best = Long.MAX_VALUE;
    Map<Long, Long> cache = new HashMap<>();
    char[] cs;

