public class E {
    static long w, m;
    static long[] bases = new long[100];
    static long[] suff;
    static int n;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        w = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        if (m < 0) {
            System.out.println("NO");
            return;
        }
        n = 0;
        for (long v = 1; v <= 2_000_000_000L; v *= w) {
            bases[n++] = v;
        }
        suff = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suff[i] = suff[i + 1] + bases[i];
        }
        System.out.println(dfs(0, 0) ? "YES" : "NO");
    }

    static boolean dfs(int pos, long sum) {
        if (pos == n) {
            return Math.abs(sum) == m;
        }
        long rem = suff[pos];
        if (Math.abs(m - sum) > rem && Math.abs(-m - sum) > rem) {
            return false;
        }
        if (dfs(pos + 1, sum - bases[pos])) return true;
        if (dfs(pos + 1, sum)) return true;
        if (dfs(pos + 1, sum + bases[pos])) return true;
        return false;
    }
}

