    else if ((M - 1) % W == 0) return dfs(W, (M - 1) / W);
    else if ((M + 1) % W == 0) return dfs(W, (M + 1) / W);
    return false;
}

bool can(long long W, long long M, double pw) {
    if (pw == M) return true;
    long long max = (long long)pw;
    long long sum = (max - 1) / (W - 1);
    if (max - sum == M) return true;
    return dfs(W, M);
}

void solve() {
    long long W, M;
    cin >> W >> M;
    int cur = 0;
    while (pow(W, cur) < M) {
        cur++;
    }
    double pw = pow(W, cur);
    cout << (can(W, M, pw) ? "YES" : "NO") << endl;
}

int main() {
    solve();
    return 0;
}

