import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    static int nextInt(InputStream in) throws IOException {
        int c = in.read();
        while (c <= ' ') c = in.read();
        boolean neg = (c == '-');
        if (neg) c = in.read();
        int ret = 0;
        while (c >= '0' && c <= '9') {
            ret = ret * 10 + c - '0';
            c = in.read();
        }
        return neg ? -ret : ret;
    }

    static boolean get(int w, int m) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(m);
        while (!stack.isEmpty()) {
            int x = stack.pop();
            if (x == 0) return true;
            if (x % w != 0) continue;
            x /= w;
            if (x == 1) return true;
            stack.push(x + 1);
            stack.push(x - 1);
            stack.push(x);
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        int w = nextInt(System.in);
        int m = nextInt(System.in);
        boolean ans = get(w, m) || get(w, m - 1) || get(w, m + 1);
        System.out.println(ans ? "YES" : "NO");
    }
}

