        if (m == 0) {
            return true;
        }
        int d = m % w;
        if (d == 0 || d == 1) {
            return solve(w, m / w);
        }
        if (d == w - 1) {
            return solve(w, (m + 1) / w);
        }
        return false;
    }
}

