        while (true) {
            if (pod1 > pod2) {
                long long nextMass = getMass(pod1 - pod2);
                if (nextMass != 0)
                    pod2 += nextMass;
                else
                    break;
            } else if (pod1 < pod2) {
                long long nextMass = getMass(pod2 - pod1);
                if (nextMass != 0)
                    pod1 += nextMass;
                else
                    break;
            } else {
                return true;
            }
        }
        return false;
    }

    long long getMass(long long mass) {
        int logBase = static_cast<int>(std::log(mass) / std::log(weight));
        // Compute sumTotal = (weight^(logBase+1) - 1) / (weight - 1)
        long long pow1 = powInt(weight, logBase + 1);
        long long sumTotal = (pow1 - 1) / (weight - 1);

        if (mass > sumTotal && !arr[logBase + 1]) {
            long long result = powInt(weight, logBase + 1);
            arr[logBase + 1] = true;
            return result;
        } else if (mass <= sumTotal && !arr[logBase]) {
            long long result = powInt(weight, logBase);
            arr[logBase] = true;
            return result;
        } else {
            return 0;
        }
    }

    // Integer exponentiation (base^exp) for non-negative exp
    static long long powInt(int base, int exp) {
        long long result = 1;
        long long b = base;
        while (exp > 0) {
            if (exp & 1)
                result *= b;
            b *= b;
            exp >>= 1;
        }
        return result;
    }

