public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long w = in.nextLong();
        long m = in.nextLong();

        long[] sum = new long[105];
        long[] pw = new long[105];
        long p = 1;
        int mx = 0;
        for (int i = 0; i < 100; ++i) {
            sum[i + 1] = p + sum[i];
            pw[i] = p;
            p *= w;
            if (p > 1L << 40) {
                mx = i;
                break;
            }
        }

        long[][] state = new long[][]{{0, mx}};
        boolean[] stop = {false};

        Stream<long[]> stream = Stream.generate(() -> {
            long[] s = state[0];
            long cur = s[0];
            int pos = (int) s[1];
            if (stop[0] || cur == m) {
                return state[0];
            }
            if (pos < 0) {
                stop[0] = true;
                return state[0];
            }
            long remaining = sum[pos + 1];
            long next = pw[pos];
            if (cur - remaining > m || cur + remaining < m) {
                stop[0] = true;
                return state[0];
            }
            long ncur;
            int npos = pos - 1;
            if (cur + sum[pos] < m) {
                ncur = cur + next;
            } else if (cur - sum[pos] > m) {
                ncur = cur - next;
            } else {
                ncur = cur;
            }
            state[0] = new long[]{ncur, npos};
            return state[0];
        });

        boolean ok = stream.limit(mx + 2).anyMatch(s -> s[0] == m);
        System.out.println(ok ? "YES" : "NO");
    }
}

