        public void solve(int testNumber, FastReader sc, PrintWriter pw) {
            long n = sc.nextInt();
            long m = sc.nextInt();
            pw.println(can(n, m, 30) ? "YES" : "NO");
        }

        private boolean can(long n, long m, int depth) {
            if (depth == 0) {
                return true;
            }

            long d = m % n;
            long q = m / n;

            if (d <= 1) {
                return can(n, q, depth - 1);
