        String[] values = br.readLine().split(" ");
        int w = Integer.parseInt(values[0]);
        int m = Integer.parseInt(values[1]);

        List<Integer> digits = new LinkedList<Integer>();
        while (m != 0) {
            digits.add(m % w);
            m /= w;
        }

        boolean ok = true;
        ListIterator<Integer> outer = digits.listIterator();
        while (outer.hasNext()) {
            int i = outer.nextIndex();
            int digit = outer.next();

            if (digit == 0 || digit == 1) {
                continue;
            }

            if (digit == w - 1) {
                ListIterator<Integer> inner = digits.listIterator(i + 1);
                while (inner.hasNext()) {
                    int higher = inner.next();
                    if (higher == w - 1) {
                        inner.set(0);
                    } else {
                        inner.set(higher + 1);
                        break;
                    }
                }
                continue;
            }

            ok = false;
            break;
        }

        System.out.println(ok ? "YES" : "NO");
    }
}

