ll modadd(ll a, ll b) {
    ll res = a + b;
    if (res >= MOD) res -= MOD;
    if (res < 0) res += MOD;
    return res;
}

ll modmul(ll a, ll b) {
    return (a * b) % MOD;
}

ll modpow(ll a, ll e) {
    if (e == 0) return 1;
    if (e == 1) return a;
    ll r = modpow(a, e >> 1);
    r = modmul(r, r);
    if (e & 1) r = modmul(r, a);
    return r;
}

