using namespace std;

typedef long long ll;

ll mod = 998244353LL;

ll mp(ll b, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * b) % mod;
        b = (b * b) % mod;
        e >>= 1;
    }
    return r;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    ll k;
    cin >> n >> k;

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    vector<ll> fact(n+1), inv(n+1);
    fact[0] = inv[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = (fact[i-1] * i) % mod;
    inv[n] = mp(fact[n], mod - 2);
    for (int i = n-1; i >= 1; i--) inv[i] = ((i+1) * inv[i+1]) % mod;

    auto nCr = [&](int n, int r) -> ll {
        if (r < 0 || r > n) return 0;
        return fact[n] * inv[n-r] % mod * inv[r] % mod;
