import java.util.stream.IntStream;

public class E1342V5 {
    static final long MOD = 998244353L;

    static long modPow(long a, long e) {
        a %= MOD;
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    static long[] fac, invfac;

    static long nck(long n, long k) {
        return fac[(int) n] * invfac[(int) k] % MOD * invfac[(int) (n - k)] % MOD;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);
        long n = fs.nextInt();
        long k = fs.nextLong();
        if (k >= n) {
            pw.println(0);
            pw.close();
            return;
        }
        int N = (int) n;
        fac = new long[N + 1];
        invfac = new long[N + 1];
        fac[0] = 1;
        for (int i = 1; i <= N; i++) fac[i] = fac[i - 1] * i % MOD;
        invfac[0] = 1;
        for (int i = 1; i <= N; i++) invfac[i] = invfac[i - 1] * modPow(i, MOD - 2) % MOD;

        long m = n - k;
        long total = IntStream.rangeClosed(0, (int) m)
                .mapToLong(i -> {
                    long term = modPow(m - i, n) * nck(m, i) % MOD;
                    return (i & 1) == 0 ? term : MOD - term;
                })
                .reduce(0L, (a, b) -> (a + b) % MOD);

        long ans = total * nck(n, m) % MOD;
        if (m != n) ans = ans * 2 % MOD;
        pw.println(ans);
        pw.close();
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

