#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD = 998244353;

int modpow(int a, int b) {
    if (a == 0) return 0;
    int res = 1;
    while (b > 0) {
        if (b & 1) res = (long long)res * a % MOD;
        a = (long long)a * a % MOD;
        b >>= 1;
    }
    return res;
}

int modmul(int a, int b) {
    return (long long)a * b % MOD;
}

int main() {
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << endl;
        return 0;
    }
    int kk = (int)k;
    vector<int> fact(n + 1), ifact(n + 1);
    fact[0] = fact[1] = 1;
    for (int i = 2; i <= n; ++i) {
        fact[i] = modmul(fact[i - 1], i);
    }
    ifact[n] = modpow(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i) {
        ifact[i] = modmul(ifact[i + 1], i + 1);
    }
    int sum = 0;
    int sgn = 1;
    for (int i = 0; i <= n - kk; ++i) {
        int val = modmul(modpow(n - kk - i, n), modmul(fact[n - kk], modmul(ifact[i], ifact[n - kk - i])));
        if (sgn == 1) {
            sum += val;
        } else {
            sum -= val;
        }
        if (sum >= MOD) sum -= MOD;
        if (sum < 0) sum += MOD;
        sgn = -sgn;
    }
    sum = modmul(sum, fact[n]);
    sum = modmul(sum, ifact[kk]);
    sum = modmul(sum, ifact[n - kk]);
    int result;
    if (kk == 0) {
        result = sum;
    } else {
        result = modmul(sum, 2);
    }
    cout << result << endl;
    return 0;
}

