#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int mul(int a, int b) {
    return (int)((long long)a * b % MOD);
}

int pow_mod(int a, int b) {
    if (a == 0) return 0;
    int ans = 1;
    while (b > 0) {
        if (b & 1) ans = mul(ans, a);
        a = mul(a, a);
        b >>= 1;
    }
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long kl;
    cin >> n >> kl;
    if (kl >= n) {
        cout << 0 << endl;
        return 0;
    }
    int k = (int)kl;
    vector<int> fact(n + 1), ifact(n + 1);
    fact[0] = fact[1] = 1;
    for (int i = 2; i <= n; ++i) {
        fact[i] = mul(fact[i - 1], i);
    }
    // ifact will be computed on demand
    auto ifac = [&](int x) -> int {
        if (ifact[x] > 0) return ifact[x];
        return ifact[x] = pow_mod(fact[x], MOD - 2);
    };

    int sum = 0;
    int sign = 1;
    int lim = n - k;
    for (int i = 0; i <= lim; ++i) {
        int val = mul(pow_mod(lim - i, n), mul(fact[lim], mul(ifac(i), ifac(lim - i))));
        sum = (sum + sign * val) % MOD;
        if (sum < 0) sum += MOD;
        sign = -sign;
    }
    sum = mul(sum, fact[n]);
    sum = mul(sum, ifac(k));
    sum = mul(sum, ifac(n - k));
    if (k != 0) {
        sum = mul(sum, 2);
    }
    cout << sum << endl;
    return 0;
}

