using namespace std;

const long long MOD = 998244353LL;

long long power(long long x, long long y, long long m) {
    if (y < 0) return 0LL;
    long long ans = 1LL;
    x %= m;
    while (y > 0) {
        if (y & 1)
            ans = (ans * x) % m;
        y >>= 1;
        x = (x * x) % m;
    }
    return ans;
}

long long choose(int n, int k, const vector<long long>& fac) {
    long long den = (fac[k] * fac[n - k]) % MOD;
    long long denInv = power(den, MOD - 2, MOD);
    return (fac[n] * denInv) % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int N;
    long long K;
    cin >> N >> K;

    if (K >= N) {
        cout << 0 << endl;
        return 0;
    }

    int C = (int)(N - K);

    vector<long long> fac(200001);
    fac[0] = 1LL;
    for (int i = 1; i <= 200000; ++i)
        fac[i] = (i * fac[i - 1]) % MOD;

    long long ans = 0LL;
    int sign = 1;
    for (int i = C; i >= 1; --i) {
        long long val = (choose(C, i, fac) * power(i, N, MOD)) % MOD;
        ans = (ans + sign * val) % MOD;
        if (ans < 0) ans += MOD;
        sign = -sign;
    }

    long long mult;
    if (C == N)
        mult = 1LL;
    else
        mult = (2LL * choose(N, C, fac)) % MOD;

    cout << (ans * mult) % MOD << endl;

    return 0;
}

