#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <stdexcept>
#include <cstdlib>

using namespace std;

const long long MOD = 998244353;
const int MAX = 1000000;
vector<long long> fact(MAX), invFact(MAX);

long long powMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}

long long nCk(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
}

long long powGo(int base, long long exp) {
    long long ans = 0;
    for (int sub = 0; sub < base; sub++) {
        long long term = powMod(base - sub, exp) * nCk(base, sub) % MOD;
        if (sub % 2 == 0)
            ans = (ans + term) % MOD;
        else
            ans = (ans + MOD - term) % MOD;
    }
    return ans;
}

void precomp() {
    fact[0] = 1;
    for (int i = 1; i < MAX; i++) fact[i] = fact[i - 1] * i % MOD;
    vector<long long> inv(MAX);
    inv[1] = 1;
    invFact[0] = invFact[1] = 1;
    for (int i = 2; i < MAX; i++) {
        inv[i] = MOD - MOD / i * inv[MOD % i] % MOD;
        invFact[i] = invFact[i - 1] * inv[i] % MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    precomp();

    try {
        cin.exceptions(ios::failbit | ios::badbit);
        int n, k;
        cin >> n >> k;

        if (k == 0) {
            cout << fact[n] << '\n';
            return 0;
        }
        if (k >= n) {
            cout << 0 << '\n';
            return 0;
        }
        int m = n - k;
        long long assign = powGo(m, n);
        long long choose = nCk(n, m);
        long long ways = choose * assign % MOD;
        cout << ways * 2 % MOD << '\n';
    } catch (const exception& e) {
        cout << 0 << '\n';
    }

    return 0;
}

