#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353;
const int MAXF = 400000;

vector<ll> fact, revFact;

ll modpow(ll x, ll y) {
    ll res = 1;
    while (y > 0) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return res;
}

void preFact(int n) {
    fact.resize(n + 1);
    revFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 0; i < n; i++) {
        fact[i + 1] = (i + 1) * fact[i] % MOD;
    }
    revFact[n] = modpow(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; i--) {
        revFact[i] = revFact[i + 1] * (i + 1) % MOD;
    }
}

ll cmb(int a, int b) {
    if (a < b) return 0;
    ll af = fact[a];
    ll bf = revFact[b];
    ll abf = revFact[a - b];
    return ((af * bf) % MOD) * abf % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll tmp;
    cin >> n >> tmp;

    if (n <= tmp) {
        cout << 0 << '\n';
        return 0;
    }
    int k = (int)tmp;

    preFact(MAXF);

    ll ans = 0;
    int si = 1;
    ll t = cmb(n, n - k);
    for (int i = n - k; i >= 1; i--) {
        ans = (ans + si * cmb(n - k, i) % MOD * modpow(i, n) % MOD) % MOD;
        if (ans < 0) ans += MOD;
        si *= -1;
    }
    ans = ans * t % MOD;
    if (k != 0) ans = ans * 2 % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << '\n';

    return 0;
}

