using namespace std;

typedef long long ll;

const ll MOD = 998244353LL;
const int MAXN = 400000;

vector<ll> fact, revFact;

ll mod_pow(ll x, ll y) {
    if (y < 0) return 0;
    ll res = 1;
    while (y) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return res;
}

ll mod_add(ll x, ll y) {
    ll res = (x + y) % MOD;
    return res < 0 ? res + MOD : res;
}

ll mod_sub(ll x, ll y) {
    ll res = (x - y) % MOD;
    return res < 0 ? res + MOD : res;
}

ll mod_mul(ll x, ll y) {
    ll res = (x * y) % MOD;
    return res < 0 ? res + MOD : res;
}

ll mod_div(ll x, ll y) {
    return mod_mul(x, mod_pow(y, MOD - 2));
}

void preFact(int n) {
    fact.resize(n + 1);
    revFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 0; i < n; ++i) {
        fact[i + 1] = mod_mul(i + 1, fact[i]);
    }
    revFact[n] = mod_div(1, fact[n]);
    for (int i = n - 1; i >= 0; --i) {
        revFact[i] = mod_mul(revFact[i + 1], i + 1);
    }
}

ll cmb(int a, int b) {
    if (a < b) return 0;
    if (fact.empty()) {
        fprintf(stderr, "error : factorials has not been calculated!! do [preFact] method\n");
        return 0;
    }
    ll af = fact[a];
    ll bf = revFact[b];
    ll abf = revFact[a - b];
    return mod_mul(mod_mul(af, bf), abf);
}

// Fast input
inline int readInt() {
    int num = 0, b;
    bool minus = false;
    while ((b = getchar()) != EOF && !((b >= '0' && b <= '9') || b == '-'));
    if (b == '-') {
        minus = true;
        b = getchar();
    }
    while (true) {
        if (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
        } else {
            return minus ? -num : num;
        }
        b = getchar();
    }
}

inline ll readLong() {
    ll num = 0;
    int b;
    bool minus = false;
    while ((b = getchar()) != EOF && !((b >= '0' && b <= '9') || b == '-'));
    if (b == '-') {
        minus = true;
        b = getchar();
    }
    while (true) {
        if (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
        } else {
            return minus ? -num : num;
        }
        b = getchar();
    }
}

void solve() {
    int n = readInt();
    ll tmp = readLong();
    if (n <= tmp) {
        cout << 0 << endl;
        return;
    }
    int k = (int)tmp;
    preFact(MAXN);
    int limit = n - k;
    ll ans = 0;
    for (int i = 1; i <= limit; ++i) {
        ll sign = (i % 2 == 0) ? -1 : 1;
        ll term = mod_mul(sign, mod_mul(cmb(limit, i), mod_pow(i, n)));
        ans = mod_add(ans, term);
    }
    if (ans < 0) ans += MOD;
    ll t = cmb(n, n - k);
    ans = mod_mul(ans, t);
    if (k != 0) ans = mod_mul(ans, 2);
    if (ans < 0) ans += MOD;
    cout << ans << endl;
}

