#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <cstdio>
using namespace std;

typedef long long ll;

const ll MOD = 998244353;
const int MAXN = 400000;

vector<ll> fact, revFact;

ll mod_pow(ll x, ll y) {
    if (y < 0) return 0;
    if (y == 0) return 1;
    if (y % 2 == 1) return (x * mod_pow(x, y - 1)) % MOD;
    ll root = mod_pow(x, y / 2);
    return (root * root) % MOD;
}

ll mod_mul(ll x, ll y) {
    ll res = (x * y) % MOD;
    return res < 0 ? res + MOD : res;
}

ll mod_div(ll x, ll y) {
    ll res = x * mod_pow(y, MOD - 2) % MOD;
    return res < 0 ? res + MOD : res;
}

void preFact(int n) {
    fact.resize(n + 1);
    revFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 0; i < n; i++) {
        fact[i + 1] = mod_mul(i + 1, fact[i]);
    }
    revFact[n] = mod_div(1, fact[n]);
    for (int i = n - 1; i >= 0; i--) {
        revFact[i] = mod_mul(revFact[i + 1], i + 1);
    }
}

ll cmb(int a, int b) {
    if (a < b) return 0;
    if (fact.empty()) {
        cerr << "error : factorials has not been calculated!! do [pre_factorial] method" << endl;
        return 0;
    }
    ll af = fact[a];
    ll bf = revFact[b];
    ll abf = revFact[a - b];
    return mod_mul(mod_mul(af, bf), abf);
}

ll sum(int limit, int n) {
    // iterative version of recursive sum(i, limit, n, sign)
    ll res = 0;
    int sign = 1;
    for (int i = 1; i <= limit; i++) {
        ll term = sign * cmb(limit, i) % MOD * mod_pow(i, n) % MOD;
        term %= MOD;
        if (term < 0) term += MOD;
        res = (res + term) % MOD;
        sign = -sign;
    }
    return res;
}

void solve() {
    int n, k;
    cin >> n >> k;
    if (n <= k) {
        cout << 0 << endl;
        return;
    }
    preFact(400000);
    ll ans = sum(n - k, n);
    if (ans < 0) ans += MOD;
    ll t = cmb(n, n - k);
    ans = (ans * t) % MOD;
    if (k != 0) ans = (ans * 2) % MOD;
    if (ans < 0) ans += MOD;
    cout << ans << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    solve();
    return 0;
}

