#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdio>
#include <cmath>
using namespace std;

typedef long long ll;

const ll mod = 998244353LL;
const int MAXN = 400000;

vector<ll> fact, revFact;

ll mod_add(ll x, ll y) {
    ll res = (x + y) % mod;
    return res < 0 ? res + mod : res;
}

ll mod_sub(ll x, ll y) {
    ll res = (x - y) % mod;
    return res < 0 ? res + mod : res;
}

ll mod_mul(ll x, ll y) {
    ll res = (x * y) % mod;
    return res < 0 ? res + mod : res;
}

ll mod_pow(ll x, ll y) {
    if (y < 0) return 0;
    if (y == 0) return 1;
    if (y % 2 == 1) return mod_mul(x, mod_pow(x, y - 1));
    ll root = mod_pow(x, y / 2);
    return mod_mul(root, root);
}

ll mod_div(ll x, ll y) {
    ll res = mod_mul(x, mod_pow(y, mod - 2));
    return res < 0 ? res + mod : res;
}

ll powIter(ll x, ll y) {
    if (y < 0) return 0;
    ll res = 1;
    ll base = x % mod;
    while (y > 0) {
        if (y & 1) {
            res = mod_mul(res, base);
        }
        base = mod_mul(base, base);
        y >>= 1;
    }
    return res;
}

void preFact(int n) {
    fact.resize(n + 1);
    revFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 0; i < n; i++) {
        fact[i + 1] = mod_mul(i + 1, fact[i]);
    }
    revFact[n] = mod_div(1, fact[n]);
    for (int i = n - 1; i >= 0; i--) {
        revFact[i] = mod_mul(revFact[i + 1], i + 1);
    }
}

ll cmb(int a, int b) {
    if (a < b) return 0;
    if (fact.empty()) {
        cerr << "error : factorials has not been calculated!! do [pre_factorial] method" << endl;
        return 0;
    }
    ll af = fact[a];
    ll bf = revFact[b];
    ll abf = revFact[a - b];
    return mod_mul(mod_mul(af, bf), abf);
}

// Fast input
inline int ni() {
    int num = 0, b;
    bool minus = false;
    while ((b = getchar()) != EOF && !((b >= '0' && b <= '9') || b == '-'));
    if (b == '-') {
        minus = true;
        b = getchar();
    }
    while (true) {
        if (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
        } else {
            return minus ? -num : num;
        }
        b = getchar();
    }
}

inline ll nl() {
    ll num = 0;
    int b;
    bool minus = false;
    while ((b = getchar()) != EOF && !((b >= '0' && b <= '9') || b == '-'));
    if (b == '-') {
        minus = true;
        b = getchar();
    }
    while (true) {
        if (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
        } else {
            return minus ? -num : num;
        }
        b = getchar();
    }
}

void solve() {
    int n = ni();
    ll tmp = nl();
    if (n <= tmp) {
        cout << 0 << endl;
        return;
    }
    int k = (int)tmp;
    preFact(400000);
    ll ans = 0;
    int limit = n - k;
    ll t = cmb(n, limit);
    bool positive = true;
    int i = 1;
    while (i <= limit) {
        ll term = (positive ? 1 : -1) * mod_mul(cmb(limit, i), powIter(i, n));
        term %= mod;
        if (term < 0) term += mod;
        ans = mod_add(ans, term);
        positive = !positive;
        i++;
    }
    if (ans < 0) ans += mod;
    ans = mod_mul(ans, t);
    if (k != 0) ans = mod_mul(ans, 2);
    if (ans < 0) ans += mod;
    cout << ans << endl;
}

int main() {
    solve();
