using namespace std;

typedef long long ll;

const int MOD = 998244353;

vector<int> fac;

int pow_mod(int b, ll e, int mod) {
    int ans = 1;
    b %= mod;
    while (e > 0) {
        if (e & 1)
            ans = (int)((ans * 1LL * b) % mod);
        e >>= 1;
        b = (int)((b * 1LL * b) % mod);
    }
    return ans;
}

ll ncr(int n, int r) {
    ll ans = fac[n];
    ll de = (fac[n - r] * 1LL * fac[r]) % MOD;
    de = pow_mod((int)de, MOD - 2, MOD);
    return (ans * de) % MOD;
}

ll gcd(ll a, ll b) {
    return (b == 0) ? a : gcd(b, a % b);
}

ll lcm(ll a, ll b) {
    return a / gcd(a, b) * b;
}

int log_int(int n, int base) {
    int ans = 0;
    while (n + 1 > base) {
        ans++;
        n /= base;
    }
    return ans;
}

ll square(ll l) {
    return l * l;
}

void shuffle_array(int a[], int n) {
    for (int i = 0; i < n; i++) {
        int r = i + rand() % (n - i);
        int tmp = a[i];
        a[i] = a[r];
        a[r] = tmp;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    ll k;
    cin >> n >> k;

    if (k > n - 1) {
        cout << 0 << endl;
        return 0;
    }

    fac.resize(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = (int)((fac[i - 1] * 1LL * (i % MOD)) % MOD);
    }

    int pop = n - (int)k;
    ll ans = 0;
    for (int i = 0; i <= pop; i++) {
        ll notPop = (ncr(pop, i) * pow_mod(pop - i, n, MOD)) % MOD;
        if (i % 2 == 1)
            notPop = (MOD - notPop) % MOD; // multiply by -1 mod MOD
        ans = (ans + notPop) % MOD;
    }
    ans = (ans * ncr(n, pop)) % MOD;
    if (k != 0)
        ans = (ans * 2) % MOD;
    cout << ans << endl;

    return 0;
}

