vector<ll> fact, invFact;

ll modPow(ll x, int e) {
    ll res = 1;
    while (e) {
        if (e & 1) res = res * x % MOD;
        x = x * x % MOD;
        e >>= 1;
    }
    return res;
}

ll modInv(ll x) {
    return modPow(x, MOD - 2);
}

void precomputeFactorials(int n) {
    fact.resize(n + 1);
    invFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invFact[n] = modInv(fact[n]);
    for (int i = n; i >= 1; --i) {
        invFact[i - 1] = invFact[i] * i % MOD;
    }
}

ll nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
}

ll paritySign(ll k) {
    return (k & 1) ? MOD - 1 : 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll k;
    cin >> n >> k;

    if (k == 0) {
        precomputeFactorials(n);
        cout << fact[n] << '\n';
        return 0;
    }

    if (k > n - 1) {
        cout << 0 << '\n';
        return 0;
    }

    int c = (int)(n - k);
    precomputeFactorials(max(n, c)); // ensure enough factorials

    ll answer = 0;
    for (int i = 1; i <= c; ++i) {
        ll term = paritySign(c - i) * nCr(c, i) % MOD * modPow(i, n) % MOD;
        answer = (answer + term) % MOD;
    }

    answer = answer * 2 % MOD * nCr(n, c) % MOD;
    cout << answer << '\n';

