        // use BigInteger for modular exponentiation
        BigInteger bx = BigInteger.valueOf(x);
        BigInteger by = BigInteger.valueOf(y);
        BigInteger bp = BigInteger.valueOf(p);
        return bx.modPow(by, bp).longValue();
    }
}

