                if (isValid(x + 1, y)) {
                    remove(x + 1, y);
                }
                // check third branch
                if (isValid(x, y + 1)) {
                    put(x, y + 1);
                    top[2] = 3;
                    stack.push(new int[]{x, y + 1, 0});
                    continue;
                } else {
                    // done, pop
                    stack.pop();
                    continue;
                }
            } else if (state == 3) {
                // after third branch rec call returned
                remove(x, y + 1);
                stack.pop();
                continue;
            }
        }
    }

    // put and remove unchanged
    private void put(int x, int y) {
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (f[nx][ny] == 0) {
                    --numFree;
                    f[nx][ny] = step;
                }
            }
        }
        ++step;
        ++cur;
    }

    private void remove(int x, int y) {
        --step;
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
