#include <iostream>
#include <vector>
#include <stack>
#include <array>
#include <climits>
#include <algorithm>

using namespace std;

class TaskC {
private:
    int n, m;
    vector<int> dx = {-1, 0, 1, 0, 0};
    vector<int> dy = {0, 1, 0, -1, 0};
    int step;
    int numFree;
    int cur;
    int res;
    vector<vector<int>> f;

    bool isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < m;
    }

    void put(int x, int y) {
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (f[nx][ny] == 0) {
                    --numFree;
                    f[nx][ny] = step;
                }
            }
        }
        ++step;
        ++cur;
    }

    void remove(int x, int y) {
        --step;
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (f[nx][ny] == step) {
                    ++numFree;
                    f[nx][ny] = 0;
                }
            }
        }
        --cur;
    }

    void rec(int startX, int startY) {
        stack<array<int,3>> st;
        st.push({startX, startY, 0});
        while (!st.empty()) {
            auto& top = st.top();
            int x = top[0];
            int y = top[1];
            int state = top[2];
            if (state == 0) {
                if (numFree == 0) {
                    res = min(res, cur);
                    st.pop();
                    continue;
                }
                if (x >= n) {
                    st.pop();
                    continue;
                }
                if (y >= m) {
                    top[0] = x + 1;
                    top[1] = 0;
                    top[2] = 0;
                    continue;
                }
                if (f[x][y] != 0) {
                    top[1] = y + 1;
                    top[2] = 0;
                    continue;
                }
                put(x, y);
                top[2] = 1;
                st.push({x, y + 1, 0});
                continue;
            } else if (state == 1) {
                remove(x, y);
                if (isValid(x + 1, y)) {
                    put(x + 1, y);
                    top[2] = 2;
                    st.push({x, y + 1, 0});
                    continue;
                } else {
                    top[2] = 2;
                }
            } else if (state == 2) {
                if (isValid(x + 1, y)) {
                    remove(x + 1, y);
                }
                if (isValid(x, y + 1)) {
                    put(x, y + 1);
                    top[2] = 3;
                    st.push({x, y + 1, 0});
                    continue;
                } else {
                    st.pop();
                    continue;
                }
            } else if (state == 3) {
                remove(x, y + 1);
                st.pop();
                continue;
            }
        }
    }

public:
    void solve() {
        cin >> n >> m;
        if (n > m) {
            swap(n, m);
        }
        f.assign(n, vector<int>(m, 0));
        res = INT_MAX;
        cur = 0;
        step = 1;
        numFree = n * m;
        rec(0, 0);
        cout << n * m - res << endl;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    TaskC task;
    task.solve();
    return 0;
}

