    if (N < M) {
        swap(N, M);
    }
    int pow = 1 << M;
    vector<int> counts(pow);
    for (int i = 0; i < pow; ++i) {
        counts[i] = __builtin_popcount(i);
    }
    // dp[y][i][j] = -1 means uninitialized
    vector<vector<vector<int>>> dp(N, vector<vector<int>>(pow, vector<int>(pow, -1)));
    for (int i = 0; i < pow; ++i) {
        dp[0][i][0] = counts[i];
    }
    int maskAll = pow - 1;
    for (int y = 0; y < N - 1; ++y) {
        for (int i = 0; i < pow; ++i) {
            for (int j = 0; j < pow; ++j) {
                int cur = dp[y][i][j];
                if (cur == -1) continue;
                for (int k = 0; k < pow; ++k) {
                    int combined = (i | (i << 1) | (i >> 1) | j | k) & maskAll;
                    if (combined == maskAll) {
                        int value = cur + counts[k];
                        int &target = dp[y + 1][k][i];
                        if (target == -1 || target > value) {
                            target = value;
                        }
                    }
                }
            }
        }
    }
    int spiders = INT_MAX;
    for (int i = 0; i < pow; ++i) {
        for (int j = 0; j < pow; ++j) {
            int cur = dp[N - 1][i][j];
            if (cur != -1) {
                int combined = (i | (i << 1) | (i >> 1) | j) & maskAll;
                if (combined == maskAll) {
                    spiders = min(spiders, cur);
                }
            }
        }
    }
    cout << (N * M - spiders) << endl;
    return 0;
}

