import java.util.*;
import java.io.*;

public class Div680 {
    static int N, M, O;
    static int[][][] D;

    static int solve(int done, int i, int diff) {
        if (i == N)
            return diff > 0 ? 1 : 0;
        if (D[done][i][diff + O] != -1)
            return D[done][i][diff + O];
        int rem = N - i;
        int ans = 0;
        for (int l = 0; l < rem; l++) {
            for (int r = done == 1 ? 0 : l; r < rem; r++) {
                ans += solve(done | (l < r ? 1 : 0), i + 1, diff + l - r);
                ans %= M;
            }
        }
        return D[done][i][diff + O] = ans;
    }

    static long solve2(int i) {
        if (i == N - 1)
            return 0;
        long ans = (N - i) * 1L * solve2(i + 1);
        ans %= M;
        for (int l = 0; l < N - i; l++) {
            for (int r = l + 1; r < N - i; r++) {
                ans += solve(1, i + 1, l - r);
                ans %= M;
            }
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        FastReader fr = new FastReader();
        PrintWriter pw = new PrintWriter(System.out);
        N = fr.nextInt();
        M = fr.nextInt();
        O = N * (N - 1);
        D = new int[2][N][2 * O + 1];
        for (int[][] x : D)
            for (int[] y : x)
                Arrays.fill(y, -1);
        pw.println(solve2(0));
        pw.flush();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

