    static int n, mod, offset;
    static Map<String, Integer> memo;

    static int dp(int done, int i, int diff) {
        if (i == n)
            return diff > 0 ? 1 : 0;
        String key = done + "," + i + "," + diff;
        if (memo.containsKey(key))
            return memo.get(key);
        int rem = n - i;
        int ans = 0;
        for (int l = 0; l < rem; l++) {
            for (int r = done == 1 ? 0 : l; r < rem; r++) {
                ans += dp(done | (l < r ? 1 : 0), i + 1, diff + l - r);
                ans %= mod;
            }
        }
        memo.put(key, ans);
        return ans;
    }

    static long dp2(int i) {
        if (i == n - 1)
            return 0;
        long ans = (n - i) * 1L * dp2(i + 1);
        ans %= mod;
        for (int l = 0; l < n - i; l++) {
            for (int r = l + 1; r < n - i; r++) {
                ans += dp(1, i + 1, l - r);
                ans %= mod;
            }
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        n = sc.nextInt();
        mod = sc.nextInt();
        offset = n * (n - 1);
        memo = new HashMap<>();
        pw.println(dp2(0));
        pw.flush();
    }

