import java.io.*;

public class Div680 {
    static int n, mod, offset;
    static int[][][] dp;

    static int solve(int done, int i, int diff) {
        if (i == n)
            return diff > 0 ? 1 : 0;
        if (dp[done][i][diff + offset] != -1)
            return dp[done][i][diff + offset];
        int rem = n - i;
        int ans = 0;
        int l = 0;
        while (l < rem) {
            int r = (done == 1) ? 0 : l;
            while (r < rem) {
                ans += solve(done | (l < r ? 1 : 0), i + 1, diff + l - r);
                ans %= mod;
                r++;
            }
            l++;
        }
        dp[done][i][diff + offset] = ans;
        return ans;
    }

    static long solve2(int i) {
        if (i == n - 1)
            return 0;
        long ans = (n - i) * 1L * solve2(i + 1);
        ans %= mod;
        int l = 0;
        while (l < n - i) {
            int r = l + 1;
            while (r < n - i) {
                ans += solve(1, i + 1, l - r);
                ans %= mod;
                r++;
            }
            l++;
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
