        while (*cur <= ' ') cur++;
        string s;
        while (*cur > ' ') {
            s += *cur;
            cur++;
        }
        return s;
    }
};

FastScanner fs;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    int T = 1;
    for (int t = 0; t < T; t++) {
        int n = fs.nextInt();
        int mod = fs.nextInt();

        // dp[i][j] : number of permutations of i+1 elements with j inversions? Actually dp[0][0]=1, dp[i][j] from dp[i-1][j-cnt] for cnt=0..i
        vector<vector<ll>> dp(n, vector<ll>(n * n + 5, 0));
        dp[0][0] = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < (int)dp[0].size(); j++) {
                for (int cnt = 0; cnt <= i; cnt++) {
                    if (j - cnt >= 0) {
                        dp[i][j] += dp[i - 1][j - cnt];
                        dp[i][j] %= mod;
                        if (dp[i][j] == 0) dp[i][j] += mod;
                    }
                }
            }
        }

        // sums[i][j] = prefix sum of dp[i][0..j] modulo mod
        vector<vector<ll>> sums(dp.size(), vector<ll>(dp[0].size(), 0));
        for (int i = 0; i < (int)dp.size(); i++) {
            ll sum = 0;
            for (int j = 0; j < (int)dp[0].size(); j++) {
                sum += dp[i][j];
                sum %= mod;
                if (sum == 0) sum += mod;
                sums[i][j] = sum;
            }
        }

        // factorials up to 501*501
        vector<ll> fact(501 * 501, 0);
        fact[0] = fact[1] = 1;
        for (int i = 2; i < (int)fact.size(); i++) {
            fact[i] = fact[i - 1] * i % mod;
        }

        // nCr up to 500
        vector<vector<ll>> ncr(501, vector<ll>(501, 0));
        ncr[0][0] = 1;
        for (int i = 1; i < 501; i++) {
            ncr[i][0] = 1;
            for (int j = 1; j < 501; j++) {
                ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod;
                if (ncr[i][j] == 0) ncr[i][j] += mod;
            }
        }

        ll res = 0;
        for (int i = n - 2; i >= 0; i--) {
            int cnt = n - i;
            int pre = n - cnt;
            ll com = (ncr[n][pre] * fact[pre]) % mod;
            if (com == 0) com += mod;
            ll sum = 0;

            for (int dif = 1; dif < cnt; dif++) {
                for (int inv = dif; inv < (int)dp[0].size(); inv++) {
                    if (dp[cnt - 1][inv] == 0) break;
                    if (inv - dif - 1 < 0) continue;
                    ll x = dp[cnt - 2][inv];
                    ll y = sums[cnt - 2][inv - dif - 1];
                    x = (x * y) % mod;
                    if (x == 0) x += mod;
                    sum = (sum + x * (cnt - dif)) % mod;
                }
            }
            res = (res + sum * com) % mod;
            if (res == 0) res += mod;
        }

        cout << (res % mod) << '\n';
    }
    return 0;
}

