            res = (res + mod) % mod;
        }
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        out.println(res % mod);
        out.flush();
    }
    static long factorial(int n, int mod) {
        long f = 1;
        for (int i = 2; i <= n; ++i) f = (f * i) % mod;
