        for (int i = 0; i < dp.length; i++) {
            long acc = 0;
            for (int j = 0; j < dp[0].length; j++) {
                acc = (acc + dp[i][j]) % mod;
                if (acc == 0) acc += mod;
                psum[i][j] = acc;
            }
