            if (u == v) continue;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
    }

    int v = adj.size();
    int e = 0;
    for (int i = 0; i < v; ++i) e += adj[i].size();
    e /= 2;

    int comps = 0;
    vector<bool> was(v, false);
    for (int i = 0; i < v; ++i) {
        if (!was[i]) {
            ++comps;
            dfs(i, was, adj);
        }
    }

    cout << 1 + comps + e - v << '\n';
    return 0;
}

