            getId(p, pointId, adj);
        }
        int m = uniqueAngles.size();
        for (int j = 0; j < m; ++j) {
            Point p = circles[i].o.add(dir.rotate(uniqueAngles[j]));
            Point q = circles[i].o.add(dir.rotate(uniqueAngles[(j + 1) % m]));
