int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    int nk = 0, nv = 0, no = 0;
    vector<int> kpos(n), vpos(n), opos(n);
    vector<int> snk(n + 1, 0), snv(n + 1, 0), sno(n + 1, 0);

    for (int i = 0; i < n; ++i) {
        char ch = s[i];
        if (ch == 'V') {
            vpos[nv++] = i;
        } else if (ch == 'K') {
            kpos[nk++] = i;
        } else {
            opos[no++] = i;
        }
        snk[i + 1] = nk;
        snv[i + 1] = nv;
        sno[i + 1] = no;
    }

    int dimV = nv + 1;
    int dimO = no + 1;
    int dimK = nk + 1;
    int total = dimK * dimV * dimO;

    vector<int> best0(total, INF);
    vector<int> best1(total, INF);

    auto idx = [&](int k, int v, int o) -> int {
        return k * dimV * dimO + v * dimO + o;
    };

    best0[idx(0, 0, 0)] = 0;

    for (int k = 0; k <= nk; ++k) {
        for (int v = 0; v <= nv; ++v) {
            for (int o = 0; o <= no; ++o) {
                int cur0 = best0[idx(k, v, o)];
                int cur1 = best1[idx(k, v, o)];

                // Place K (only if last was not V, i.e., from cur0)
                if (k < nk && cur0 < INF) {
                    int cost = max(snv[kpos[k]] - v, 0) + max(sno[kpos[k]] - o, 0);
                    int &target = best0[idx(k + 1, v, o)];
                    target = min(target, cur0 + cost);
                }

                // Place V (always allowed)
                if (v < nv) {
                    int cost = max(snk[vpos[v]] - k, 0) + max(sno[vpos[v]] - o, 0);
                    if (cur0 < INF) {
                        int &target = best1[idx(k, v + 1, o)];
                        target = min(target, cur0 + cost);
                    }
                    if (cur1 < INF) {
                        int &target = best1[idx(k, v + 1, o)];
                        target = min(target, cur1 + cost);
                    }
                }

                // Place O (always allowed)
                if (o < no) {
                    int cost = max(snv[opos[o]] - v, 0) + max(snk[opos[o]] - k, 0);
                    if (cur0 < INF) {
                        int &target = best0[idx(k, v, o + 1)];
                        target = min(target, cur0 + cost);
                    }
                    if (cur1 < INF) {
                        int &target = best0[idx(k, v, o + 1)];
                        target = min(target, cur1 + cost);
                    }
                }
            }
        }
    }

    int ans = min(best0[idx(nk, nv, no)], best1[idx(nk, nv, no)]);
    cout << ans << endl;

    return 0;
}

