int fast(const string& s) {
    string t = prepare(s);
    int n = t.size();
    vector<int> a(n);
    vector<vector<int>> pos(3, vector<int>(n));
    vector<int> sz(3, 0);
    vector<vector<vector<int>>> cntHere(3, vector<vector<int>>(n, vector<int>(3)));
    vector<vector<int>> pref(n + 1, vector<int>(3, 0));
    pref[0] = {0, 0, 0};

    for (int i = 0; i < n; ++i) {
        int c = STR.find(t[i]);
        a[i] = c;
        cntHere[c][sz[c]] = pref[i];
        pos[c][sz[c]] = i;
        sz[c]++;
        pref[i + 1] = pref[i];
        pref[i + 1][c]++;
    }

    int sz0 = sz[0], sz1 = sz[1], sz2 = sz[2];
    int dim0 = sz0 + 1, dim1 = sz1 + 1, dim2 = sz2 + 1;
    int total = 2 * dim0 * dim1 * dim2;
    vector<int> dp(total, INF);
    auto idx = [&](int last, int j0, int j1, int j2) -> int {
        return ((last * dim0 + j0) * dim1 + j1) * dim2 + j2;
    };
    dp[idx(0, 0, 0, 0)] = 0;

