import java.io.*;
import java.util.*;

public class C5 {

    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;

    void submit() throws IOException {
        nextInt();
        String s = nextToken();
        out.println(fast(s));
    }

    static final String BAD = "VK";

    String prepare(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (BAD.indexOf(c) != -1) {
                sb.append(c);
            } else {
                sb.append('A');
            }
        }
        return sb.toString();
    }

    int slow(String s) {
        s = prepare(s);
        HashMap<String, Integer> map = new HashMap<>();
        ArrayDeque<String> que = new ArrayDeque<>();
        que.add(s);
        map.put(s, 0);

        while (true) {
            s = que.poll();
            int curD = map.get(s);
            if (s.indexOf(BAD) == -1) {
                return curD;
            }

            for (int i = 0; i < s.length() - 1; i++) {
                String nxt = swap(s, i, i + 1);
                if (nxt != null && !map.containsKey(nxt)) {
                    map.put(nxt, curD + 1);
                    que.add(nxt);
                }
            }
        }
    }

    String swap(String s, int i, int j) {
        if (s.charAt(i) == s.charAt(j)) {
            return null;
        }
        char[] buf = s.toCharArray();
        char tmp = buf[i];
        buf[i] = buf[j];
        buf[j] = tmp;
        return new String(buf);
    }

    static final String STR = "VKA";

    int fast(String s) {
        s = prepare(s);
        int n = s.length();
        int[] a = new int[n];
        int[][] pos = new int[3][n];
        int[] sz = new int[3];
        int[][][] cntHere = new int[3][n][3];
        int[][] pref = new int[n + 1][];
        pref[0] = new int[] { 0, 0, 0 };

        for (int i = 0; i < n; i++) {
            a[i] = STR.indexOf(s.charAt(i));
            int c = a[i];
            cntHere[c][sz[c]] = pref[i].clone();
            pos[c][sz[c]++] = i;
            pref[i + 1] = pref[i].clone();
            pref[i + 1][c]++;
        }

        int[][][][] dp = new int[2][sz[0] + 1][sz[1] + 1][sz[2] + 1];
        for (int i = 0; i < 2; i++) {
            for (int j0 = 0; j0 <= sz[0]; j0++) {
                for (int j1 = 0; j1 <= sz[1]; j1++) {
                    Arrays.fill(dp[i][j0][j1], INF);
                }
            }
        }

        int ans = INF;
        dp[0][0][0][0] = 0;
