int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<int> cnt(3, 0);
    vector<vector<int>> pos(3);
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        int idx;
        if (c == 'K') idx = 0;
        else if (c == 'V') idx = 1;
        else idx = 2;
        pos[idx].push_back(i);
        cnt[idx]++;
    }

    int c0 = cnt[0], c1 = cnt[1], c2 = cnt[2];
    int dim0 = c0 + 1, dim1 = c1 + 1, dim2 = c2 + 1;
    int total = 2 * dim0 * dim1 * dim2;
    vector<int> dp(total, INT_MAX / 2);

    auto idx = [&](int last, int i0, int i1, int i2) -> int {
        return ((last * dim0 + i0) * dim1 + i1) * dim2 + i2;
    };

    dp[idx(0, 0, 0, 0)] = 0;

    for (int i0 = 0; i0 <= c0; ++i0) {
        for (int i1 = 0; i1 <= c1; ++i1) {
            for (int i2 = 0; i2 <= c2; ++i2) {
                for (int last = 0; last < 2; ++last) {
                    int cur = dp[idx(last, i0, i1, i2)];
                    if (cur >= INT_MAX / 2) continue;

                    // try to place a K (type 0) only if last == 0
                    if (i0 < c0 && last == 0) {
                        int swaps = 0;
                        int p0 = pos[0][i0];
                        for (int i = i1; i < c1 && pos[1][i] < p0; ++i) swaps++;
                        for (int i = i2; i < c2 && pos[2][i] < p0; ++i) swaps++;
                        int nxt = idx(0, i0 + 1, i1, i2);
                        dp[nxt] = min(dp[nxt], cur + swaps);
                    }

                    // try to place a V (type 1)
                    if (i1 < c1) {
                        int swaps = 0;
                        int p1 = pos[1][i1];
                        for (int i = i0; i < c0 && pos[0][i] < p1; ++i) swaps++;
                        for (int i = i2; i < c2 && pos[2][i] < p1; ++i) swaps++;
                        int nxt = idx(1, i0, i1 + 1, i2);
                        dp[nxt] = min(dp[nxt], cur + swaps);
                    }

                    // try to place a J (type 2)
                    if (i2 < c2) {
                        int swaps = 0;
                        int p2 = pos[2][i2];
                        for (int i = i0; i < c0 && pos[0][i] < p2; ++i) swaps++;
                        for (int i = i1; i < c1 && pos[1][i] < p2; ++i) swaps++;
                        int nxt = idx(0, i0, i1, i2 + 1);
                        dp[nxt] = min(dp[nxt], cur + swaps);
                    }
                }
            }
        }
    }

    int ans = min(dp[idx(0, c0, c1, c2)], dp[idx(1, c0, c1, c2)]);
    cout << ans << endl;

    return 0;
}

