import java.io.*;
import java.util.*;

public class Codeforces {
    public static void main(String args[]) throws Exception {
        BufferedReader bu = new BufferedReader(new InputStreamReader(System.in));
        String line = bu.readLine();
        char[] s = line.toCharArray();
        boolean hasX = false;
        int n = s.length;
        for (int i = 0; i < n; i++) hasX |= s[i] == 'X';
        int ans = 0;
        for (int xVal = 0; xVal < 10; xVal++) {
            char[] t = replaceX(s, xVal);
            if (t[0] == '0') continue;
            ans += countDivisibleBy25(t);
            if (!hasX) break;
        }
        if (n == 1 && (s[0] == '_' || s[0] == 'X' || s[0] == '0')) ans++;
        System.out.println(ans);
    }

    static char[] replaceX(char[] s, int xVal) {
        int n = s.length;
        char[] res = new char[n];
        for (int i = 0; i < n; i++) {
            if (s[i] == 'X') res[i] = (char) ('0' + xVal);
            else res[i] = s[i];
        }
        return res;
    }

    static int countDivisibleBy25(char[] s) {
        int n = s.length;
        int[][] dp = new int[2][25];
        int cur = 1;
        dp[0][0] = 1;
        for (int j = 0; j < n; j++) {
            Arrays.fill(dp[cur], 0);
            int lo = 0, hi = 9;
            if (s[j] != '_') {
                lo = hi = s[j] - '0';
            } else if (j == 0) lo++;
            for (int r = 0; r < 25; r++) {
                if (dp[cur ^ 1][r] == 0) continue;
                for (int d = lo; d <= hi; d++) {
                    int nr = (r * 10 + d) % 25;
                    dp[cur][nr] += dp[cur ^ 1][r];
                }
            }
            cur ^= 1;
        }
        return dp[cur ^ 1][0];
    }
}

