using namespace std;

string replaceX(const string& s, int xVal) {
    int n = s.length();
    string res(n, ' ');
    for (int i = 0; i < n; i++) {
        if (s[i] == 'X')
            res[i] = '0' + xVal;
        else
            res[i] = s[i];
    }
    return res;
}

int countDivisibleBy25(const string& s) {
    int n = s.length();
    int dp[2][25];
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;
    int cur = 1;
    for (int j = 0; j < n; j++) {
        fill(dp[cur], dp[cur] + 25, 0);
        int lo = 0, hi = 9;
        if (s[j] != '_') {
            lo = hi = s[j] - '0';
        } else if (j == 0) {
            lo++;
        }
        for (int r = 0; r < 25; r++) {
            if (dp[cur ^ 1][r] == 0) continue;
            for (int d = lo; d <= hi; d++) {
