#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    // Special cases
    if (n == 1 && s[0] == '0') {
        cout << 1 << endl;
        return 0;
    }
    if (s[0] == '0') {
        cout << 0 << endl;
        return 0;
    }
    if (n == 1 && (s[0] == 'X' || s[0] == '_')) {
        cout << 1 << endl;
        return 0;
    }

    // dp[i][rem][x] : number of ways for suffix starting at i,
    // with current remainder rem, and assigned digit for X = x (10 means unassigned)
    vector<vector<vector<long long>>> dp(n + 1,
        vector<vector<long long>>(25, vector<long long>(11, 0)));

    // Base case: i == n
    for (int x = 0; x <= 10; ++x) {
        dp[n][0][x] = 1; // remainder 0 is valid
    }

    // Fill DP from n-1 down to 0
    for (int i = n - 1; i >= 0; --i) {
        for (int rem = 0; rem < 25; ++rem) {
            for (int x = 0; x <= 10; ++x) {
                long long ans = 0;
                char c = s[i];
                if (c == '_') {
                    for (int d = 0; d < 10; ++d) {
                        if (i == 0 && d == 0) continue; // no leading zero
                        int new_rem = (rem * 10 + d) % 25;
                        ans += dp[i + 1][new_rem][x];
                    }
                } else if (c == 'X') {
                    if (x != 10) {
                        // X already assigned
                        int d = x;
                        int new_rem = (rem * 10 + d) % 25;
                        ans += dp[i + 1][new_rem][x];
                    } else {
                        // X not assigned yet, try all digits
                        for (int d = 0; d < 10; ++d) {
                            if (i == 0 && d == 0) continue;
                            int new_rem = (rem * 10 + d) % 25;
                            ans += dp[i + 1][new_rem][d]; // assign d to X
                        }
                    }
                } else { // digit
                    int d = c - '0';
                    int new_rem = (rem * 10 + d) % 25;
                    ans += dp[i + 1][new_rem][x];
                }
                dp[i][rem][x] = ans;
            }
        }
    }

    // Initial state: i=0, rem=0, x=10 (unassigned)
    cout << dp[0][0][10] << endl;
    return 0;
}

