        int x = -1;
        for (int i = s.length() - 1; i >= 0; i--) {
            int d = n % 10;
            if (s.charAt(i) == 'X') {
                if (x >= 0 && x != d) {
                    return false;
                }
                x = d;
            } else if (s.charAt(i) != '_') {
                if (s.charAt(i) - '0' != d) {
                    return false;
                }
            }
            if (s.length() > 1 && i == 0 && d == 0) {
                return false;
            }
            n /= 10;
        }
        return true;
    }
    static class Reader {
        BufferedReader in;
        StringTokenizer st;
        public Reader() {
            in = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
