public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        System.out.println(countMatches(s, 0, new int[1]));
        sc.close();
    }
    static int countMatches(String s, int pos, int[] x) {
        if (pos == s.length()) {
            int num = 0;
            for (int i = 0; i < s.length(); i++) num = num * 10 + x[i];
            if (s.length() > 1 && x[0] == 0) return 0;
            if (num % 25 == 0) return 1;
            else return 0;
        }
        char c = s.charAt(pos);
        int sum = 0;
        if (c == '_') {
            for (int d = 0; d <= 9; d++) {
                x[pos] = d;
                sum += countMatches(s, pos + 1, x);
            }
        } else if (c == 'X') {
            for (int d = 0; d <= 9; d++) {
                x[pos] = d;
                if (pos == 0 || x[0] == d) {
                    sum += countMatches(s, pos + 1, x);
                }
            }
        } else {
            x[pos] = c - '0';
            sum += countMatches(s, pos + 1, x);
        }
        return sum;
    }
}

