    for (long long i = 5; i * i <= N; i += 6) {
        if (N % i == 0 || N % (i + 2) == 0) return false;
    }
    return true;
}

static string reverse(const string& str) {
    if (str.empty()) return str;
    return string(str.rbegin(), str.rend());
}

static string repeat(char ch, int repeat) {
    if (repeat <= 0) return "";
    return string(repeat, ch);
}

static vector<int> manacher(const string& s) {
    int n = s.size();
    vector<int> d1(n);
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
        while (0 <= i - k && i + k < n && s[i - k] == s[i + k]) k++;
        d1[i] = k--;
        if (i + k > r) {
            l = i - k;
            r = i + k;
        }
    }
    return d1;
}

static vector<int> kmp(const string& s) {
    int n = s.size();
    vector<int> res(n);
    for (int i = 1; i < n; ++i) {
        int j = res[i - 1];
        while (j > 0 && s[i] != s[j]) j = res[j - 1];
        if (s[i] == s[j]) ++j;
        res[i] = j;
    }
    return res;
}

// ---------- Solve ----------
static void solve() {
    int n = i();
    double p = d();

    int l = 0, r = n - 1;
    while (l < r) {
        int m = (l + r) / 2;
        double x = cal(m, n);
        if (x >= p) r = m;
        else l = m + 1;
    }
    out.println(l);
}

int main() {
    srand(time(0));
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt = 1;
    while (tt--) {
        solve();
    }
    out.flush();
    return 0;
}

