using namespace std;

const int MD = 998244353;
vector<long long> ww(21), ww_(21);

long long power(long long a, int k) {
    long long res = 1;
    while (k) {
        if (k & 1) res = res * a % MD;
        a = a * a % MD;
        k >>= 1;
    }
    return res;
}

void init() {
    for (int h = 0; h <= 20; h++) {
        ww[h] = power(3, (MD - 1) >> h);
        ww_[h] = power(3, MD - 1 - ((MD - 1) >> h));
    }
}

void ntt(vector<int>& aa, int n, bool inverse) {
    for (int i = 1, j = 0; i < n; i++) {
        int b = n;
        do {
            j ^= b >>= 1;
        } while ((j & b) == 0);
        if (i < j) {
            swap(aa[i], aa[j]);
        }
    }
    for (int h = 0, b; (b = 1 << h) < n; h++) {
        long long w_ = inverse ? ww_[h + 1] : ww[h + 1];
        for (int i = 0; i < n; i += b * 2) {
            long long w = 1;
            for (int j = 0; j < b; j++) {
                int l = i + j, r = l + b;
                long long u = aa[l];
                long long v = aa[r] * w % MD;
                aa[l] = (u + v) % MD;
                aa[r] = (u - v) % MD;
                w = w * w_ % MD;
            }
        }
    }
}

