    while (n_ < n * 9 + 1)
        n_ <<= 1;
    vector<int> aa(n_, 0);
    for (int i = 0; i < k; i++) {
        int d;
        cin >> d;
        aa[d] = 1;
    }
    ntt(aa, n_, false);
    for (int i = 0; i < n_; i++)
        aa[i] = power(aa[i], n);
    ntt(aa, n_, true);
    long long v = power(n_, MD - 2);
    for (int i = 0; i < n_; i++) {
        long long temp = aa[i];
        temp = temp * v % MD;
        aa[i] = (int)temp;
