static void fft(vector<double>& a, vector<double>& b, bool inverse) {
    int n = a.size();
    int shift = 32 - __builtin_ctz(n);
    for (int i = 1; i < n; i++) {
        int j = __builtin_rev(i << shift);
        if (i < j) {
            swap(a[i], a[j]);
            swap(b[i], b[j]);
        }
    }
    for (int len = 2; len <= n; len <<= 1) {
        int halfLen = len >> 1;
