            for (int k = 0, s = j << (h - i), t = s | (1 << (h - i - 1)); k < 1 << (h - i - 1); k++, s++, t++) {
                ll u = (dst[s] - dst[t] + 2 * P) * wws[k];
                dst[s] += dst[t];
                if (dst[s] >= 2 * P) dst[s] -= 2 * P;
                unsigned long long uu = u;
                unsigned long long Q = ((uu << 32) * (unsigned long long)J) >> 32;
                dst[t] = (uu >> 32) - ((Q * P) >> 32) + P;
            }
        }
        if (i < h - 1) {
            for (int k = 0; k < 1 << (h - i - 2); k++) wws[k] = wws[k * 2];
        }
    }
    for (int i = 0; i < n; i++) {
        if (dst[i] >= P) dst[i] -= P;
    }
    for (int i = 0; i < n; i++) {
        int rev = 0;
        for (int j = 0; j < h; j++) {
            rev = (rev << 1) | ((i >> j) & 1);
        }
        if (i < rev) {
            swap(dst[i], dst[rev]);
        }
    }
    if (inv) {
        ll in = invl(n, P);
        for (int i = 0; i < n; i++) dst[i] = modh(dst[i] * in, M, H, P);
    }
    return dst;
}

vector<ll> multiplyPolynomials(const vector<ll>& a, const vector<ll>& b, int P, int g) {
    int m = max(2, highestOneBit(max((int)a.size(), (int)b.size()) - 1) << 2);
    vector<ll> fa = ntt(a, m, false, P, g);
    vector<ll> fb;
    if (&a == &b) fb = fa;
    else fb = ntt(b, m, false, P, g);
    for (int i = 0; i < m; i++) {
        fa[i] = (fa[i] * fb[i]) % P;
    }
    return ntt(fa, m, true, P, g);
}

