// FFT functions
void fft(vector<double>& a, vector<double>& b, bool inverse) {
    int n = a.size();
    int shift = 32 - __builtin_ctz(n);
    for (int i = 1; i < n; i++) {
        int j = __builtin_bitreverse32(i << shift);
        if (i < j) {
            swap(a[i], a[j]);
            swap(b[i], b[j]);
        }
    }
    for (int len = 2; len <= n; len <<= 1) {
        int halfLen = len >> 1;
        vector<double> cs(halfLen), sn(halfLen);
        for (int i = 0; i < halfLen; i++) {
            double angle = 2 * M_PI * i / len * (inverse ? -1 : 1);
            cs[i] = cos(angle);
            sn[i] = sin(angle);
        }
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < halfLen; j++) {
                double wA = cs[j];
                double wB = sn[j];
                double uA = a[i + j];
                double uB = b[i + j];
                double vA = a[i + j + halfLen] * wA - b[i + j + halfLen] * wB;
                double vB = a[i + j + halfLen] * wB + b[i + j + halfLen] * wA;
                a[i + j] = uA + vA;
                b[i + j] = uB + vB;
                a[i + j + halfLen] = uA - vA;
                b[i + j + halfLen] = uB - vB;
            }
        }
    }
    // Note: inverse division is not done here; it's handled in multiplyMod
