#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const ll MOD = 998244353;
const ll W = 646;
const int SZ = 1 << 20;

ll modpow(ll x, int p) {
    if (p == 0) return 1;
    if (p % 2 == 1) return modpow(x, p - 1) * x % MOD;
    ll y = modpow(x, p / 2);
    return y * y % MOD;
}

ll modinv(ll x) {
    return modpow(x, MOD - 2);
}

class FFT {
public:
    vector<ll> wtable, winvtable;
    ll winv, szinv;

    FFT() {
        winv = modinv(W);
        szinv = modinv(SZ);
        wtable.resize(SZ);
        winvtable.resize(SZ);
        wtable[0] = 1;
        winvtable[0] = 1;
        for (int i = 1; i < SZ; ++i) {
            wtable[i] = wtable[i - 1] * W % MOD;
            winvtable[i] = winvtable[i - 1] * winv % MOD;
        }
    }

    vector<ll> fft_transform(const vector<ll>& a) {
        vector<ll> ans(SZ, 0);
        ll wth = 1;
        for (int i = 0; i < SZ; ++i) {
            ll x = 1;
            for (size_t j = 0; j < a.size(); ++j) {
                ans[i] = (ans[i] + a[j] * x) % MOD;
                x = x * wth % MOD;
            }
            wth = wth * W % MOD;
        }
        return ans;
    }

    vector<ll> dft(int first, int pow, bool straight, const vector<ll>& v) {
        if (pow == SZ) {
            return {v[first]};
        }
        vector<ll> zero = dft(first, 2 * pow, straight, v);
        vector<ll> one = dft(first + pow, 2 * pow, straight, v);
        int n = zero.size();
        vector<ll> ans(2 * n);
        for (int i = 0; i < n; ++i) {
            ll factor = straight ? wtable[i * pow] : winvtable[i * pow];
            ans[i] = (zero[i] + factor * one[i]) % MOD;
        }
        for (int i = 0; i < n; ++i) {
            ll factor = straight ? wtable[i * pow] : winvtable[i * pow];
            ans[n + i] = ((zero[i] - factor * one[i]) % MOD + MOD) % MOD;
        }
        return ans;
    }

    vector<ll> fft_inverse(const vector<ll>& a) {
        vector<ll> x = dft(0, 1, false, a);
        for (int i = 0; i < SZ; ++i) {
            x[i] = x[i] * szinv % MOD;
        }
        return x;
    }

    vector<ll> pow_vector(vector<ll> a, int p) {
        for (int i = 0; i < SZ; ++i) {
            a[i] = modpow(a[i], p);
        }
        return a;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;
    vector<ll> arr(10, 0);
    for (int i = 0; i < k; ++i) {
        int d;
        cin >> d;
        arr[d] = 1;
    }

    FFT fft;
    vector<ll> x = fft.fft_transform(arr);
    x = fft.pow_vector(x, n / 2);
    vector<ll> res = fft.fft_inverse(x);

    ll ans = 0;
    for (int i = 0; i < SZ; ++i) {
        ans = (ans + res[i] * res[i]) % MOD;
    }
    cout << ans << '\n';

    return 0;
}

