ll mod_pow(ll x, int p) {
    if (p == 0) return 1;
    if (p % 2 == 1) return mod_pow(x, p - 1) * x % MOD;
    ll y = mod_pow(x, p / 2);
    return y * y % MOD;
}

ll mod_inv(ll a) {
    // extended Euclidean algorithm
    ll t = 0, newt = 1;
    ll r = MOD, newr = a;
    while (newr != 0) {
        ll quotient = r / newr;
        ll tmp = t - quotient * newt;
        t = newt;
        newt = tmp;
        tmp = r - quotient * newr;
        r = newr;
        newr = tmp;
    }
    if (r != 1) return -1; // not invertible
    if (t < 0) t += MOD;
    return t;
}

class Vector {
