#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

int n, k;
vector<pair<int,int>> segs;
vector<int> l, delt;
vector<vector<int>> dp0, dp1;

struct RMQ {
    int n, k;
    vector<vector<int>> min;

    RMQ(const vector<int>& a) {
        n = a.size();
        k = 0;
        int tmp = n;
        while (tmp > 0) {
            tmp >>= 1;
            k++;
        }
        // k = floor(log2(n)) + 1
        min.assign(k, vector<int>(n));
        for (int i = 0; i < n; i++) min[0][i] = a[i];
        for (int i = 1; i < k; i++) {
            int step = 1 << (i - 1);
            for (int j = 0; j + step < n; j++) {
                min[i][j] = std::min(min[i-1][j], min[i-1][j + step]);
            }
        }
    }

    int query(int a, int b) {
        int len = b - a + 1;
        int z = 0;
        int tmp = len;
        while (tmp > 1) {
            tmp >>= 1;
            z++;
        }
        // z = floor(log2(len))
        return std::min(min[z][a], min[z][b - (1 << z) + 1]);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> k;
    segs.resize(k);
    for (int i = 0; i < k; i++) {
        cin >> segs[i].first >> segs[i].second;
    }

    // sort by start
    sort(segs.begin(), segs.end());

    // merge overlapping intervals
    vector<pair<int,int>> finSeg;
    int i = 0;
    while (i < k) {
        int lo = segs[i].first;
        int hi = segs[i].first;
        while (i < k && segs[i].first <= hi) {
            hi = max(hi, segs[i].second);
            i++;
        }
        finSeg.push_back({lo, hi});
    }

    k = finSeg.size();
    segs = finSeg;
    l.resize(k);
    delt.resize(k);
    for (int i = 0; i < k; i++) {
        l[i] = segs[i].second - segs[i].first;
        delt[i] = (i < k - 1) ? segs[i+1].first - segs[i].second : 2 * n - segs[i].second;
    }

    // dp0 and dp1: dimensions (k+1) x (2*n+1)
    dp0.assign(k+1, vector<int>(2*n+1, n));
    dp1.assign(k+1, vector<int>(2*n+1, n));
    dp0[k][n] = 0;
    dp1[k][n] = 0;

    RMQ rmq0(dp0[k]);
    RMQ rmq1(dp1[k]);

    for (int i = k-1; i >= 0; i--) {
        for (int j = 0; j <= 2*n; j++) {
            // first assignment for dp0
            if (j + l[i] + delt[i] <= 2*n)
