        for (int i = 0; i < k; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            interval.push_back({a, b});
        }
        interval.push_back({2 * N, 2 * N});
        int cur = 0;
        vector<SegmentTree> dp(2, SegmentTree(N + 1));
        dp[0].assign(0, 0);
        for (size_t i = 0; i < interval.size(); i++) {
            for (int j = N; j >= 0; j--) {
                dp[0].assign(j, dp[0].getVal(j - (interval[i].first - cur)));
