#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

const int INF = 1e9;

class SegmentTree {
private:
    vector<int> tree;
    vector<int> arr;
    int size;

    void build(int n, int tl, int tr) {
        if (tl == tr) {
            tree[n] = arr[tl];
        } else {
            int tm = (tl + tr) / 2;
            build(2 * n, tl, tm);
            build(2 * n + 1, tm + 1, tr);
            tree[n] = min(tree[2 * n], tree[2 * n + 1]);
        }
    }

    int queryUtil(int n, int tl, int tr, int l, int r) {
        if (l > r) return INF;
        if (tl == l && tr == r) return tree[n];
        int tm = (tl + tr) / 2;
        return min(queryUtil(2 * n, tl, tm, l, min(r, tm)),
                   queryUtil(2 * n + 1, tm + 1, tr, max(tm + 1, l), r));
    }

    void update(int n, int tl, int tr, int pos, int val) {
        if (tl == tr) {
            tree[n] = val;
        } else {
            int tm = (tl + tr) / 2;
            if (pos <= tm) update(2 * n, tl, tm, pos, val);
            else update(2 * n + 1, tm + 1, tr, pos, val);
            tree[n] = min(tree[2 * n], tree[2 * n + 1]);
        }
    }

public:
    SegmentTree(int N) {
        size = N;
        tree.assign(4 * N, INF);
        arr.assign(N, INF);
        build(1, 0, size - 1);
    }

    int query(int l, int r) {
        if (r < 0) return INF;
        return queryUtil(1, 0, size - 1, max(0, l), r);
    }

    void assign(int n, int val) {
        arr[n] = val;
        update(1, 0, size - 1, n, val);
    }

    int getVal(int i) {
        if (i < 0) return INF;
        return arr[i];
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, k;
    cin >> N >> k;

    vector<pair<int, int>> interval;
    for (int i = 0; i < k; ++i) {
        int a, b;
        cin >> a >> b;
        interval.push_back({a, b});
    }
    interval.push_back({2 * N, 2 * N});

    int cur = 0;
    SegmentTree dp[2] = {SegmentTree(N + 1), SegmentTree(N + 1)};
    dp[0].assign(0, 0);

    for (size_t i = 0; i < interval.size(); ++i) {
        int seg0 = interval[i].first;
        int seg1 = interval[i].second;
        for (int j = N; j >= 0; --j) {
            dp[0].assign(j, dp[0].getVal(j - (seg0 - cur)));
        }
        cur = seg1;
        int sz = seg1 - seg0;
        for (int j = N; j >= 0; --j) {
            int put[2];
            for (int z = 0; z <= 1; ++z) {
                int twoSwaps = dp[z].query(j - sz, j);
                int oneSwap = dp[(z + 1) % 2].query(j - sz, j);
                int noSwap;
                if (z == 1) {
                    noSwap = dp[z].getVal(j);
                } else {
                    noSwap = dp[z].getVal(j - sz);
                }
                put[z] = min(twoSwaps + 2, min(oneSwap + 1, noSwap));
            }
            dp[0].assign(j, put[0]);
            dp[1].assign(j, put[1]);
        }
    }

    int ans = min(dp[0].query(N, N), dp[1].query(N, N));
    if (ans >= INF) {
        cout << "Hungry\n";
    } else {
        cout << "Full\n" << ans << "\n";
    }

    return 0;
}

