#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <climits>

using namespace std;

const int INF = (int)1e8;

struct Node {
    Node *left, *right;
    int minVal;
    int batchSetValue;
    bool dirty;

    Node() : left(nullptr), right(nullptr), minVal(INF), batchSetValue(0), dirty(false) {}

    void pushUp() {
        minVal = min(left->minVal, right->minVal);
    }

    void setValue(int val) {
        minVal = val;
        batchSetValue = val;
        dirty = true;
    }

    void pushDown() {
        if (dirty) {
            left->setValue(batchSetValue);
            right->setValue(batchSetValue);
            dirty = false;
        }
    }
};

Node* build(int l, int r) {
    Node* node = new Node();
    if (l != r) {
        int m = (l + r) >> 1;
        node->left = build(l, m);
        node->right = build(m + 1, r);
    }
    return node;
}

int query(int f, int t, int l, int r, Node* node) {
    if (f > r || t < l) return INF;
    if (f <= l && r <= t) return node->minVal;
    node->pushDown();
    int m = (l + r) >> 1;
    return min(query(f, t, l, m, node->left), query(f, t, m + 1, r, node->right));
}

void update(int i, int l, int r, int val, Node* node) {
    if (i > r || i < l) return;
    if (l == r) {
        node->minVal = min(node->minVal, val);
        return;
    }
    node->pushDown();
    int m = (l + r) >> 1;
    update(i, l, m, val, node->left);
    update(i, m + 1, r, val, node->right);
    node->pushUp();
}

void toArray(int l, int r, vector<int>& data, Node* node) {
    if (l == r) {
        data[l] = node->minVal;
        return;
    }
    node->pushDown();
    int m = (l + r) >> 1;
    toArray(l, m, data, node->left);
    toArray(m + 1, r, data, node->right);
}

void fromArray(int l, int r, const vector<int>& data, Node* node) {
    if (l == r) {
        node->minVal = data[l];
        return;
    }
    node->dirty = false;
    int m = (l + r) >> 1;
    fromArray(l, m, data, node->left);
    fromArray(m + 1, r, data, node->right);
    node->pushUp();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<vector<int>> intervals(k + 2, vector<int>(2));
    for (int i = 1; i <= k; ++i) {
        cin >> intervals[i][0] >> intervals[i][1];
    }
    intervals[k + 1][0] = 2 * n;
    intervals[k + 1][1] = 2 * n;
    k++;

    Node* loop[2];
    loop[0] = build(0, n);
    loop[1] = build(0, n);

    vector<int> data(n + 1, INF);

    for (int i = 1; i <= k; ++i) {
        Node* curDp = loop[i & 1];
        Node* lastDp = loop[(i - 1) & 1];

        int intervalLength = intervals[i][1] - intervals[i][0];
        int middleLength = intervals[i][0] - intervals[i - 1][1];

        toArray(0, n, data, lastDp);
        // shift data right by (intervalLength + middleLength) and fill left with INF
        int shift = intervalLength + middleLength;
        if (shift > 0) {
