#include <cstdio>
#include <cstring>
#include <algorithm>
#include <vector>

const int INF = (int)1e8;

struct Node {
    Node* left;
    Node* right;
    int batchSetValue;
    bool dirty;
    int min;

    Node() : left(nullptr), right(nullptr), batchSetValue(0), dirty(false), min(0) {}

    void setValue(int val) {
        min = val;
        batchSetValue = val;
        dirty = true;
    }

    void pushDown() {
        if (dirty) {
            left->setValue(batchSetValue);
            right->setValue(batchSetValue);
            dirty = false;
        }
    }

    void pushUp() {
        min = std::min(left->min, right->min);
    }

    static Node* build(int l, int r) {
        Node* node = new Node();
        if (l != r) {
            int m = (l + r) >> 1;
            node->left = build(l, m);
            node->right = build(m + 1, r);
        }
        return node;
    }

    static void setValue(int f, int t, int l, int r, int val, Node* node) {
        if (f > r || t < l) return;
        if (f <= l && t >= r) {
            node->setValue(val);
            return;
        }
        node->pushDown();
        int m = (l + r) >> 1;
        setValue(f, t, l, m, val, node->left);
        setValue(f, t, m + 1, r, val, node->right);
        node->pushUp();
    }

    static int query(int f, int t, int l, int r, Node* node) {
        if (f > r || t < l) return INF;
        if (f <= l && r <= t) return node->min;
        node->pushDown();
        int m = (l + r) >> 1;
        return std::min(query(f, t, l, m, node->left), query(f, t, m + 1, r, node->right));
    }

    static void update(int i, int l, int r, int val, Node* node) {
        if (i > r || i < l) return;
        if (i <= l && i >= r) {
            node->min = std::min(node->min, val);
            return;
        }
        node->pushDown();
        int m = (l + r) >> 1;
        update(i, l, m, val, node->left);
        update(i, m + 1, r, val, node->right);
        node->pushUp();
    }

    static void toArray(int l, int r, int* data, Node* node) {
        if (l == r) {
            data[l] = node->min;
            return;
        }
        node->pushDown();
        int m = (l + r) >> 1;
        toArray(l, m, data, node->left);
        toArray(m + 1, r, data, node->right);
    }

    static void fromArray(int l, int r, int* data, Node* node) {
        if (l == r) {
            node->min = data[l];
            return;
        }
        node->dirty = false;
        int m = (l + r) >> 1;
        fromArray(l, m, data, node->left);
        fromArray(m + 1, r, data, node->right);
        node->pushUp();
    }
};

void solve() {
    int n, k;
    scanf("%d %d", &n, &k);

    std::vector<int> lefts(k + 2), rights(k + 2);
    for (int i = 1; i <= k; ++i) {
        scanf("%d %d", &lefts[i], &rights[i]);
    }
    lefts[k + 1] = 2 * n;
    rights[k + 1] = 2 * n;
    k++;

    Node* loop[2];
    loop[0] = Node::build(0, n);
    loop[1] = Node::build(0, n);

    int* data = new int[n + 1];

    for (int i = 1; i <= k; ++i) {
        Node* curDp = loop[i & 1];
        Node* lastDp = loop[(i - 1) & 1];

        int intervalLength = rights[i] - lefts[i];
        int middleLength = lefts[i] - rights[i - 1];

        Node::toArray(0, n, data, lastDp);

        int dest = std::min(n + 1, intervalLength + middleLength);
        int len = std::max(0, n + 1 - (intervalLength + middleLength));
        if (len > 0) {
            memmove(data + dest, data, len * sizeof(int));
        }
        std::fill(data, data + dest, INF);

        int minX = rights[i] - middleLength - intervalLength;
        int maxX = rights[i] - middleLength;
        for (int j = 0; j <= n; ++j) {
            int minNeedTime = Node::query(minX - j, maxX - j, 0, n, lastDp);
            data[j] = std::min(data[j], minNeedTime + 1);
        }

        for (int j = 0; j <= n; ++j) {
            int minNeedTime = Node::query(j - middleLength - intervalLength, j - middleLength, 0, n, lastDp);
            data[j] = std::min(data[j], minNeedTime + 2);
        }

        Node::fromArray(0, n, data, curDp);
    }

    int minFlipTime = Node::query(n, n, 0, n, loop[k & 1]);

    if (minFlipTime < INF) {
        printf("Full\n%d\n", minFlipTime);
    } else {
        printf("Hungry\n");
    }

    delete[] data;
    // Note: We do not delete the segment tree nodes for simplicity.
}

int main() {
    solve();
    fflush(stdout);
    return 0;
}

