import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.InputMismatchException;

public class F {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    void solve() {
        int n = ni(), K = ni();
        int[][] ts = new int[K][];
        long all = 0;
        for (int i = 0; i < K; i++) {
            ts[i] = na(2);
            all += ts[i][1] - ts[i][0];
        }
        int[] dpe = new int[n + 1];
        int[] dpo = new int[n + 1];
        Arrays.fill(dpe, 99999999);
        Arrays.fill(dpo, 99999999);
        if (ts[0][0] > n) {
            out.println("Hungry");
            return;
        }
        dpe[ts[0][0]] = 0;
        for (int i = 0; i < K; i++) {
            int[] ndpo = new int[n + 1];
            int[] ndpe = new int[n + 1];
            Arrays.fill(ndpo, 99999999);
            Arrays.fill(ndpe, 99999999);
            Deque<Integer> dq = new ArrayDeque<>();
            int w = ts[i][1] - ts[i][0];
            // Use while loops instead of for loops for the sliding window
            int j = 0;
            while (j <= n) {
                while (dq.size() > 0 && dpe[dq.peekLast()] >= dpe[j]) {
                    dq.pollLast();
                }
                while (dq.size() > 0 && dq.peekFirst() < j - w) {
                    dq.pollFirst();
                }
                dq.add(j);
                ndpo[j] = Math.min(ndpo[j], dpe[dq.peekFirst()] + 1);
                if (j + w <= n) ndpe[j + w] = Math.min(ndpe[j + w], dpe[j]);
                j++;
            }
            dq.clear();
            j = 0;
            while (j <= n) {
                while (dq.size() > 0 && dpo[dq.peekLast()] >= dpo[j]) {
                    dq.pollLast();
                }
                while (dq.size() > 0 && dq.peekFirst() < j - w) {
                    dq.pollFirst();
                }
                dq.add(j);
                ndpe[j] = Math.min(ndpe[j], dpo[dq.peekFirst()] + 1);
                ndpo[j] = Math.min(ndpo[j], dpo[j]);
                j++;
            }
            dpo = ndpo;
            dpe = ndpe;

            // Use a single loop for the mutual update
            for (int j = 0; j <= n; j++) {
                int min = Math.min(dpe[j], dpo[j] + 1);
                dpo[j] = Math.min(dpo[j], dpe[j] + 1);
                dpe[j] = min;
            }

            int s = (i == K - 1 ? 2 * n : ts[i + 1][0]) - ts[i][1];
            // Use a while loop for the shift
            int j = n;
            while (j >= s) {
                dpe[j] = dpe[j - s];
                j--;
            }
            j = Math.min(n, s - 1);
            while (j >= 0) {
                dpe[j] = 99999999;
                j--;
            }
        }
        int ans = Math.min(dpe[n], dpo[n]);
        if (ans >= 9999999) {
            out.println("Hungry");
        } else {
            out.println("Full");
            out.println(ans);
        }
    }

