static long long pow[16];

int solveIterative(long long x) {
    std::stack<std::pair<long long, int>> st;
    st.push({x, 0});
    std::unordered_map<long long, int> results;

    while (!st.empty()) {
        auto& top = st.top();
        long long val = top.first;

        if (val <= 11) {
            int base;
            if (val == 11) base = 2;
            else if (val == 10) base = 3;
            else if (val == 9) base = 4;
            else if (val == 8) base = 5;
            else if (val == 7) base = 6;
            else base = (int)val;
            results[val] = base;
            st.pop();
            continue;
        }

        if (top.second == 1) {
            int len = std::to_string(val).length();
            long long boof = 0;
            for (int i = 0; i <= len; i++)
                boof += pow[i];
            int res = INT_MAX;
            if (val > boof - val)
                res = std::min(res, len + 1 + results[boof - val]);
            boof -= pow[len];
            long long firstDigit = val / pow[len - 1];
            for (int d = 1; d <= 9; d++) {
                long long candidate = boof * d;
                if (d == firstDigit || d + 1 == firstDigit)
                    res = std::min(res, len * d + results[std::abs(candidate - val)]);
            }
            results[val] = res;
            st.pop();
        } else {
            top.second = 1;
            int len = std::to_string(val).length();
            long long boof = 0;
            for (int i = 0; i <= len; i++)
                boof += pow[i];
            if (val > boof - val) {
                long long child = boof - val;
                if (results.find(child) == results.end())
                    st.push({child, 0});
            }
            boof -= pow[len];
            long long firstDigit = val / pow[len - 1];
            for (int d = 1; d <= 9; d++) {
                long long candidate = boof * d;
                if (d == firstDigit || d + 1 == firstDigit) {
                    long long child = std::abs(candidate - val);
                    if (results.find(child) == results.end())
                        st.push({child, 0});
                }
            }
        }
    }
    return results[x];
}

int main() {
    pow[0] = 1;
    for (int i = 1; i <= 15; i++)
        pow[i] = pow[i - 1] * 10;

    std::string input;
    std::cin >> input;
    long long start = std::stoll(input);
    std::cout << solveIterative(start) << std::endl;
    return 0;
