    long long low;
    long long high;
    long long ret1;
    long long ret2;
};

long long ONES[17];

long long go(long long x, int len) {
    x = std::llabs(x);
    std::stack<Frame> st;
    st.push({x, len, 0, 0, 0, 0, 0});
    long long result = 0;
