                result = f.x / ONES[f.len] * f.len;
                st.pop();
                continue;
            }
            long long low = f.x / ONES[f.len];
            long long high = low + 1;
            f.low = low;
            f.high = high;
            f.state = 1;
            st.push({f.x - low * ONES[f.len], f.len - 1, 0, 0, 0, 0, 0});
