        ONES[i] = 10 * ONES[i-1] + 1;
    }
}

ll my_abs(ll x) {
    if (x >= 0) return x;
    if (x == LLONG_MIN) return x; // same as Java Math.abs for Long.MIN_VALUE
    return -x;
}

struct pair_hash {
    size_t operator()(const pair<ll, int>& p) const {
        return hash<ll>()(p.first) ^ (hash<int>()(p.second) << 1);
    }
};

unordered_map<pair<ll, int>, ll, pair_hash> memo;

ll go(ll x, int len) {
    x = my_abs(x);
    auto key = make_pair(x, len);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    ll res;
    if (x % ONES[len] == 0) {
