#include <iostream>
#include <string>
#include <algorithm>
#include <climits>

using namespace std;

const int MAXN = 60;
const int SHIFT = 15;
const int INF = INT_MAX;

int main() {
    string s;
    cin >> s;
    s = "000" + s;
    int n = s.length();

    int dp[MAXN + 1][MAXN + 1][2 * SHIFT + 1];
    int nxt[MAXN + 1][MAXN + 1][2 * SHIFT + 1];

    // Initialize dp with INF
    for (int i = 0; i <= MAXN; ++i)
        for (int j = 0; j <= MAXN; ++j)
            for (int k = 0; k <= 2 * SHIFT; ++k)
                dp[i][j][k] = INF;

    dp[MAXN][MAXN][SHIFT] = 0;

    for (int idx = n - 1; idx >= 0; --idx) {
        int digit = s[idx] - '0';

        // Relaxation step
        for (int plus = MAXN; plus >= 0; --plus) {
            for (int minus = MAXN; minus >= 0; --minus) {
                for (int carry = 0; carry <= 2 * SHIFT; ++carry) {
                    if (plus + 1 <= MAXN)
                        dp[plus][minus][carry] = min(dp[plus][minus][carry], dp[plus + 1][minus][carry]);
                    if (minus + 1 <= MAXN)
                        dp[plus][minus][carry] = min(dp[plus][minus][carry], dp[plus][minus + 1][carry]);
                }
            }
        }

        // Initialize nxt with INF
        for (int i = 0; i <= MAXN; ++i)
            for (int j = 0; j <= MAXN; ++j)
                for (int k = 0; k <= 2 * SHIFT; ++k)
                    nxt[i][j][k] = INF;

        // Transition
        for (int plus = MAXN; plus >= 0; --plus) {
            for (int minus = MAXN; minus >= 0; --minus) {
                for (int carry = 0; carry <= 2 * SHIFT; ++carry) {
                    int val = dp[plus][minus][carry];
                    if (val == INF) continue;
                    int realCarry = carry - SHIFT;
                    int curN = plus - minus + realCarry;
                    int curD = curN % 10;
                    if (curD < 0) curD += 10;
                    int newCarry = (curN - curD) / 10;
                    if (curD != digit) continue;
                    nxt[plus][minus][newCarry + SHIFT] = min(nxt[plus][minus][newCarry + SHIFT], plus + minus + val);
                }
            }
        }

        // Copy nxt to dp
        for (int i = 0; i <= MAXN; ++i)
            for (int j = 0; j <= MAXN; ++j)
                for (int k = 0; k <= 2 * SHIFT; ++k)
                    dp[i][j][k] = nxt[i][j][k];
    }

    int ans = INF;
    for (int i = 0; i <= MAXN; ++i)
        for (int j = 0; j <= MAXN; ++j)
            ans = min(ans, dp[i][j][SHIFT]);

    cout << ans << endl;

    return 0;
}

