const int INF = 1000000;
const int SIZE = 50; // size for pos, neg
const int MAX_INDEX = 17; // number of digits
const int CARRY_SIZE = 100; // 0..99

vector<int> DP(MAX_INDEX * SIZE * SIZE * CARRY_SIZE, -1);
string number;
vector<int> weight(MAX_INDEX);

inline int dp_index(int idx, int pos, int neg, int carry) {
    return ((idx * SIZE + pos) * SIZE + neg) * CARRY_SIZE + carry;
}

int get(int index, int pos, int neg, int carry) {
    int truCarry = carry - 50;
    if (index == 17) {
        return (pos + neg + truCarry == 0) ? 0 : INF;
    }
    int idx = dp_index(index, pos, neg, carry);
    if (DP[idx] != -1)
        return DP[idx];
    int res = INF;
    int digit = number[index] - '0';
    for (int p = 0; p <= min(15, pos); p++) {
        for (int n = 0; n <= min(15, neg); n++) {
            int sum = pos - neg + truCarry;
