            int nextCarry = (sum > 0) ? sum / 10 : (sum - 9) / 10;
            if (currentBit != digit) continue;
            int cost = (p + n) * weight[index];
            res = min(res,
                      get(index + 1, pos - p, neg - n, nextCarry + 50) + cost);
        }
    }
    DP[idx] = res;
    return res;
}

