using namespace std;

typedef long long ll;

struct pair_hash {
    size_t operator()(const pair<ll, int>& p) const {
        return hash<ll>()(p.first) ^ (hash<int>()(p.second) << 1);
    }
};

ll dfsMemo(const ll* ones, ll n, int idx, unordered_map<pair<ll, int>, ll, pair_hash>& memo) {
    if (idx == 0) return 0; // base case, though not reached in practice
    pair<ll, int> key = make_pair(n, idx);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    ll quot = n / ones[idx];
    ll rem = n % ones[idx];
    ll used = quot * idx;
    ll result;
    if (rem == 0) {
        result = used;
    } else {
        ll option1 = dfsMemo(ones, rem, idx - 1, memo);
        ll option2 = idx + dfsMemo(ones, ones[idx] - rem, idx - 1, memo);
        result = used + min(option1, option2);
    }
    memo[key] = result;
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll n;
    cin >> n;

    ll ones[17];
    ones[0] = 0;
    for (int i = 1; i < 17; ++i) {
        ones[i] = 10 * ones[i - 1] + 1;
    }

    unordered_map<pair<ll, int>, ll, pair_hash> memo;
    ll ans = dfsMemo(ones, n, 16, memo);
    cout << ans << endl;

    return 0;
}

