struct Frame {
    long long val;
    int state;
    long long firstAdd;
    long long secondAdd;
    int cnt;
    long long k;
    int firstRes;
    int secondRes; // not used, but for completeness
};

int go(long long n) {
    if (n == 0) return 0;
    std::stack<Frame> st;
    st.push({n, 0, 0, 0, 0, 0, 0, 0});
    int branchResult = 0; // corresponds to results[0] in Java
    while (!st.empty()) {
        Frame cur = st.top();
        st.pop();
        long long val = cur.val;
        int state = cur.state;
        if (state == 0) {
            if (val == 0) {
                st.push({val, 2, 0, 0, 0, 0, 0, 0}); // dummy
                continue;
            }
            long long k = 1;
            int cnt = 1;
            while (k * 10 + 1 < val) {
                k = k * 10 + 1;
                cnt++;
            }
            long long firstArg = val % k;
            long long firstAdd = val / k * cnt;
            long long secondArg = (k * 10 + 1 - val) % k;
            long long secondAdd = (cnt + 1) + (k * 10 + 1 - val) / k * cnt;
            // Push current state to collect results
            st.push({val, 1, firstAdd, secondAdd, cnt, k, 0, 0});
            st.push({firstArg, 0, 0, 0, 0, 0, 0, 0});
        } else if (state == 1) {
            int firstRes = branchResult;
            long long firstAdd = cur.firstAdd;
            long long secondAdd = cur.secondAdd;
            int cnt = cur.cnt;
            long long k = cur.k;
            long long secondArg = (k * 10 + 1 - cur.val) % k;
            // Push to compute second branch
            st.push({cur.val, 2, firstAdd, secondAdd, cnt, k, firstRes, 0});
            st.push({secondArg, 0, 0, 0, 0, 0, 0, 0});
        } else if (state == 2) {
            int firstRes = cur.firstRes;
            int secondRes = branchResult;
            long long firstAdd = cur.firstAdd;
            long long secondAdd = cur.secondAdd;
            int res = std::min(firstRes + firstAdd, secondRes + secondAdd);
            branchResult = res;
        }
    }
    return branchResult;
}

int main() {
    long long n;
    std::cin >> n;
    std::cout << go(n) << std::endl;
    return 0;
}

