#include <bits/stdc++.h>
using namespace std;

class CF1187G {
public:
    CF1187G() {}

    static const int INF = 0x3f3f3f3f;

    // input
    int n, m, k, c, d;
    vector<int> ii;
    vector<vector<int>> orig_adj;

    // flow network
    int n_, m_;
    vector<vector<int>> aa_;
    vector<int> uu, vv, uv, cost, cc;
    vector<int> pi, dd, bb;
    vector<int> qq;
    int nq, head, cnt;
    vector<bool> iq;

    void init() {
        aa_.resize(n_);
        for (int i = 0; i < n_; ++i) aa_[i].clear();
        pi.assign(n_, INF);
        dd.assign(n_, 0);
        bb.assign(n_, 0);
        iq.assign(n_, false);
        // queue will be rebuilt each spfa
        uu.clear();
        vv.clear();
        uv.clear();
        cost.clear();
        cc.clear();
        m_ = 0;
    }

    void link(int u, int v, int cap, int cos) {
        int h = m_++;
        uu.push_back(u);
        vv.push_back(v);
        uv.push_back(u ^ v);
        cost.push_back(cos);
        cc.push_back(cap);   // forward
        cc.push_back(0);     // reverse
        aa_[u].push_back(h << 1);
        aa_[v].push_back(h << 1 | 1);
    }

    void enqueue(int v) {
        if (iq[v]) return;
        // simple queue using vector (circular buffer like Java)
        if (head + cnt == (int)qq.size()) {
            if (cnt * 2 <= (int)qq.size()) {
                for (int i = 0; i < cnt; ++i)
                    qq[i] = qq[head + i];
                head = 0;
            } else {
                int new_size = (int)qq.size() * 2;
                vector<int> qq2(new_size);
                for (int i = 0; i < cnt; ++i)
                    qq2[i] = qq[head + i];
                qq.swap(qq2);
                head = 0;
            }
        }
        qq[head + cnt++] = v;
        iq[v] = true;
    }

    int dequeue() {
        int u = qq[head++];
        cnt--;
        iq[u] = false;
        return u;
    }

    bool spfa(int s, int t) {
        fill(pi.begin(), pi.end(), INF);
        pi[s] = 0;
        dd[s] = 0; // dd is never used before assignment, so ok
        head = cnt = 0;
        if (qq.empty()) qq.resize(1);
        enqueue(s);
        while (cnt > 0) {
            int u = dequeue();
            int d = dd[u] + 1;
            const vector<int>& adj = aa_[u];
            for (int h_ : adj) {
                if (cc[h_] > 0) {
                    int h = h_ >> 1;
                    int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                    int v = u ^ uv[h];
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = h_;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void push1(int s, int t) {
        for (int u = t; u != s; ) {
            int h_ = bb[u];
            int h = h_ >> 1;
            cc[h_]--;
            cc[h_ ^ 1]++;
            u ^= uv[h];
        }
    }

    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int total = 0;
        for (int h = 0; h < m_; ++h)
            total += cost[h] * cc[h << 1 | 1]; // reverse arc capacity = flow sent
        return total;
    }

    int readInt() {
        int x = 0;
        char c = getchar();
        while (c <= 32) c = getchar();
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = getchar();
        }
        return x;
    }

    void solve() {
        n = readInt();
        m = readInt();
        k = readInt();
        c = readInt();
        d = readInt();
        ii.resize(k);
        for (int i = 0; i < k; ++i) {
            ii[i] = readInt() - 1;
        }
        orig_adj.resize(n);
        for (int i = 0; i < m; ++i) {
            int a = readInt() - 1;
            int b = readInt() - 1;
            orig_adj[a].push_back(b);
            orig_adj[b].push_back(a);
        }

        int t = n + k + 1;
        n_ = n * t + 1;
        // allocate maximum edges as in Java
        int max_edges = k + (m * 2 * k + n) * (t - 1);
        uu.reserve(max_edges);
        vv.reserve(max_edges);
        uv.reserve(max_edges);
        cost.reserve(max_edges);
        cc.reserve(2 * max_edges);
        init();

        // edges from original graph
        for (int i = 0; i < n; ++i) {
            const vector<int>& adj = orig_adj[i];
            for (int s = 0; s < t - 1; ++s) {
                int u = i * t + s;
                for (int j : adj) {
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; ++x)
                        link(u, v, 1, c + (2 * x - 1) * d);
                }
            }
        }
        // edges staying in place
        for (int i = 0; i < n; ++i) {
            for (int s = 0; s < t - 1; ++s) {
                int u = i * t + s, v = u + 1;
                link(u, v, k, (i == 0 ? 0 : c));
            }
        }
        // source edges
        for (int h = 0; h < k; ++h)
            link(n_ - 1, ii[h] * t + 0, 1, 0);

        int source = n_ - 1;
        int sink = 0 * t + t - 1;
        printf("%d\n", edmonds_karp(source, sink));
    }
};

int main() {
    CF1187G solver;
    solver.solve();
    return 0;
}

