            int d = dd[u] + 1;
            for (int h_ : adj[u]) {
                if (cap[h_] > 0) {
                    int h = h_ >> 1;
                    int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                    int v = u ^ uv[h];
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = h_;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void push1(int s, int t) {
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            cap[h_]--;
            cap[h_ ^ 1]++;
        }
    }

    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int flow = 0;
        for (int h = 0; h < m; h++)
            flow += cost[h] * cap[h << 1 | 1];
        return flow;
    }

    void solve() {
        string line;
        while (getline(cin, line)) {
            if (line.empty()) continue;
            stringstream ss(line);
            int N, M, K, C, D;
            ss >> N >> M >> K >> C >> D;

            vector<int> start(K);
            getline(cin, line);
            stringstream ss2(line);
            for (int i = 0; i < K; i++)
                ss2 >> start[i];

            vector<vector<int>> graph(N);
            for (int i = 0; i < M; i++) {
                getline(cin, line);
                stringstream ss3(line);
                int a, b;
                ss3 >> a >> b;
                a--; b--;
                graph[a].push_back(b);
                graph[b].push_back(a);
            }

            int T = N + K + 1;
            int max_n = N * T + 1;
            int max_m = K + (M * 2 * K + N) * (T - 1);
            init(max_n, max_m);

            for (int i = 0; i < N; i++) {
                for (int s = 0; s < T - 1; s++) {
                    int u = i * T + s;
                    for (int j : graph[i]) {
                        int v = j * T + s + 1;
                        for (int x = 1; x <= K; x++)
                            link(u, v, 1, C + (x * 2 - 1) * D);
                    }
                }
            }

            for (int i = 0; i < N; i++)
                for (int s = 0; s < T - 1; s++) {
                    int u = i * T + s, v = u + 1;
                    link(u, v, K, i == 0 ? 0 : C);
                }

            for (int h = 0; h < K; h++)
                link(max_n - 1, start[h] * T, 1, 0);

            cout << edmonds_karp(max_n - 1, 0 * T + T - 1) << endl;
        }
    }
};

