        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.flush();out.close();
    }
    static class TaskE {
        class MinCostMaxFlow{
            ArrayList<Edge> al[];
            Edge ja[][]; 
            int d[]; 
            int N , S , T , maxFlow ; int minCost;
            final int gmax = Integer.MAX_VALUE / 100;

            class Edge{
                int u , flow, rid, cost;
                Edge(int a, int b, int c, int d){u = a; flow = b; cost = c; rid = d;}
            }

            void addEdge(int u , int v , int flow , int cost){
                int lu = al[u].size(), lv = al[v].size();
                al[u].add(new Edge(v, flow, cost, lv)); 
                al[v].add(new Edge(u, 0, -cost, lu));   
            }

            void convertToArray(){
                ja = new Edge[N][];
                for(int i = 0; i < N; i++){
                    int sz = al[i].size();
                    ja[i] = new Edge[sz];
                    for(int j = 0; j < sz; j++){
                        ja[i][j] = al[i].get(j);
                    }
                    al[i].clear();
                }
            }

            MinCostMaxFlow(int n , int source , int sink){
                N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
                al = new ArrayList[N];
                d = new int[N];
                for(int i = 0; i < N; i++){
                    al[i] = new ArrayList<>();
                }
            }

            // Binary heap implementation for Dijkstra
            class BinaryHeap {
                int[] heap;
                int[] pos;
                int size;
                BinaryHeap(int n) {
                    heap = new int[n];
                    pos = new int[n];
                    Arrays.fill(pos, -1);
                    size = 0;
                }
                void push(int v, int dist) {
                    if(pos[v] == -1) {
                        pos[v] = size;
                        heap[size] = v;
                        size++;
                    }
                    int i = pos[v];
                    while(i > 0) {
                        int p = (i-1)/2;
                        if(dist[heap[p]] <= dist[v]) break;
                        swap(i, p);
                        i = p;
                    }
                }
                int pop() {
                    int ret = heap[0];
                    size--;
                    heap[0] = heap[size];
                    pos[heap[0]] = 0;
                    int i = 0;
                    while(true) {
                        int left = 2*i+1;
                        int right = 2*i+2;
                        int smallest = i;
                        if(left < size && dist[heap[left]] < dist[heap[smallest]]) smallest = left;
                        if(right < size && dist[heap[right]] < dist[heap[smallest]]) smallest = right;
                        if(smallest == i) break;
                        swap(i, smallest);
                        i = smallest;
                    }
                    pos[ret] = -1;
                    return ret;
                }
                boolean isEmpty() { return size == 0; }
                void swap(int i, int j) {
                    int tmp = heap[i];
                    heap[i] = heap[j];
                    heap[j] = tmp;
                    pos[heap[i]] = i;
                    pos[heap[j]] = j;
                }
            }

            int[] dist, prv, prve, visit;

            boolean dijkstra(){
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, gmax);
                BinaryHeap pq = new BinaryHeap(N);
                pq.push(S, 0);
                dist[S] = 0;
                while(!pq.isEmpty()){
                    int u = pq.pop();
                    visit[u] = 2;
                    for(int i = 0; i < ja[u].length; i++){
                        Edge e = ja[u][i];
                        if(e.flow == 0) continue;
                        int nd = dist[u] + e.cost + d[u] - d[e.u];
                        if(nd < dist[e.u]){
                            if(visit[e.u] == 2) return false;
                            dist[e.u] = nd;
                            prv[e.u] = u;
                            prve[e.u] = i;
                            pq.push(e.u, nd);
                            visit[e.u] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment(){
                int p = T; int min = gmax;
                while(p != 0){
                    int pp = prv[p], pe = prve[p];
                    int val = ja[pp][pe].flow;
                    min = Math.min(min , val);
                    p = pp;
                }
                p = T;
                while(p != 0){
                    int pp = prv[p], pe = prve[p];
                    ja[pp][pe].flow -= min;
                    ja[p][ja[pp][pe].rid].flow += min;
                    p = pp;
                }
                maxFlow += min;
                return min;
            }

            void updPotential(){
                for(int i = 0; i < N; i++){
                    if(visit[i] != 0){
                        d[i] += dist[i] - dist[S];
                    }
                }
            }
            boolean calWithPotential(){
                while(dijkstra()){
                    int min = dist[T] + d[T] - d[S];
                    minCost += min * augment();
                    updPotential();
                }
                return true;   
            }
        }
        int n , m, k, c, d, a[], f[];
       public void solve(int testNumber, InputReader in, PrintWriter out) {
