        a = new int[k + 1]; f = new int[n + 1];
        for(int i = 1; i <= k; i++){
            a[i] = in.nextInt();
            f[a[i]]++;
        }
        for(int i = 1; i <= n; i++){
            if(f[i] == 0)continue;
            ans.addEdge(0 , i , f[i], 0);
        }
        for(int i = 2; i <= n; i++){
            for(int l = 0; l < maxl - 1; l++){
                ans.addEdge(l * n + i , (l + 1) * n + i, k, c);
            }
        }
        for(int i = 1; i <= m; i++){
