            while (cnt > 0) {
                int u = qq[head++]; cnt--; iq[u] = false;
                for (int h_ : aa_[u]) {
                    if (cc[h_] > 0) {
                        int h = h_ >> 1;
                        int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                        int v = u ^ uv[h];
                        if (pi[v] > p) {
                            pi[v] = p;
                            dd[v] = dd[u] + 1;
                            bb[v] = h_;
                            if (!iq[v]) {
                                if (head + cnt == (int)qq.size()) {
                                    vector<int> qq_(qq.size() * 2);
                                    copy(qq.begin() + head, qq.begin() + head + cnt, qq_.begin());
                                    qq = qq_;
                                    head = 0;
                                }
                                qq[head + cnt++] = v; iq[v] = true;
                            }
                        }
                    }
                }
            }
            if (pi[t] == INF) return 0;
            for (int i = 0; i < n_; i++)
                if (pi[i] < INF)
                    potential[i] = pi[i];
            push1(s, t);
        }
        while (dijkstra(s, t))
            push1(s, t);
        int c = 0;
        for (int h = 0; h < m_; h++)
            c += cost[h] * cc[h << 1 ^ 1];
        return c;
    }

    void main() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        vector<int> ii(k);
        for (int h = 0; h < k; h++)
            ii[h] = sc.nextInt() - 1;
        vector<vector<int>> aa(n);
        for (int i = 0; i < n; i++)
            aa[i].clear();
        for (int h = 0; h < m; h++) {
            int i = sc.nextInt() - 1;
            int j = sc.nextInt() - 1;
            aa[i].push_back(j);
            aa[j].push_back(i);
        }
        int t = n + k + 1;
        n_ = n * t + 1;
        m_ = k + (m * 2 * k + n) * (t - 1);
        init();
        for (int i = 0; i < n; i++) {
            vector<int>& adj = aa[i];
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (int j : adj) {
