            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s, v = u + 1;
                link(u, v, k, i == 0 ? 0 : c);
            }
        for (int h = 0; h < k; h++)
            link(n_ - 1, ii[h] * t + 0, 1, 0);
        cout << edmonds_karp(n_ - 1, 0 * t + t - 1) << endl;
    }
};

