#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = LLONG_MAX / 4;

struct Edge {
    int to, rev;
    ll cap, cost;
    Edge(int to, int rev, ll cap, ll cost) : to(to), rev(rev), cap(cap), cost(cost) {}
};

struct MinCostMaxFlow {
    vector<vector<Edge>> graph;
    vector<ll> potential, dist;
    vector<int> prevv, preve;
    int N;

    MinCostMaxFlow(int n) : N(n), graph(n), potential(n, 0), dist(n), prevv(n), preve(n) {}

    void add_edge(int from, int to, ll cap, ll cost) {
        graph[from].emplace_back(to, (int)graph[to].size(), cap, cost);
        graph[to].emplace_back(from, (int)graph[from].size() - 1, 0, -cost);
    }

    pair<ll, ll> min_cost_flow(int s, int t, ll maxf) {
        ll flow = 0, cost = 0;
        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto p = pq.top(); pq.pop();
                int v = p.second;
                if (dist[v] < p.first) continue;
                for (int i = 0; i < (int)graph[v].size(); ++i) {
                    Edge &e = graph[v][i];
                    if (e.cap > 0) {
                        ll nd = dist[v] + e.cost + potential[v] - potential[e.to];
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            pq.push({nd, e.to});
                        }
                    }
                }
            }
            if (dist[t] == INF) break;
            for (int v = 0; v < N; ++v) potential[v] += dist[v];
            ll d = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) {
                d = min(d, graph[prevv[v]][preve[v]].cap);
            }
            flow += d;
            cost += d * potential[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = graph[prevv[v]][preve[v]];
                e.cap -= d;
                graph[v][e.rev].cap += d;
            }
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M, K, C, D;
    cin >> N >> M >> K >> C >> D;

    vector<int> people(K);
    for (int i = 0; i < K; ++i) {
        cin >> people[i];
        --people[i];
    }

    const int amt = 150;
    int src = 0, snk = 1;
    int node_cnt = 2 + N * amt; // time nodes for j=0..amt-1, but we use j=1..amt-1
    MinCostMaxFlow mcmf(node_cnt);

    auto node_id = [&](int node, int time) {
        return 2 + node * amt + time;
    };

    // time chain edges
    for (int i = 0; i < N; ++i) {
        for (int j = 1; j < amt; ++j) {
            if (j > 1) {
                mcmf.add_edge(node_id(i, j-1), node_id(i, j), INF, 0);
            }
        }
    }

    // source to people at time 1
    for (int i = 0; i < K; ++i) {
        mcmf.add_edge(src, node_id(people[i], 1), 1, 0);
    }

    // node 0 to sink at each time
    for (int i = 1; i < amt; ++i) {
        for (int j = 0; j < K; ++j) {
            mcmf.add_edge(node_id(0, i), snk, 1, C * i - C);
        }
    }

    // road edges
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        for (int j = 1; j < amt - 1; ++j) {
            ll prev = 0;
            for (int k = 1; k <= K; ++k) {
                ll cost = D * k * k - prev;
                mcmf.add_edge(node_id(a, j), node_id(b, j+1), 1, cost);
                mcmf.add_edge(node_id(b, j), node_id(a, j+1), 1, cost);
                prev = D * k * k;
            }
        }
    }

    auto res = mcmf.min_cost_flow(src, snk, INF);
    cout << res.second << '\n';

    return 0;
}

