struct Item {
    ll dist;
    int v;
    Item(ll d, int vv) : dist(d), v(vv) {}
    bool operator<(const Item &other) const { return dist < other.dist; }
};

class BinaryHeap {
public:
    vector<Item> heap;
    void add(const Item &e) {
        heap.push_back(e);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[i].dist >= heap[p].dist) break;
            swap(heap[i], heap[p]);
            i = p;
        }
    }
    Item poll() {
        Item result = heap[0];
        Item last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0;
            int n = heap.size();
            while (true) {
                int left = 2 * i + 1;
                int right = 2 * i + 2;
                int smallest = i;
                if (left < n && heap[left].dist < heap[smallest].dist) smallest = left;
                if (right < n && heap[right].dist < heap[smallest].dist) smallest = right;
                if (smallest == i) break;
                swap(heap[i], heap[smallest]);
                i = smallest;
            }
        }
        return result;
    }
    bool isEmpty() const { return heap.empty(); }
};

