        al[u].emplace_back(v, flow, cost, lv);
        al[v].emplace_back(u, 0, -cost, lu);
    }

    void convertToArray() {
        ja.resize(N);
        for (int i = 0; i < N; i++) {
            ja[i] = al[i];
            al[i].clear();
        }
    }

    bool BellmanFord(bool check) {
        fill(d.begin(), d.end(), INF);
        d[0] = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N; j++) {
                for (const Edge& e : ja[j]) {
                    if (e.flow == 0) continue;
                    if (d[j] + e.cost < d[e.to]) {
                        d[e.to] = d[j] + e.cost;
                    }
                }
            }
        }
        if (check) {
            for (int j = 0; j < N; j++) {
                for (const Edge& e : ja[j]) {
                    if (e.flow == 0) continue;
                    if (d[j] + e.cost < d[e.to]) return false;
                }
            }
        }
        return true;
    }

    // SPFA (simple)
    vector<int> node, visit, prv, prve, dist;
    bool simple() {
        node.assign(N, 0);
        visit.assign(N, 0);
        prv.assign(N, -1);
        prve.assign(N, -1);
        dist.assign(N, INF);

        node[0] = S;
        dist[S] = 0;
        int front = 1, back = 0;
        while (front != back) {
            int u = node[back++];
            if (back == N) back = 0;
            int distu = dist[u];
            visit[u] = 2;
            for (int i = 0; i < (int)ja[u].size(); i++) {
                const Edge& e = ja[u][i];
                if (e.flow == 0) continue;
                int cdist = distu + e.cost;
                if (cdist < dist[e.to]) {
                    if (visit[e.to] == 0) {
                        node[front] = e.to;
                        if (++front == N) front = 0;
                    } else if (visit[e.to] == 2) {
                        if (--back == -1) back += N;
                        node[back] = e.to;
                    }
                    visit[e.to] = 1;
                    prve[e.to] = i;
                    prv[e.to] = u;
                    dist[e.to] = cdist;
                }
            }
        }
        return visit[T] != 0;
    }

    bool dijkstra() {
        visit.assign(N, 0);
        prv.assign(N, -1);
        prve.assign(N, -1);
        dist.assign(N, INF);
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        pq.emplace(0, S);
        dist[S] = 0;
        while (!pq.empty()) {
            auto p = pq.top(); pq.pop();
            int du = p.first, u = p.second;
            if (du != dist[u]) continue;
            visit[u] = 2;
            for (int i = 0; i < (int)ja[u].size(); i++) {
                const Edge& e = ja[u][i];
                if (e.flow == 0) continue;
                int cdist = du + (e.cost + d[u] - d[e.to]); // reduced cost
                if (cdist < dist[e.to]) {
                    if (visit[e.to] == 2) return false;
                    pq.emplace(cdist, e.to);
                    dist[e.to] = cdist;
                    prv[e.to] = u;
                    prve[e.to] = i;
                    visit[e.to] = 1;
                }
            }
        }
        return visit[T] != 0;
    }

    int augment() {
        int p = T;
        int minFlow = INF;
        while (p != S) {
            int pp = prv[p], pe = prve[p];
            minFlow = min(minFlow, ja[pp][pe].flow);
            p = pp;
        }
        p = T;
        while (p != S) {
            int pp = prv[p], pe = prve[p];
            ja[pp][pe].flow -= minFlow;
            ja[p][ja[pp][pe].rev].flow += minFlow;
            p = pp;
        }
        maxFlow += minFlow;
        return minFlow;
    }

    bool calSimple() {
        while (simple()) {
            minCost += dist[T] * augment();
        }
        return true;
    }

    void updPotential() {
        for (int i = 0; i < N; i++) {
            if (visit[i] != 0) {
                d[i] += dist[i] - dist[S];
            }
        }
    }

    bool calWithPotential() {
        while (dijkstra()) {
            int min = dist[T] + d[T] - d[S];
            minCost += min * augment();
            updPotential();
        }
        return true;
    }
};

