#include <functional>

using namespace std;

struct Edge {
    int to, rev, flow, cost;
    Edge() {}
    Edge(int t, int f, int c, int r) : to(t), flow(f), cost(c), rev(r) {}
};

class MCMF {
public:
    int N, S, T;
    int maxFlow, minCost;
    const int INF = 21474836; // = Integer.MAX_VALUE/100
    vector<vector<Edge>> g;
    vector<vector<Edge>> mat;
    vector<int> pot;
    vector<int> q;
    vector<int> vis;
    vector<int> prev, preve;
    vector<int> dist;

    MCMF(int n, int s, int t) : N(n), S(s), T(t), maxFlow(0), minCost(0) {
        g.assign(N, vector<Edge>());
        pot.assign(N, 0);
    }

    void addEdge(int u, int v, int flow, int cost) {
        int lu = g[u].size();
        int lv = g[v].size();
        g[u].push_back(Edge(v, flow, cost, lv));
        g[v].push_back(Edge(u, 0, -cost, lu));
    }

    void toArray() {
        mat.assign(N, vector<Edge>());
        for (int i = 0; i < N; i++) {
            mat[i] = g[i];
            g[i].clear();
        }
    }

    bool bellmanFord(bool check) {
        pot.assign(N, 0);
        for (int i = 0; i < N-1; i++) {
            for (int j = 0; j < N; j++) {
                for (const Edge& e : mat[j]) {
                    if (e.flow == 0) continue;
                    if (pot[j] + e.cost < pot[e.to])
                        pot[e.to] = pot[j] + e.cost;
                }
            }
        }
        if (check) {
            for (int j = 0; j < N; j++) {
                for (const Edge& e : mat[j]) {
                    if (e.flow == 0) continue;
                    if (pot[j] + e.cost < pot[e.to]) return false;
                }
            }
        }
        return true;
    }

    bool simple() {
        q.assign(N, 0);
        vis.assign(N, 0);
        prev.assign(N, 0);
        preve.assign(N, 0);
        dist.assign(N, INF);
        dist[S] = 0;
        q[0] = S;
        int front = 1, back = 0;
        while (front != back) {
            int u = q[back++];
            if (back == N) back = 0;
            vis[u] = 2;
            for (int i = 0; i < (int)mat[u].size(); i++) {
                const Edge& e = mat[u][i];
                if (e.flow == 0) continue;
                int nd = dist[u] + e.cost;
                if (nd < dist[e.to]) {
                    if (vis[e.to] == 0) {
                        q[front] = e.to;
                        if (++front == N) front = 0;
                    } else if (vis[e.to] == 2) {
                        if (--back == -1) back += N;
                        q[back] = e.to;
                    }
                    vis[e.to] = 1;
                    preve[e.to] = i;
                    prev[e.to] = u;
                    dist[e.to] = nd;
                }
            }
        }
        return vis[T] != 0;
    }

    bool dijkstra() {
        vis.assign(N, 0);
        prev.assign(N, 0);
        preve.assign(N, 0);
        dist.assign(N, INF);
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        pq.push({0, S});
        dist[S] = 0;
        while (!pq.empty()) {
            pair<int,int> p = pq.top(); pq.pop();
            int d = p.first, u = p.second;
            if (d > dist[u]) continue;
            vis[u] = 2;
            for (int i = 0; i < (int)mat[u].size(); i++) {
                const Edge& e = mat[u][i];
                if (e.flow == 0) continue;
                int nd = d + e.cost + pot[u] - pot[e.to];
                if (nd < dist[e.to]) {
                    if (vis[e.to] == 2) return false;
                    pq.push({nd, e.to});
                    dist[e.to] = nd;
                    prev[e.to] = u;
                    preve[e.to] = i;
                    vis[e.to] = 1;
                }
            }
        }
        return vis[T] != 0;
    }

    int augment() {
        int p = T;
        int min_flow = INF;
        while (p != S) {
            int pp = prev[p], pe = preve[p];
            min_flow = min(min_flow, mat[pp][pe].flow);
            p = pp;
        }
        p = T;
        while (p != S) {
            int pp = prev[p], pe = preve[p];
            mat[pp][pe].flow -= min_flow;
            mat[p][mat[pp][pe].rev].flow += min_flow;
            p = pp;
        }
        maxFlow += min_flow;
        return min_flow;
    }

    bool calSimple() {
        while (simple()) {
            minCost += dist[T] * augment();
        }
        return true;
    }

    void updPot() {
        for (int i = 0; i < N; i++) {
            if (vis[i] != 0) {
                pot[i] += dist[i] - dist[S];
            }
        }
    }

    bool calWithPotential() {
        while (dijkstra()) {
            int min_cost = dist[T] + pot[T] - pot[S];
            minCost += min_cost * augment();
            updPot();
        }
        return true;
    }
};

void solve() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    int maxl = n + k;
    int T = n * maxl;
    MCMF ans(T+1, 0, T);
    vector<int> a(k+1);
    vector<int> f(n+1, 0);
    for (int i = 1; i <= k; i++) {
        cin >> a[i];
        f[a[i]]++;
    }
    for (int i = 1; i <= n; i++) {
        if (f[i] == 0) continue;
        ans.addEdge(0, i, f[i], 0);
    }
    // edges for staying in city i (i != 1) across layers
    for (int i = 2; i <= n; i++) {
        for (int l = 0; l < maxl-1; l++) {
            ans.addEdge(l * n + i, (l+1) * n + i, k, c);
        }
    }
    // movement edges
    for (int i = 1; i <= m; i++) {
        int a, b;
        cin >> a >> b;
        for (int l = 0; l < maxl-1; l++) {
            for (int p = 1; p <= k; p++) {
                if (a != 1)
                    ans.addEdge(l * n + a, (l+1) * n + b, 1, d * (2 * p - 1) + c);
                if (b != 1)
                    ans.addEdge(l * n + b, (l+1) * n + a, 1, d * (2 * p - 1) + c);
            }
        }
    }
    // edges to sink from city 1
    for (int l = 1; l < maxl; l++) {
        ans.addEdge(l * n + 1, T, k, 0);
    }
    ans.toArray();
    ans.calSimple();
    if (ans.maxFlow != k) {
        cout << "BUG" << endl;
    } else {
        cout << ans.minCost << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    solve();
    return 0;
}

