		}
	}

	void run() throws Exception {
		br = new BufferedReader(new InputStreamReader(oj ? System.in : new ByteArrayInputStream(INPUT.getBytes())));
		out = new PrintWriter(System.out);

		long s = System.currentTimeMillis();
		solve();
