// Custom hash map from long long to long long (open addressing)
class LongLongMap {
public:
    vector<ll> keys;
    vector<ll> allocated;
    int scale;
    int rscale;
    int mask;
    int size;
    static const ll NG = 0;

    LongLongMap() : scale(16), rscale(8), mask(15), size(0) {
        allocated.assign(scale, NG);
        keys.resize(scale);
    }

    bool containsKey(ll x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) return true;
            pos = (pos + 1) & mask;
        }
        return false;
    }

    ll get(ll x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) return allocated[pos];
            pos = (pos + 1) & mask;
        }
        return NG;
    }

    ll put(ll x, ll v) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) {
                ll oldval = allocated[pos];
                allocated[pos] = v;
                return oldval;
            }
            pos = (pos + 1) & mask;
        }
        if (size == rscale) {
            resizeAndPut(x, v);
        } else {
            keys[pos] = x;
            allocated[pos] = v;
        }
        size++;
        return 0;
    }

private:
    void resizeAndPut(ll x, ll v) {
        int nscale = scale << 1;
        int nmask = nscale - 1;
        vector<ll> nallocated(nscale, NG);
        vector<ll> nkeys(nscale);
        for (int i = 0; i < scale; i++) {
            if (allocated[i] != NG) {
                ll y = keys[i];
                int pos = h(y) & nmask;
                while (nallocated[pos] != NG)
                    pos = (pos + 1) & nmask;
                nkeys[pos] = y;
                nallocated[pos] = allocated[i];
            }
        }
        {
            int pos = h(x) & nmask;
            while (nallocated[pos] != NG)
                pos = (pos + 1) & nmask;
            nkeys[pos] = x;
            nallocated[pos] = v;
        }
        allocated.swap(nallocated);
        keys.swap(nkeys);
        scale = nscale;
        rscale <<= 1;
        mask = nmask;
    }

    int h(ll x) {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (int)x;
    }
};

