    vector<int> xcums;
    vector<ull> isp;
    int cachelimit;
    LongLongMap picache;
    vector<vector<int>> cumps;
    int FP[8] = {2, 3, 5, 7, 11, 13, 17, 19};
    int M = 8;
    int B = 100;

    MeisselLehmer5(ll n) {
        assert(n >= 4);
        int s = (int)sqrt(n) * B;
        cachelimit = s;
        this->primes = sieveEratosthenes(s);
        int xcums_size = (s >> 6) + 1;
        xcums.assign(xcums_size, 0);
        isp.assign(xcums_size, 0ULL);
        for (int p : this->primes) {
            isp[p >> 6] |= 1ULL << p;
        }
        for (int i = 0; i < xcums_size - 1; i++) {
            xcums[i + 1] = xcums[i] + __builtin_popcountll(isp[i]);
        }

        cumps.resize(M);
        vector<bool> b(1, true);
        int len = 1;
        for (int i = 0; i < M; i++) {
            len *= FP[i];
            vector<bool> c(len, false);
            for (int j = 0; j < FP[i]; j++) {
                copy(b.begin(), b.end(), c.begin() + j * b.size());
            }
            for (int k = 0; k < len; k += FP[i]) {
                c[k] = false;
            }
            cumps[i].resize(len + 1);
            for (int j = 0; j < len; j++) {
                cumps[i][j + 1] = cumps[i][j] + (c[j] ? 1 : 0);
            }
            FP[i] = len;
            b.swap(c);
        }
    }

    ll sqrt(ll n) {
        ll i = max(0LL, (ll)::sqrt(n) - 2);
        while (i * i <= n) i++;
        return i - 1;
    }

    ll cbrt(ll n) {
        ll i = max(0LL, (ll)::cbrt(n) - 2);
        while (i * i * i <= n) i++;
        return i - 1;
    }

    ll pi(ll x) {
