						int last = pos;
						pos = pos + 1 & mask;
						while (allocated[pos] != NG) {
							int lh = h(keys[pos]) & mask;
							if (
									lh <= last && last < pos ||
									pos < lh && lh <= last ||
									last < pos && pos < lh) {
