        if (A > 0 && x <= (ll)primes[A - 1] * primes[A - 1]) {
            return pi(x) - A + 1;
        }
        ll code = (x << 13) | A;
        if (phicache.containsKey(code)) return phicache.get(code);

        ll ret = x;
        for (int i = A - 1; i >= 0; i--)
            ret -= phi(x / primes[i], i);

        if (cachePhi) phicache.put(code, ret);
        return ret;
    }

    ll P2(ll x, int A) {
        int B = (int)pi(sqrt(x));
        ll ret = 0;
        for (int i = A; i < B; i++) {
            ret += pi(x / primes[i]);
        }
        ret -= (ll)(B - A) * (B + A - 1) / 2;
        return ret;
    }

    ll P3(ll x, int A) {
        int C = (int)pi(cbrt(x));
        ll ret = 0;
        for (int i = A; i < C; i++) {
            ll xi = x / primes[i];
            int B = (int)pi(sqrt(xi));
            for (int j = i; j < B; j++) {
                ret += pi(xi / primes[j]) - j;
            }
        }
        return ret;
    }
};

