        ll code = (x << 13) | A;
        auto it = phicache.find(code);
        if (it != phicache.end()) return it->second;

        ll ret = x;
        for (int i = A - 1; i >= 0; i--) {
            ret -= phi(x / primes[i], i);
        }
        if (cachePhi) phicache[code] = ret;
        return ret;
    }

    ll P2(ll x, int A) {
        int B = (int)pi(sqrt(x));
        ll ret = 0;
        for (int i = A; i < B; i++) {
            ret += pi(x / primes[i]);
        }
        ret -= (ll)(B - A) * (B + A - 1) / 2;
        return ret;
    }

    ll P3(ll x, int A) {
        int C = (int)pi(cbrt(x));
        ll ret = 0;
        for (int i = A; i < C; i++) {
            ll xi = x / primes[i];
            int B = (int)pi(sqrt(xi));
            for (int j = i; j < B; j++) {
                ret += pi(xi / primes[j]) - j;
            }
        }
        return ret;
    }
};

void solve() {
    ll n;
    scanf("%lld", &n);
    ll ans = 0;
    MeisselLehmer2 ml(n / 2);
    for (int i = 0; i < (int)primes.size(); i++) {
        ll plus = ml.pi(n / primes[i]) - (i + 1);
        if (plus <= 0) break;
        ans += plus;
    }
    for (int p : primes) {
        if ((ll)p * p * p <= n) {
            ans++;
        } else {
            break;
        }
    }
    printf("%lld\n", ans);
}

int main() {
    solve();
    return 0;
}

