	public static class MeisselLehmer2 {
		int[] primes;
		int[] cump;

		int cachelimit;
		LongHashCounterL picache;
		LongHashCounterL phicache;
		boolean cachePhi = true;

		int[][] cumps;
		int[] FP = {2,3,5,7,11,13,17,19};
		int M = FP.length;

		int B = 100;

		public MeisselLehmer2(long n)
		{
			assert n >= 4;
			picache = new LongHashCounterL();
			phicache = new LongHashCounterL();

			int s = (int)Math.sqrt(n)*B;
			cachelimit = s;
			this.primes = sieveEratosthenes(s);
			cump = new int[cachelimit+1];
			int pidx = 0;
			int pcnt = 0;
			for(int i = 0;i <= cachelimit;i++){
				if(pidx < primes.length && primes[pidx] == i){
					pcnt++;
					pidx++;
				}
				cump[i] = pcnt;
			}

			cumps = new int[M][];
			boolean[] b = {true};
			int len = 1;
			for(int i = 0;i < M;i++){
				len *= FP[i];
				boolean[] c = new boolean[len];
				for(int j = 0;j < FP[i];j++){
					System.arraycopy(b, 0, c, j*b.length, b.length);
