            return pi(x) - A + 1;
        }

        long ret = x;
        for (int i = A - 1; i >= 0; i--)
            ret -= phi(x / primes[i], i);

        return ret;
    }

    private long P2(long x, int A) {
        int B = (int) pi(sqrt(x));
        long ret = 0;
        for (int i = A; i < B; i++) {
            ret += pi(x / primes[i]);
        }
        ret -= (long) (B - A) * (B + A - 1) / 2;
        return ret;
    }

    private long P3(long x, int A) {
