            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    long oldval = allocated[pos];
                    allocated[pos] = v;
                    return oldval;
                }
                pos = pos + 1 & mask;
            }
            if (size == rscale) {
                resizeAndPut(x, v);
            } else {
                keys[pos] = x;
                allocated[pos] = v;
            }
            size++;
            return 0;
        }

        public long inc(long x, long v) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    allocated[pos] += v;
                    return allocated[pos];
                }
                pos = pos + 1 & mask;
            }
            if (size == rscale) {
                resizeAndPut(x, v);
            } else {
                keys[pos] = x;
                allocated[pos] = v;
            }
            size++;
            return v;
        }

