        public boolean containsKey(long x) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos])
                    return true;
                pos = pos + 1 & mask;
            }
            return false;
        }

        public long get(long x) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos])
                    return allocated[pos];
                pos = pos + 1 & mask;
            }
            return NG;
        }

        public long put(long x, long v) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    long oldval = allocated[pos];
                    allocated[pos] = v;
                    return oldval;
                }
                pos = pos + 1 & mask;
            }
            if (size == rscale) {
                resizeAndPut(x, v);
            } else {
                keys[pos] = x;
                allocated[pos] = v;
            }
            size++;
            return 0;
        }

        public long inc(long x, long v) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    allocated[pos] += v;
                    return allocated[pos];
                }
                pos = pos + 1 & mask;
            }
            if (size == rscale) {
                resizeAndPut(x, v);
            } else {
                keys[pos] = x;
                allocated[pos] = v;
            }
            size++;
            return v;
        }

        public boolean remove(long x) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    size--;
                    int last = pos;
                    pos = pos + 1 & mask;
                    while (allocated[pos] != NG) {
                        int lh = h(keys[pos]) & mask;
                        if (lh <= last && last < pos || pos < lh && lh <= last || last < pos && pos < lh) {
                            keys[last] = keys[pos];
                            allocated[last] = allocated[pos];
                            last = pos;
                        }
                        pos = pos + 1 & mask;
                    }
                    keys[last] = 0;
                    allocated[last] = NG;
                    return true;
                }
                pos = pos + 1 & mask;
            }
            return false;
        }

        private void resizeAndPut(long x, long v) {
            int nscale = scale << 1;
            int nrscale = rscale << 1;
