#include <bits/stdc++.h>
using namespace std;

class BigInt {
public:
    static const long long MOD = 998244353;
    long long val;

    BigInt(long long v = 0) : val(v % MOD) {
        if (val < 0) val += MOD;
    }

    BigInt operator+(const BigInt& other) const {
        return BigInt(val + other.val);
    }

    BigInt operator-(const BigInt& other) const {
        return BigInt(val - other.val);
    }

    BigInt operator*(const BigInt& other) const {
        return BigInt(val * other.val % MOD);
    }

    BigInt modPow(BigInt exp) const {
        long long res = 1, base = val;
        while (exp.val > 0) {
            if (exp.val & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp.val >>= 1;
        }
        return BigInt(res);
    }

    BigInt modPow(long long exp) const {
        return modPow(BigInt(exp));
    }

    BigInt subtract(BigInt other) const {
        return *this - other;
    }

    bool operator==(const BigInt& other) const {
        return val == other.val;
    }

    BigInt& operator=(long long v) {
        val = v % MOD;
        if (val < 0) val += MOD;
        return *this;
    }
};

int main() {
    int n, k, l;
    cin >> n >> k >> l;

    vector<BigInt> fac(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = fac[i - 1] * BigInt(i);
    }

    vector<vector<BigInt>> dp(2 * n + 1, vector<BigInt>(2 * n + 2, BigInt(0)));
    dp[0][0] = 1;
    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0) dp[i][j] = dp[i][j] + dp[i - 1][j - 1];
            dp[i][j] = dp[i][j] + (dp[i - 1][j + 1] * BigInt(j + 1));
        }
    }

    BigInt ans = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            ans = ans + (dp[i][j] * dp[2 * n - i][j] * fac[j]);
        }
    }

    BigInt result = BigInt(l) * ans;
    result = result * dp[2 * n][0].modPow(BigInt(BigInt::MOD - 2));
    result = result * BigInt(2 * n + 1).modPow(BigInt(BigInt::MOD - 2));
