const long long MD = 998244353;

long long power(long long a, long long k) {
    if (k == 0) return 1;
    long long p = power(a, k / 2);
    p = p * p % MD;
    if (k % 2 == 1) p = p * a % MD;
    return p;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, l;
    cin >> n >> k >> l;

    // Compute binomial coefficients up to n
    vector<vector<long long>> ch(n + 1, vector<long long>(n + 1, 0));
    ch[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        ch[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            ch[i][j] = (ch[i - 1][j] + ch[i - 1][j - 1]) % MD;
        }
    }

    int size = n + n + 1;
    vector<long long> pp(size, 0), qq(size, 0), aa(size, 0);

    pp[n] = power(2, n);
    for (int i = 0; i < n; i++) {
        for (int j = n + n; j > 0; j--) {
            pp[j] = (pp[j] - pp[j - 1]) % MD;
            if (pp[j] < 0) pp[j] += MD;
        }
    }

    for (int j = 0; j < size; j++) {
        aa[j] = pp[j];
    }

    long long inv2 = (MD + 1) / 2;

    for (int i = 1; i <= n - k; i++) {
        // qq := pp / (2x(1-x))
        // first divide by 2x
        for (int j = 0; j < n + n; j++) {
            qq[j] = pp[j + 1] * inv2 % MD;
        }
        qq[n + n] = 0;

        // then divide by (1-x): multiply by 1 + x + x^2 + ...
        for (int j = 1; j <= n + n; j++) {
            qq[j] = (qq[j] + qq[j - 1]) % MD;
        }

        // pp := qq - pp  (i.e., pp = pp * (1-p)/p)
        for (int j = 0; j < size; j++) {
            pp[j] = (qq[j] - pp[j]) % MD;
            if (pp[j] < 0) pp[j] += MD;
        }

        long long a_coeff = ch[n][i];
        for (int j = 0; j < size; j++) {
            aa[j] = (aa[j] + a_coeff * pp[j]) % MD;
        }
    }

    // integrate: sum over i of aa[i] / (i+1)
    long long ans = 0;
    for (int i = 0; i < size; i++) {
        ans = (ans + aa[i] * power(i + 1, MD - 2)) % MD;
    }
    ans = ans * l % MD;
    ans = (ans + MD) % MD; // ensure non-negative

    cout << ans << '\n';

    return 0;
}

