    return (int)(ab % mod);
}

int pow_mod(int a, int e, int mod) {
    long long res = 1;
    long long base = a % mod;
    while (e > 0) {
        if (e & 1) {
            res = (res * base) % mod;
        }
        base = (base * base) % mod;
        e >>= 1;
    }
    return (int)res;
}

int inv(int a, int mod) {
    int m = mod;
    int r1 = 1, r2 = 0, r3 = 0, r4 = 1;
