#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD = 998244353;
const int MAXN = 2002;
const int MAXF = 4002;

long long cnk[MAXN][MAXN];
long long fact[MAXF];
long long rev[MAXF];
long long deg2[MAXN];

long long bin_pow(long long a, long long b, long long mod) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    // Precompute binomial coefficients
    cnk[0][0] = 1;
    for (int i = 1; i < MAXN; ++i) {
        cnk[0][i] = 1;
        for (int j = 1; j <= i; ++j) {
            cnk[j][i] = (cnk[j-1][i-1] + cnk[j][i-1]) % MOD;
        }
    }

    // Precompute factorials and powers of 2
    fact[0] = 1;
    deg2[0] = 1;
    for (int i = 1; i < MAXF; ++i) {
        fact[i] = fact[i-1] * i % MOD;
    }
