    int n, k;
    long long l;
    cin >> n >> k >> l;
    l %= MOD;

    // Precompute tmp for each i using a separate array
    vector<long long> tmpArr(n + 1, 0);
    for (int i = k; i <= n; ++i) {
        long long tmp = 0;
        for (int s = 0; s <= n - i; ++s) {
            long long term = comb(n - i, s) * pow2[s] % MOD;
            term = term * fact[s + i] % MOD;
            term = term * fact[s + i] % MOD;
            term = term * invFact[2 * (s + i) + 1] % MOD;
            if ((s & 1) == 0) {
                tmp = (tmp + term) % MOD;
            } else {
                tmp = (tmp - term) % MOD;
            }
        }
        tmpArr[i] = tmp;
    }

    long long ans = 0;
    for (int i = k; i <= n; ++i) {
        long long add = comb(n, i) * pow2[i] % MOD * tmpArr[i] % MOD;
        ans = (ans + add) % MOD;
    }
    ans = ans * l % MOD;
    cout << (ans + MOD) % MOD << endl;

    return 0;
}

