const int MD = 998244353;

// Extended Euclidean algorithm to find modular inverse
int inv(int a) {
    int x, y;
    int g = extended_gcd(a, MD, x, y);
    // g should be 1
    x %= MD;
    if (x < 0) x += MD;
    return x;
}

int extended_gcd(int a, int b, int& x, int& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    int x1, y1;
    int g = extended_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

