            long long termA = (dp[j] * j) % MD;
            long long termB = 0;
            if (j > 0) {
                termB = (dp[j - 1] * (n - (j - 1))) % MD;
            }
            ndp[j] = (termA + termB) % MD;
        }
        swap(dp, ndp);
    }

    long long p = 1, ans = 0;
