using namespace std;

const long long MOD = 998244353LL;

// Extended Euclidean algorithm: returns {gcd, x, y} such that a*x + b*y = gcd
array<long long, 3> extended_gcd(long long a, long long b) {
    if (a == 0) return {b, 0, 1};
    auto next = extended_gcd(b % a, a);
    long long tempX = next[1];
    next[1] = next[2] - (b / a) * next[1];
    next[2] = tempX;
    return next;
}

// Modular inverse of a modulo mod (assuming mod is prime)
long long inverse(long long a, long long mod) {
    auto inv = extended_gcd(a, mod);
    if (inv[0] != 1) return 0;
    long long res = inv[1] % mod;
    if (res < 0) res += mod;
    return res;
}

// Compute (a / b) mod mod
long long modFraction(long long a, long long b, long long mod) {
    long long invB = inverse(b, mod);
    if (invB == 0) return -1;
    return (invB * a) % mod;
}

// Positive modulo
long long mod(long long a, long long mod) {
    long long r = a % mod;
    if (r < 0) r += mod;
    return r;
}

int main() {
