        StringTokenizer st = new StringTokenizer(f.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long p = modInverse(m, MOD);
        // Compute Stirling numbers using 1D array (only row k)
        long[] prev = new long[k+1];
        prev[0] = 1;
        for(int i = 1; i <= k; i++){
            long[] cur = new long[k+1];
            for(int j = 1; j <= i; j++){
                cur[j] = (prev[j-1] % MOD) + (j * prev[j]) % MOD;
                cur[j] %= MOD;
            }
            prev = cur;
        }
        long val = 1;
        long ans = 0;
        long prob = 1;
        for(int i = k; i > 0; i--){
            val = (val * (n - (k - i))) % MOD;
            prob = (prob * p) % MOD;
            ans = (ans + ((val * prob) % MOD) * prev[k-i+1]) % MOD;
        }
        System.out.println(ans);
    }

    // Extended Euclidean algorithm for modular inverse
    public static long modInverse(long a, long m){
        long m0 = m, t, q;
        long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m;
