                                long nd = dist[v] + g.cost[e];
                                if (dist[u] > nd) {
                                    dist[u] = nd;
                                    prevv[u] = v;
                                    preve[u] = e;
                                    updated = true;
                                }
                            }
                        }
                    }
                    if (!updated) break;
                }
