class InputReader {
public:
    InputReader(istream &stream) : stream(stream) {}

    string next() {
        while (tokenPos == string::npos || tokenPos >= line.length()) {
            if (!getline(stream, line)) {
                throw runtime_error("Input error");
            }
            tokenPos = 0;
            // Skip leading spaces
            while (tokenPos < line.length() && line[tokenPos] == ' ') {
