            }
        }
        size_t start = tokenPos;
        while (tokenPos < line.length() && line[tokenPos] != ' ') {
            tokenPos++;
        }
        string token = line.substr(start, tokenPos - start);
        // Skip trailing spaces
        while (tokenPos < line.length() && line[tokenPos] == ' ') {
            tokenPos++;
        }
        return token;
    }

