                    if (e.cap > 0 && pot[e.to] > pot[v] + e.cost) {
                        pot[e.to] = pot[v] + e.cost;
                        upd = true;
                    }
                }
            }
            if (!upd) break;
        }

        int total = 0;
        while (true) {
            int[] dist = new int[N];
            Arrays.fill(dist, INF);
            dist[s] = 0;

            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.add(new long[] {0, s});

            while (!pq.isEmpty()) {
                long[] cur = pq.poll();
                int v = (int) cur[1];
                int d = (int) cur[0];
                if (d != dist[v]) continue;
                for (Edge e : g.get(v)) {
                    if (e.cap <= 0) continue;
                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pq.add(new long[] {nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int v = 0; v < N; v++)
                if (dist[v] < INF) pot[v] += dist[v];

            vis = new boolean[N];
            while (true) {
                int f = dfs(s, Integer.MAX_VALUE);
                if (f == 0) break;
                total += f * (pot[t] - pot[s]);
            }
        }
        return total;
    }

    void run() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt() / 2;
