import java.util.stream.*;

public class ll {
    public static void main(String[] args) throws IOException {
        new gg();
    }
}

class gg {
    gg() throws IOException {
        FScanner fs = new FScanner(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = fs.nextInt();
        char[] word = fs.nextLine().toCharArray();
        int[] vals = fs.iarr(n);
        int[] badones = new int[26];
        int m = 0;
        for (int i = 0; i < n / 2; i++) {
            if (word[i] == word[n - i - 1]) {
                badones[word[i] - 'a']++;
                m++;
            }
        }
        OptionalInt opt = IntStream.range(0, 26).filter(i -> badones[i] * 2 > m).findFirst();
        if (!opt.isPresent()) {
            long sum = IntStream.range(0, n / 2)
                .mapToLong(i -> word[i] != word[n - i - 1] ? vals[i] + vals[n - i - 1] : Math.max(vals[i], vals[n - i - 1]))
                .sum();
            pw.println(sum);
        } else {
            int val = opt.getAsInt();
            int others = badones[val] - (m - badones[val]);
            List<Integer> appr = IntStream.range(0, n / 2)
                .filter(i -> word[i] != word[n - i - 1] && word[i] != 'a' + val && word[n - i - 1] != 'a' + val)
                .map(i -> Math.min(vals[i], vals[n - i - 1]))
                .sorted()
                .boxed()
                .collect(Collectors.toList());
            long ans = IntStream.range(0, n / 2)
                .mapToLong(i -> word[i] == word[n - i - 1] ? Math.max(vals[i], vals[n - i - 1]) : vals[i] + vals[n - i - 1])
                .sum();
            for (int i = 0; i < others; i++)
                ans -= appr.get(i);
            pw.println(ans);
        }
        pw.close();
    }
}

class FScanner {
    StringTokenizer st;
    BufferedReader reader;
    FScanner(InputStreamReader isr) throws IOException {
        reader = new BufferedReader(isr);
    }
    String nextLine() throws IOException {
        return reader.readLine();
    }
    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String s = reader.readLine();
            if (s == null) return null;
            st = new StringTokenizer(s);
        }
        return st.nextToken();
    }
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
    int[] iarr(int n) throws IOException {
        int[] mas = new int[n];
        for (int i = 0; i < n; i++) mas[i] = nextInt();
        return mas;
    }
}

