        return (s + x) % n;
    }
    return (s + n - x) % n;
}

int advanceFull(int s, int m, int n) {
    for (int i = n - 1; i > 0; i--) {
        s = advance(s, i, m, n);
    }
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, s;
    long long t;
    cin >> n >> m >> s >> t;
    s--;

    while (t % n != 0) {
        s = advance(s, (int)(t % n), m, n);
        t--;
    }

    long long cant = t / n;
    vector<int> order;
    unordered_map<int, int> seen;

    while (cant > 0 && seen.find(s) == seen.end()) {
        seen[s] = order.size();
        order.push_back(s);
        s = advanceFull(s, m, n);
        cant--;
    }

    if (cant > 0) {
        int start = seen[s];
        long long cycleLen = order.size() - start;
        long long total = cant % cycleLen;
        for (long long i = 0; i < total; i++) {
            s = advanceFull(s, m, n);
        }
    }

    cout << (s + 1) << '\n';
    return 0;
}

