using namespace std;

class InputReader {
public:
    InputReader(istream& stream) : reader(stream) {
        tokenizer = nullptr;
    }

    string next() {
        while (tokenizer == nullptr || !(*tokenizer).hasMoreTokens()) {
            string line;
            getline(reader, line);
            if (line.empty()) continue;
            tokenizer = new StringTokenizer(line);
        }
        return (*tokenizer).nextToken();
    }

    int NextInt() {
        return stoi(next());
    }

    long long NextLong() {
        return stoll(next());
    }

private:
    class StringTokenizer {
    public:
        StringTokenizer(const string& str) : data(str), pos(0) {
            // Delimiters: space, tab, newline, carriage return, form feed, comma
            delimiters = " \t\n\r\f,";
            skipDelimiters();
        }

        bool hasMoreTokens() {
            return pos < data.size();
        }

        string nextToken() {
            if (!hasMoreTokens()) return "";
            size_t start = pos;
            while (pos < data.size() && delimiters.find(data[pos]) == string::npos) {
                ++pos;
            }
            string token = data.substr(start, pos - start);
            skipDelimiters();
            return token;
        }

    private:
        string data;
        size_t pos;
        string delimiters;

        void skipDelimiters() {
            while (pos < data.size() && delimiters.find(data[pos]) != string::npos) {
                ++pos;
            }
        }
    };

    istream& reader;
    StringTokenizer* tokenizer;
};

