        long long q = g / r;
        g %= r;
        long long temp = g;
        g = r;
        r = temp;
        x -= q * y;
        temp = x;
        x = y;
        y = temp;
    }
    // g should be 1
    x %= MOD;
    if (x < 0) x += MOD;
