    ll v = a + b;
    return v < MOD ? v : v - MOD;
}

ll mod_sub(ll a, ll b) {
    ll v = a - b;
    return v < 0 ? v + MOD : v;
}

ll mod_mul(ll a, ll b) {
    return (a * b) % MOD;
}

ll mod_pow(ll a, ll e) {
    ll res = 1;
    while (e > 0) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

ll mod_inv(ll x) {
    return mod_pow(x, MOD - 2);
}

vector<ll> fact, inv_fact;

void ensure_fact(int n) {
    if ((int)fact.size() > n) return;
    int old = fact.size();
    fact.resize(n + 1);
    inv_fact.resize(n + 1);
    if (old == 0) {
        fact[0] = 1;
        old = 1;
    }
    for (int i = old; i <= n; i++) {
        fact[i] = (fact[i-1] * i) % MOD;
    }
    inv_fact[n] = mod_inv(fact[n]);
    for (int i = n; i > old; i--) {
        inv_fact[i-1] = (inv_fact[i] * i) % MOD;
    }
}

ll nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    ensure_fact(n);
    return ((fact[n] * inv_fact[r]) % MOD * inv_fact[n-r]) % MOD;
}

ll small_inv(int n) {
    ensure_fact(n);
    return (inv_fact[n] * fact[n-1]) % MOD;
}

