    static long solve(int n, int m) {
        int max = n + m;
        long[] inv = new long[max + 1];
        for (int i = 1; i <= max; i++) {
            inv[i] = modInv(i);
        }

        long phase = 1;
        for (int i = n; i >= 0; i--) {
            int den = n + m - i;
            if (den == 0) {
                throw new ArrayIndexOutOfBoundsException();
            }
            long ratio = (long) (n - i) * inv[den] % MOD;
            phase = (1 + ratio * phase) % MOD;
        }

        long answer = 0;
        long comb = 1;
        for (int k = 1; k <= n; k++) {
            comb = comb * (n - k + 1) % MOD * inv[k] % MOD;
            long sign = ((k + 1) & 1) == 0 ? 1 : MOD - 1;
            long numPhases = (long) (m + k) * inv[k] % MOD;
            long term = sign * comb % MOD * numPhases % MOD * phase % MOD;
            answer += term;
            if (answer >= MOD) answer -= MOD;
        }

        return answer;
    }

    static long modInv(long a) {
        long g = MOD, x = 0, y = 1;
        for (long r = a; r != 0; ) {
            long q = g / r;
            g %= r;

            long tmp = g;
            g = r;
            r = tmp;

            x -= q * y;

            tmp = x;
            x = y;
            y = tmp;
