        return invFact(n) * fact(n - 1) % MOD;
    }

    long long ncr(int n, int r) {
        if (r < 0 || n < r) return 0;
        return fact(n) * invFact(r) % MOD * invFact(n - r) % MOD;
    }

    long long paritySign(long long k) {
        return (k & 1) == 0 ? 1 : MOD - 1;
    }

    long long add(long long a, long long b) {
        long long v = a + b;
        return v < MOD ? v : v - MOD;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long mult(initializer_list<long long> args) {
        long long r = 1;
        for (long long a : args) {
            r = mult(r, a);
        }
        return r;
    }

    long long div(long long a, long long b) {
        return mult(a, modPow(b % MOD, MOD - 2));
    }

    long long modPow(long long a, long long e) {
        long long r = 1;
        while (e > 0) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }
};

// Fast integer reader (similar to Java's FastScanner)
int readInt() {
    int c;
    do {
        c = getchar();
    } while (c <= ' ' && c != EOF);

    int sign = 1;
    if (c == '-') {
        sign = -1;
        c = getchar();
    }

    int result = 0;
    while (c >= '0' && c <= '9') {
        result = result * 10 + (c - '0');
        c = getchar();
    }
    return result * sign;
}

int main() {
    int n = readInt();
    int m = readInt();

    Mod mod;
    mod.ensureFactorial(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, n - i, mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = mod.div(m + k, k);
        long long term = mod.mult({sign, mod.ncr(n, k), numPhases, phaseSize});
        answer = mod.add(answer, term);
    }

    cout << answer << endl;
    return 0;
}

