import java.util.StringTokenizer;

public class Main {
    static final long MOD = 998244353L;
    static final BigInteger B_MOD = BigInteger.valueOf(MOD);

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        if (n == 0) {
            out.println(0);
            out.close();
            return;
        }

        long harmonic = 0;
        for (int i = 1; i <= n; i++) {
            harmonic += BigInteger.valueOf(i).modInverse(B_MOD).longValue();
            harmonic %= MOD;
        }

        long phase = ((n + m + 1L) % MOD) * BigInteger.valueOf(m + 1L).modInverse(B_MOD).longValue() % MOD;
        long inside = (1 + (m % MOD) * harmonic) % MOD;
        long answer = phase * inside % MOD;

        out.println(answer);
        out.close();
    }
}

