using namespace std;

typedef long long ll;

const ll MOD = 998244353;

struct Arithmetic {
    vector<ll> fact;
    vector<ll> invFact;

    Arithmetic() {
        fact.push_back(1);
        invFact.push_back(1);
    }

    void prepare(int n) {
        while ((int)fact.size() <= n) {
            int len = fact.size();
            fact.push_back(mul(fact[len - 1], len));
        }
        if ((int)invFact.size() <= n) {
            int last = invFact.size() - 1;
            ll fInv = inv(fact[n]);
            int need = n - last;
            vector<ll> temp(need);
            temp[0] = fInv;
            for (int i = 1; i < need; i++) {
                temp[i] = mul(temp[i - 1], n - i + 1);
            }
            for (int i = need - 1; i >= 0; i--) {
                invFact.push_back(temp[i]);
            }
        }
    }

    ll fact(int n) {
        prepare(n);
        return fact[n];
    }

    ll fInv(int n) {
        prepare(n);
        return invFact[n];
    }

    ll ncr(int n, int r) {
        if (r < 0 || r > n) return 0;
        return mul(fact(n), mul(fInv(r), fInv(n - r)));
    }

    ll smallInv(int n) {
        return mul(fInv(n), fact(n - 1));
    }

    ll add(ll a, ll b) {
        ll v = a + b;
        return v >= MOD ? v - MOD : v;
    }

    ll sub(ll a, ll b) {
        ll v = a - b;
        return v < 0 ? v + MOD : v;
    }

    ll mul(ll a, ll b) {
        return a * b % MOD;
    }

    ll inv(ll value) {
        ll g = MOD, x = 0, y = 1;
        ll r = value;
        while (r != 0) {
            ll q = g / r;
            g %= r;
            swap(g, r);
            x -= q * y;
            swap(x, y);
        }
        if (g != 1) assert(false);
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }
};

struct Solver {
    Arithmetic arith;
    int n, m;

