        cin >> n >> m;
        arith.prepare(n + m);

        ll phaseSize = 1;
        ll p = 1;
        for (int i = 0; p != 0; i++) {
            p = arith.mul(arith.mul(p, n - i), arith.smallInv(n + m - i));
            phaseSize = arith.add(phaseSize, p);
        }

        ll answer = 0;
        for (int k = 1; k <= n; k++) {
            ll numPhases = arith.mul(m + k, arith.smallInv(k));
            ll term = arith.mul(arith.ncr(n, k), arith.mul(numPhases, phaseSize));
            if ((k & 1) == 1) answer = arith.add(answer, term);
