    public static void main(String[] args) throws IOException {
        int a = nextInt();
        int b = nextInt();
        int l = nextInt() - 1;
        int r = nextInt() - 1;
        int best = r - l + 1;
        for (char x = 'a'; x <= 'z'; x++) {
            for (char y = 'a'; y <= 'z'; y++) {
                for (char z = 'a'; z <= 'z'; z++) {
                    best = Math.min(best, compute(a, b, l, r, new char[]{x, y, z}));
                }
            }
        }
