public class CF819A {
    static int a, b, ab, l, r, d;

    static int prefixValue(int block, int off) {
        if (off < a - d)
            return off;
        return off + (block % 2 == 0 ? 0 : d);
    }

    static int countDirect(int[] ks) {
        boolean[] used = new boolean[24];
        int cnt = 0;
        for (int i = l; i <= r; i++) {
            int block = i / ab;
            int off = i % ab;
            int val;
            if (off < a)
                val = prefixValue(block, off);
            else
                val = prefixValue(block, a - ks[block]);
            if (!used[val]) {
                used[val] = true;
                cnt++;
            }
        }
        return cnt;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
