        if (h > 2)
            r -= (h - 2) * ab;
        d = a > b ? a - b : 1;

        int min = a + a;
        for (int k0 = 1; k0 <= d; k0++) {
            for (int k1 = 1; k1 <= d; k1++) {
                for (int k2 = 1; k2 <= d; k2++) {
                    for (int k3 = 1; k3 <= d; k3++) {
                        int[] ks = {k0, k1, k2, k3};
                        int cur = countDirect(ks);
                        if (cur < min) min = cur;
                    }
                }
