	public static void main(String... args)
	{
		int a = sc.nextInt();
		int b = sc.nextInt();
		int l = sc.nextInt() - 1;
		int r = sc.nextInt();

		r -= l / (a + b) * (a + b);
		l -= l / (a + b) * (a + b);

		if (r > (a + b) * 3)
		{
			r -= r / (a + b) * (a + b);
			r += (a + b) * 3;
		}

		int[] seq = new int[r];

		for (int i = 0; i < r; i++)
		{
			seq[i] = i;
		}

		{
			int i = a;
			while (i < r)
			{
				if (i % (a + b) < a)
				{
					HashSet<Integer> used = new HashSet<Integer>();
					for (int j = i - 1; i - j <= a; j--)
					{
						used.add(seq[j]);
					}

					for (int j = 0; i % (a + b) != a && i < r; i++, j++)
					{
						while (used.contains(j))
						{
							j++;
						}
						used.add(j);

						seq[i] = j;
					}
				}
				else
				{
					seq[i] = seq[i - 1];
					i++;
				}
			}
		}

		int result;

		{
			HashSet<Integer> used = new HashSet<Integer>();

			for (int i = l; i < r; i++)
			{
				used.add(seq[i]);
			}

			result = used.size();
		}

		for(int i = a; i < a + b && i < r && b < r; i++)
		{
			seq[i] = seq[b];
		}

		{
			int i = a + b;
			while (i < r)
			{
				if (i % (a + b) < a)
				{
					HashSet<Integer> used = new HashSet<Integer>();
					for (int j = i - 1; i - j <= a; j--)
					{
						used.add(seq[j]);
					}

					for (int j = 0; i % (a + b) != a && i < r; i++, j++)
					{
						while (used.contains(j))
						{
							j++;
						}
						used.add(j);

