    int i = start;
    while (i < (int)s.size()) {
        if (i % m < a) {
            vector<bool> used;
            // set bits for the last a indices
            for (int j = i - 1; i - j <= a; j--) {
                int val = s[j];
                if (val >= (int)used.size()) used.resize(val + 1);
                used[val] = true;
            }
            for (int j = 0; i % m != a && i < (int)s.size(); i++, j++) {
                while (j < (int)used.size() && used[j]) j++;
                if (j >= (int)used.size()) used.resize(j + 1);
                used[j] = true;
                s[i] = j;
            }
        } else {
            s[i] = s[i - 1];
            i++;
        }
    }
}

int count(const vector<int>& s, int l, int r) {
    vector<bool> seen;
    for (int i = l; i < r; i++) {
        int val = s[i];
        if (val >= (int)seen.size()) seen.resize(val + 1);
        seen[val] = true;
    }
    int cnt = 0;
    for (bool b : seen) if (b) cnt++;
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int a, b, l, r;
    cin >> a >> b >> l >> r;
    l--; // as in Java: l = sc.nextInt() - 1
    int m = a + b;
    int block = l / m * m;
    l -= block;
    r -= block;

    if (r > 3 * m) {
        r = r % m + 3 * m;
    }

    vector<int> s(r);
    for (int i = 0; i < r; i++) {
        s[i] = i;
    }

    build(s, a, a, b);
    int first = count(s, l, r);

    for (int i = a; i < a + b && i < r && b < r; i++) {
        s[i] = s[b];
    }

    build(s, a + b, a, b);
    int second = count(s, l, r);

    cout << min(first, second) << endl;
    return 0;
}

