int evaluate(string& cString, int a, int b, int first, int second, long long l, long long r) {
    // Append b characters of 'a'+first
    cString.append(b, 'a' + first);

    // Take last a characters
    string sub = cString.substr(cString.length() - a, a);
    set<int> used;
    for (char ch : sub) {
