    for (int i = 0; i < a; i++) {
        rep.push_back('a' + i);
    }
    for (int i = 0; i < b; i++) {
        rep.push_back(p);
    }
    for (int i = 0; i < a; i++) {
        bool seen[26] = {false};
        for (int j = b; j < a + b + i; j++) {
            seen[rep[j] - 'a'] = true;
        }
        for (int c = 0; c < 26; c++) {
            if (!seen[c]) {
                rep.push_back('a' + c);
                break;
            }
        }
    }
    for (int i = 0; i < b; i++) {
        rep.push_back(q);
    }
    return rep;
}

int countLetters(const string& rep, int l, int r) {
    bool flag[26] = {false};
    int len = rep.length();
    if (r - l + 1 >= 100000) {
        for (int i = 0; i < len; i++) {
            flag[rep[i] - 'a'] = true;
        }
    } else {
        for (int i = l; i <= r; i++) {
            flag[rep[i % len] - 'a'] = true;
        }
    }
    int ans = 0;
    for (int i = 0; i < 26; i++) {
        if (flag[i]) ans++;
    }
    return ans;
}

int solve(int a, int b, int l, int r) {
