        int a = (int) st.nval;
        st.nextToken();
        int b = (int) st.nval;
        st.nextToken();
        int l = (int) st.nval;
        st.nextToken();
        int r = (int) st.nval;

        System.out.println(result(a, b, l, r));
    }

    static int result(int a, int b, int l, int r) {
        int p = a + b;

        if (r - l + 1 > 2 * p) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        List<Integer> seq = new ArrayList<>(Collections.nCopies(3 * p + 1, 0));
        int cur = 0;

        for (int i = 1; i <= a; i++) {
            seq.set(i, i);
            cur = i;
        }

        for (int i = a + 1; i <= p; i++) {
            seq.set(i, cur);
        }

        for (int i = p + 1; i <= p + a; i++) {
            int candidate = 1;
            while (contains(seq, candidate, b + 1, i - 1)) {
                candidate++;
            }
            seq.set(i, candidate);
            cur = candidate;
        }

        for (int i = p + a + 1; i <= 2 * p; i++) {
            seq.set(i, cur);
        }

        for (int i = 2 * p + 1; i <= 3 * p; i++) {
            seq.set(i, seq.get(i - p));
        }

        boolean[] used = new boolean[25];
        int start = l % p;
        if (start == 0) start = p;
        int end = r - l + start;
        if (end < start) end += p;

        for (int i = start; i <= end; i++) {
            used[seq.get(i)] = true;
        }

        return IntStream.rangeClosed(1, 24).map(i -> used[i] ? 1 : 0).sum();
